INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88515, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "按照就是照着某个办法或话去做。", "primary_collocate": null, "pronunciation": "àn zhào", "ipa": "an˥˩ ʈʂɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "请按照老师说的办法做。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我按照妈妈的话，早点睡了。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按照书上的方法做了蛋糕。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你按照这个办法试试。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按照地图上的路走。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按照医生说的吃药。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按照说明书把机器打开。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王按照老板的话去了银行。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们按照老师说的站好了。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我按照她告诉我的地址找到了那家店。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "照着别人说的话或给定的办法去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "按照", "is_correct": true, "explanation": "正确：“按照”表示依照老师给的办法去做，符合句意。"}, {"text": "自从", "is_correct": false, "explanation": "语义：“自从”表示从某个时间开始，句中没有时间起点，“请自从……做”不通。"}, {"text": "对于", "is_correct": false, "explanation": "配价：“对于”引出关涉的对象，后面不能接表示依照办法去做的动作。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“老师说的办法”不能作为目的，句意不通。"}], "explanations": {"按照": "正确：“按照”表示依照老师给的办法去做，符合句意。", "自从": "语义：“自从”表示从某个时间开始，句中没有时间起点，“请自从……做”不通。", "对于": "配价：“对于”引出关涉的对象，后面不能接表示依照办法去做的动作。", "为了": "语义：“为了”表示目的，“老师说的办法”不能作为目的，句意不通。"}, "sentence_index": 0, "correct_answer": "按照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他按照面子同意了这件事。", "explanation": "这里应该用〈碍于〉。“按照”要依据规定、办法或标准，“面子”不是依据；因情面而不好拒绝，应该用〈碍于〉。"}, {"text": "我按照她买了一件新衣服。", "explanation": "这里应该用〈替〉。“按照”表示依照别人的话或办法去做，不能表示代人做事，应该说“我替她买了一件新衣服”。"}, {"text": "我按照老师请教问题。", "explanation": "这里应该用〈向〉。“按照”引出依据，“老师”是请教的对象，应该用〈向〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "按照", "is_correct": true, "explanation": "正确：“按照”表示依照说明书去做，符合句意。"}, {"text": "由于", "is_correct": false, "explanation": "语义：“由于”表示原因，句中没有原因，“请由于说明书……”不通。"}, {"text": "关于", "is_correct": false, "explanation": "配价：“关于”引出谈论的话题，不能引出动作所依据的办法。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人做事，“说明书”不能代替人去打开机器，句意不通。"}], "explanations": {"按照": "正确：“按照”表示依照说明书去做，符合句意。", "由于": "语义：“由于”表示原因，句中没有原因，“请由于说明书……”不通。", "关于": "配价：“关于”引出谈论的话题，不能引出动作所依据的办法。", "替": "语义：“替”表示代替某人做事，“说明书”不能代替人去打开机器，句意不通。"}, "sentence_index": 6, "correct_answer": "按照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按照力气搬走了这块石头。", "explanation": "这里应该用〈凭〉。“按照”表示依据规定或标准，“力气”是能力，表示凭借应该用〈凭〉。"}, {"text": "我按照学校出发。", "explanation": "这里应该用〈从〉。“按照”表示依据，不能表示出发的起点，起点要用〈从〉。"}, {"text": "这个小孩按照他的父亲很像。", "explanation": "这里应该用〈跟〉。“按照”表示依照办法去做，不能引出比较的对象，比较要用〈跟〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请按照了医生的建议去做。", "corrected_sentence": "请按照医生的建议去做。", "error_description": "错误：介词“按照”后面不能直接加“了”。正确：“请按照医生的建议去做。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他按照了导游的安排去了博物馆。", "corrected_sentence": "他按照导游的安排去了博物馆。", "error_description": "错误：“按照”后面不能直接加“了”。正确：“了”应附在动词“去”后面，即“他按照导游的安排去了博物馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
