INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88516, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "依照;以某种标准或规定为根据。", "primary_collocate": null, "pronunciation": "àn zhào", "ipa": "an˥˩ ʈʂɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "按照学校的规定，八点前要到校。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按照标准给大家发工资。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛按照规则进行。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照计划，我们明天出发。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照法律，开车不能喝酒。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生按照年级分成三个班。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子按照大小来定价格。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照公司的规定，周末可以休息。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果按照重量来卖。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作按照他们的要求完成了。", "target_word": "按照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "以某种标准、规定或计划为根据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "按照", "is_correct": true, "explanation": "正确：“按照”表示依照学校的规定，符合句意。"}, {"text": "自从", "is_correct": false, "explanation": "语义：“自从”表示时间起点，“学校的规定”不是时间，句意不通。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人做事，“规定”不能代替人做事，句意不通。"}, {"text": "朝", "is_correct": false, "explanation": "配价：“朝”引出动作的方向，“学校的规定”不能作为方向，句意不通。"}], "explanations": {"按照": "正确：“按照”表示依照学校的规定，符合句意。", "自从": "语义：“自从”表示时间起点，“学校的规定”不是时间，句意不通。", "替": "语义：“替”表示代替某人做事，“规定”不能代替人做事，句意不通。", "朝": "配价：“朝”引出动作的方向，“学校的规定”不能作为方向，句意不通。"}, "sentence_index": 0, "correct_answer": "按照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他按照生病，请了一个星期的假。", "explanation": "这里应该用〈因为〉。“按照”表示依据规定或标准，不能表示原因；“生病”是原因，应该用〈因为〉。"}, {"text": "我按照朋友去了一趟北京。", "explanation": "这里应该用〈跟〉。“按照”表示依据，不能引出同行的人，应该说“我跟朋友去了一趟北京”。"}, {"text": "这些水果按照南方运来。", "explanation": "这里应该用〈从〉。“按照”表示依据，不能表示起点，应该说“从南方运来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "按照", "is_correct": true, "explanation": "正确：“按照”表示以大小为依据来定价格，符合句意。"}, {"text": "沿着", "is_correct": false, "explanation": "配价：“沿着”需要路线或方向作宾语，“大小”不能作为路线，句意不通。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“大小”不是定价的目的，句意不通。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”引出对象，“大小”不能作为定价的对象，句意不通。"}], "explanations": {"按照": "正确：“按照”表示以大小为依据来定价格，符合句意。", "沿着": "配价：“沿着”需要路线或方向作宾语，“大小”不能作为路线，句意不通。", "为了": "语义：“为了”表示目的，“大小”不是定价的目的，句意不通。", "向": "配价：“向”引出对象，“大小”不能作为定价的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "按照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我按照她借了一本书。", "explanation": "这里应该用〈向〉。“按照”引出依据，“她”是借书的对象，应该用〈向〉。"}, {"text": "他按照河边走了很久。", "explanation": "这里应该用〈沿着〉。“按照”表示依据或依照，不能表示沿线而行，应该用〈沿着〉。"}, {"text": "我按照妹妹买了一张票。", "explanation": "这里应该用〈替〉。“按照”表示依据，不能表示代替，应该用〈替〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们按照了日程表上课。", "corrected_sentence": "我们按照日程表上课。", "error_description": "错误：介词“按照”后面不能直接加“了”。正确：“我们按照日程表上课。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告按照了老师的要求写好了。", "corrected_sentence": "这份报告按照老师的要求写好了。", "error_description": "错误：“按照”后面不能直接加“了”。正确：“了”应附在动词“写”后面，即“这份报告按照老师的要求写好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
