INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88517, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大员是官职很高的人。", "primary_collocate": null, "pronunciation": "dà yuán", "ipa": "ta˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "皇帝派了一位大员去管理边远的地方。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大员穿着官服，走进了大门。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的那位大员，心地非常善良。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都想见一见这位来自京城的大员。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当大员，所以努力读书考试。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说有一位大员要来检查工作。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大员很忙，每天只睡四个小时。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，大员出行要坐轿子。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大员对百姓说：“大家放心，我会帮你们。”", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座老房子里，住过一位有名的大员。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "钦差大员", "label": "复合"}], "register": "书面", "sense_fingerprint": "官职很高的人；多用于古代或正式场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大员", "is_correct": true, "explanation": "正确：“大员”指官职很高的人，与“皇帝派”“管理边远的地方”相合。"}, {"text": "厨子", "is_correct": false, "explanation": "语义：“厨子”是做饭的人，没有管理边远地方的职权。"}, {"text": "学徒", "is_correct": false, "explanation": "语义：“学徒”是学习手艺的人，不是官员，无法被派去管理地方。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有生命，不能被派去管理地方；量词“位”也只用于人。"}], "explanations": {"大员": "正确：“大员”指官职很高的人，与“皇帝派”“管理边远的地方”相合。", "厨子": "语义：“厨子”是做饭的人，没有管理边远地方的职权。", "学徒": "语义：“学徒”是学习手艺的人，不是官员，无法被派去管理地方。", "石头": "语义：“石头”没有生命，不能被派去管理地方；量词“位”也只用于人。"}, "sentence_index": 0, "correct_answer": "大员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只是个普通的大员，平时很少出门。", "explanation": "这里应该用〈官员〉。大员指官职很高的人，不能用来称呼普通的基层官员。"}, {"text": "那位大员每天早上给病人看病。", "explanation": "这里应该用〈医生〉。大员指官职很高的人，不能用来指给病人看病的医生。"}, {"text": "那个大员每天早起下地干活。", "explanation": "这里应该用〈农民〉。大员指官职很高的人，不能用来指下地干活的农民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大员", "is_correct": true, "explanation": "正确：“大员”指官职很高的人，与“这位”的敬称和“很忙”的语境相合。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“位”只用于人，“书”不能用“这位”修饰，也不能“很忙”。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：“老鼠”是动物，不指人，与“这位”及“很忙、每天只睡四个小时”的人物语境不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有生命，不能“很忙”，也不能“每天只睡四个小时”；量词“位”只用于人。"}], "explanations": {"大员": "正确：“大员”指官职很高的人，与“这位”的敬称和“很忙”的语境相合。", "书": "搭配：量词“位”只用于人，“书”不能用“这位”修饰，也不能“很忙”。", "老鼠": "语义：“老鼠”是动物，不指人，与“这位”及“很忙、每天只睡四个小时”的人物语境不合。", "石头": "语义：“石头”没有生命，不能“很忙”，也不能“每天只睡四个小时”；量词“位”只用于人。"}, "sentence_index": 6, "correct_answer": "大员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐是一名大员，每天在医院给病人打针。", "explanation": "这里应该用〈护士〉。大员指官职很高的人，不能用来指在医院给病人打针的护士。"}, {"text": "我舅舅是一名大员，每天在饭店做菜。", "explanation": "这里应该用〈厨师〉。大员指官职很高的人，不能用来指在饭店做菜的厨师。"}, {"text": "我叔叔是一名大员，每天在学校教数学。", "explanation": "这里应该用〈老师〉。大员指官职很高的人，不能用来指在学校教数学的老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只大员下午来到了村子里。", "corrected_sentence": "那位大员下午来到了村子里。", "error_description": "量词错误：“大员”指人，应用敬称量词“位”；“只”用于动物，应改为“那位大员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位的大员住在城东。", "corrected_sentence": "那位大员住在城东。", "error_description": "多余的“的”：“那位”后面直接接“大员”，中间不能加“的”，应为“那位大员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
