INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "职位较高的官员。", "primary_collocate": null, "pronunciation": "dà yuán", "ipa": "ta˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这位大员昨天来到了我们的城市。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朝时，皇帝派大员去南方查看水灾。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位政府大员正在会议室里讲话。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷曾经是朝廷的大员。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位大员坐在前排，认真听着报告。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大员出门的时候，身边总有很多人跟着。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝很信任这位大员，常常请他商量大事。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大员一生清廉，老百姓都很尊敬他。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在介绍一位古代的大员。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位大员见面后，先握了握手。", "target_word": "大员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "钦差大员", "label": "复合"}], "register": "书面", "sense_fingerprint": "职位较高的官员；多指朝廷或政府的高官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大员", "is_correct": true, "explanation": "正确：“大员”指职位较高的官员，与“这位”的敬称搭配，语境也相合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，“桌子”不能用“这位”修饰。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“行李”。"}, {"text": "猴子", "is_correct": false, "explanation": "语义：“猴子”是动物，不指“这位”所称的人。"}], "explanations": {"大员": "正确：“大员”指职位较高的官员，与“这位”的敬称搭配，语境也相合。", "桌子": "搭配：量词“位”只用于人，“桌子”不能用“这位”修饰。", "行李": "搭配：量词“位”只用于人，不能修饰“行李”。", "猴子": "语义：“猴子”是动物，不指“这位”所称的人。"}, "sentence_index": 0, "correct_answer": "大员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只是一名普通的大员，每天在办公室里写材料。", "explanation": "这里应该用〈官员〉。大员专指职位很高的官员，不能用来形容一般办事的普通官员。"}, {"text": "他在公司当大员，每天负责打印文件。", "explanation": "这里应该用〈职员〉。大员指职位很高的官员，不能用来称呼负责打印文件的普通职员。"}, {"text": "这个班的大员都很努力地读书。", "explanation": "这里应该用〈学生〉。大员专指职位很高的官员，不能用来指班里的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大员", "is_correct": true, "explanation": "正确：“大员”指职位较高的官员，与“信任”“商量大事”的语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有感情，不能被皇帝信任，也不能商量大事。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“位”只用于人，“书”不能用“这位”修饰。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：“老鼠”是动物，不能被皇帝信任，也不能商量大事。"}], "explanations": {"大员": "正确：“大员”指职位较高的官员，与“信任”“商量大事”的语境相合。", "石头": "语义：“石头”没有感情，不能被皇帝信任，也不能商量大事。", "书": "搭配：量词“位”只用于人，“书”不能用“这位”修饰。", "老鼠": "语义：“老鼠”是动物，不能被皇帝信任，也不能商量大事。"}, "sentence_index": 6, "correct_answer": "大员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的表哥是一名出租车大员，每天开车接送乘客。", "explanation": "这里应该用〈司机〉。大员指职位较高的官员，不能用来指每天开车接送乘客的出租车司机。"}, {"text": "我妈妈是一名大员，每天很早就来饭店做菜。", "explanation": "这里应该用〈厨师〉。大员指职位较高的官员，不能用来指每天在饭店做菜的厨师。"}, {"text": "奶奶是一名大员，每天给小朋友讲故事。", "explanation": "这里应该用〈老师〉。大员指职位较高的官员，不能用来指给小朋友讲故事的老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老百姓都很尊敬那只大员。", "corrected_sentence": "老百姓都很尊敬那位大员。", "error_description": "量词错误：“大员”指人，应用敬称量词“位”；“只”用于动物，应改为“那位大员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位的大员在会议上讲了话。", "corrected_sentence": "那位大员在会议上讲了话。", "error_description": "多余的“的”：“那位”后面直接接“大员”，中间不能加“的”，应为“那位大员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "摘", "is_correct": true, "explanation": "摘：把戴在头上、脸上或手上的东西取下来，与“戴”构成反义关系。"}, {"text": "拿", "is_correct": false, "explanation": "拿：用手握住或取得，与“戴”不构成反义关系。"}, {"text": "放", "is_correct": false, "explanation": "放：搁置、安置，与“戴”不构成反义关系。"}, {"text": "送", "is_correct": false, "explanation": "送：把东西给别人，与“戴”不构成反义关系。"}], "correct_answer": "摘", "explanations": {"摘": "摘：把戴在头上、脸上或手上的东西取下来，与“戴”构成反义关系。", "拿": "拿：用手握住或取得，与“戴”不构成反义关系。", "放": "放：搁置、安置，与“戴”不构成反义关系。", "送": "送：把东西给别人，与“戴”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "摘", "is_correct": true, "explanation": "摘：把戴在头上、脸上或手上的东西取下来，与“戴”构成反义关系。"}, {"text": "买", "is_correct": false, "explanation": "买：付钱取得，与“戴”不构成反义关系。"}, {"text": "选", "is_correct": false, "explanation": "选：挑选，与“戴”不构成反义关系。"}, {"text": "找", "is_correct": false, "explanation": "找：寻求、查找，与“戴”不构成反义关系。"}], "correct_answer": "摘", "explanations": {"摘": "摘：把戴在头上、脸上或手上的东西取下来，与“戴”构成反义关系。", "买": "买：付钱取得，与“戴”不构成反义关系。", "选": "选：挑选，与“戴”不构成反义关系。", "找": "找：寻求、查找，与“戴”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "戴是把东西放在头上、脸上或手上。", "primary_collocate": null, "pronunciation": "dài", "ipa": "tai˥˩", "syllable_count": 1, "sentences": [{"text": "他每天都戴帽子。", "target_word": "戴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她脸上戴着一副黑眼镜。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，你要戴手套。", "target_word": "戴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她手上戴了一个红色的戒指。", "target_word": "戴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明在室内也戴着帽子。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生进来时，脸上戴着口罩。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车的时候要戴头盔。", "target_word": "戴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你戴过这种手表吗？", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把新帽子戴在头上。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴着耳机听音乐。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戴着", "label": "着体"}, {"form": "戴了", "label": "了体"}, {"form": "戴过", "label": "过体"}], "register": "中性", "sense_fingerprint": "把帽子、眼镜、戒指等放在头上、脸上或手上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d06d0e-067c-4c11-97ae-a74e588d261c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴（dài）：把东西放在头上、脸上或手上，是本题正确答案。"}, {"text": "太", "is_correct": false, "explanation": "tài（第四声）与 dài 声母不同（t 与 d），意思是“太”，表示程度过分。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dài 韵母不同（没有 -i），意思是“大”。"}, {"text": "呆", "is_correct": false, "explanation": "dāi（第一声）与 dài 声调不同，意思是“呆板、停留”。"}], "explanations": {"戴": "戴（dài）：把东西放在头上、脸上或手上，是本题正确答案。", "太": "tài（第四声）与 dài 声母不同（t 与 d），意思是“太”，表示程度过分。", "大": "dà（第四声）与 dài 韵母不同（没有 -i），意思是“大”。", "呆": "dāi（第一声）与 dài 声调不同，意思是“呆板、停留”。"}, "sentence_index": null, "correct_answer": "戴"}, "level_3": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴：把东西放在头上、脸上或手上，与“他每天都”和“帽子”搭配相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不能用于帽子。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“帽子”不能吃。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球或脚下的物体，不能说“踢帽子”。"}], "explanations": {"戴": "戴：把东西放在头上、脸上或手上，与“他每天都”和“帽子”搭配相符。", "穿": "搭配：“穿”用于衣服、鞋袜，不能用于帽子。", "吃": "语义：“吃”的对象是食物，“帽子”不能吃。", "踢": "搭配：“踢”的对象是球或脚下的物体，不能说“踢帽子”。"}, "sentence_index": 0, "correct_answer": "戴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她今天戴了一件红色的外套。", "explanation": "这里应该用〈穿〉。“戴”用于头、脸、手上的东西，衣服要用“穿”。"}, {"text": "她手上戴了一封信。", "explanation": "这里应该用〈拿〉。“戴”指把东西加在头、脸、手上，信件只能拿。"}, {"text": "门上戴着一把锁。", "explanation": "这里应该用〈挂〉。“戴”指把东西放在头、脸、手上，锁应挂在门上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴（dài）：把东西放在头上、脸上或手上，是本题正确答案。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 dài 声母不同（b 与 d），意思是“拜访、拜”。"}, {"text": "盖", "is_correct": false, "explanation": "gài 与 dài 声母不同（g 与 d），意思是“覆盖、盖子”。"}, {"text": "赖", "is_correct": false, "explanation": "lài 与 dài 声母不同（l 与 d），意思是“依靠、耍赖”。"}], "explanations": {"戴": "戴（dài）：把东西放在头上、脸上或手上，是本题正确答案。", "拜": "bài 与 dài 声母不同（b 与 d），意思是“拜访、拜”。", "盖": "gài 与 dài 声母不同（g 与 d），意思是“覆盖、盖子”。", "赖": "lài 与 dài 声母不同（l 与 d），意思是“依靠、耍赖”。"}, "sentence_index": null, "correct_answer": "戴"}, "level_3": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴：把东西放在头上，与“骑自行车的时候要”和“头盔”相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，“头盔”不能喝。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱头盔”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬头盔会损坏保护用品，与骑车时佩戴头盔的语境相矛盾。"}], "explanations": {"戴": "戴：把东西放在头上，与“骑自行车的时候要”和“头盔”相符。", "喝": "语义：“喝”的对象是液体，“头盔”不能喝。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱头盔”。", "咬": "语义：咬头盔会损坏保护用品，与骑车时佩戴头盔的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "戴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戴着书包上学。", "explanation": "这里应该用〈背〉。“戴”指把东西放在头、脸、手上，书包应背在肩上。"}, {"text": "她戴着一个枕头睡觉。", "explanation": "这里应该用〈抱〉。“戴”指加在头、脸、手上，枕头不能戴。"}, {"text": "他把钥匙戴在桌上。", "explanation": "这里应该用〈放〉。“戴”指把东西放在头、脸、手上，桌上的东西只能放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天冷了，他出门前戴下了帽子。", "corrected_sentence": "天冷了，他出门前戴上了帽子。", "error_description": "错误形式：补语“下”。正确形式：“戴上”。把东西戴到头上、脸上或手上用“戴上”，“戴下”不能这样说；取下来要用“摘下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
