INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88521, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表决是大家举手或投票，决定同意不同意。", "primary_collocate": null, "pronunciation": "biǎo jué", "ipa": "pjɑʊ˨˩˦ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "开会时，大家要表决这个计划。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们举手表决，决定星期六去公园。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不能一个人决定，要大家表决。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今天表决了新的休息办法。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票表决开始了，请大家安静。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先讨论，然后再表决。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员们表决后，法案就通过了。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组用投票的方式表决了活动时间。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表决的结果是十个人同意，两个人反对。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都同意表决这个办法。", "target_word": "表决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表决了", "label": "体标"}, {"form": "表决过", "label": "体标"}, {"form": "表决权", "label": "复合"}, {"form": "表決", "label": "繁体"}], "register": "正式", "sense_fingerprint": "大家举手或投票决定同意与否", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c4b9b2f-50a8-4d73-9791-1b73b884d009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表决", "is_correct": true, "explanation": "表决是大家以举手或投票决定是否同意，开会时表决计划符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱这个计划”说不通，计划不能唱。"}, {"text": "吃", "is_correct": false, "explanation": "语义：计划不能吃，句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不说“打扫这个计划”。"}], "explanations": {"表决": "表决是大家以举手或投票决定是否同意，开会时表决计划符合句意。", "唱": "语义：“唱这个计划”说不通，计划不能唱。", "吃": "语义：计划不能吃，句意不通。", "打扫": "搭配：“打扫”的对象是场所或物品，不说“打扫这个计划”。"}, "sentence_index": 0, "correct_answer": "表决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师表决了我的请求。", "explanation": "这里应该用〈答应〉。老师一个人同意请求用答应；表决是大家投票作决定。"}, {"text": "他表决了这篇作文，给出了很多修改意见。", "explanation": "这里应该用〈批改〉。给作文改错、写批语用批改，表决是大家举手或投票作决定。"}, {"text": "医生表决了病人的病情。", "explanation": "这里应该用〈诊断〉。判断病情要用诊断，表决是对议案的决定方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表决", "is_correct": true, "explanation": "表决是议员们投票决定，之后法案才通过，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步不能使法案通过，与“法案就通过了”没有逻辑联系。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与法案通过没有关系，句意说不通。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”不能引出法案通过的结果，搭配不当。"}], "explanations": {"表决": "表决是议员们投票决定，之后法案才通过，符合句意。", "散步": "语义：散步不能使法案通过，与“法案就通过了”没有逻辑联系。", "吃饭": "语义：吃饭与法案通过没有关系，句意说不通。", "出差": "搭配：“出差”不能引出法案通过的结果，搭配不当。"}, "sentence_index": 6, "correct_answer": "表决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师表决了一个有趣的故事。", "explanation": "这里应该用〈讲〉。讲故事用“讲”，表决只用于对议案表示同意与否。"}, {"text": "他表决了自己的看法。", "explanation": "这里应该用〈发表〉。说出自己的意见用发表，表决只用于对议案作决定。"}, {"text": "会计表决了账目。", "explanation": "这里应该用〈统计〉。核算数字要用统计，表决是对议案的决定方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们正在表决了这个议案，请大家安静。", "corrected_sentence": "他们正在表决这个议案，请大家安静。", "error_description": "错误：“正在表决了”；正确：“正在表决”。“正在”表示动作进行中，不能再用表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都把这个办法表决。", "corrected_sentence": "大家都把这个办法表决了。", "error_description": "错误：“把”字句缺少动词后的成分。“把这个办法表决”不完整，应为“把这个办法表决了”，“了”表示动作完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88523, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卸任", "is_correct": true, "explanation": "与“担任”构成反义：卸任指解除职务，与担任相反。"}, {"text": "参加", "is_correct": false, "explanation": "与“担任”没有反义关系，参加指加入某项活动。"}, {"text": "出席", "is_correct": false, "explanation": "与“担任”没有反义关系，出席指到场参加会议或活动。"}, {"text": "旅行", "is_correct": false, "explanation": "与“担任”没有反义关系，旅行指到外地游览。"}], "correct_answer": "卸任", "explanations": {"卸任": "与“担任”构成反义：卸任指解除职务，与担任相反。", "参加": "与“担任”没有反义关系，参加指加入某项活动。", "出席": "与“担任”没有反义关系，出席指到场参加会议或活动。", "旅行": "与“担任”没有反义关系，旅行指到外地游览。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88523, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卸任", "is_correct": true, "explanation": "与“担任”构成反义：卸任指解除职务，与担任相反。"}, {"text": "游泳", "is_correct": false, "explanation": "与“担任”没有反义关系，游泳指在水中运动。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“担任”没有反义关系，睡觉指休息入睡。"}, {"text": "思考", "is_correct": false, "explanation": "与“担任”没有反义关系，思考指用脑想问题。"}], "correct_answer": "卸任", "explanations": {"卸任": "与“担任”构成反义：卸任指解除职务，与担任相反。", "游泳": "与“担任”没有反义关系，游泳指在水中运动。", "睡觉": "与“担任”没有反义关系，睡觉指休息入睡。", "思考": "与“担任”没有反义关系，思考指用脑想问题。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88523, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担任就是做某个工作,要负责任。", "primary_collocate": null, "pronunciation": "dān rèn", "ipa": "tan˥ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "李老师担任我们班的班主任。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司担任经理已经五年了。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来担任这次活动的负责人？", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王明担任过我们学校的校长。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后担任了一家公司的翻译。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会议由张局长担任主持人。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想担任学生会的主席。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担任队长以后，要对全队负责。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她担任着公司的财务工作。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你担任我们比赛的裁判，好吗？", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担任了", "label": "体标"}, {"form": "担任过", "label": "体标"}, {"form": "担任着", "label": "体标"}, {"form": "擔任", "label": "繁体"}], "register": "书面", "sense_fingerprint": "做某个工作并负起责任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担任", "is_correct": true, "explanation": "正确答案，“担任”表示担当某个职务，填入后符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语法：“睡觉”是不及物动词，不能带“班主任”作宾语。"}, {"text": "跑步", "is_correct": false, "explanation": "语法：“跑步”不能带宾语，句子不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是地方，不能是“班主任”。"}], "explanations": {"担任": "正确答案，“担任”表示担当某个职务，填入后符合句意。", "睡觉": "语法：“睡觉”是不及物动词，不能带“班主任”作宾语。", "跑步": "语法：“跑步”不能带宾语，句子不通。", "打扫": "搭配：“打扫”的对象是地方，不能是“班主任”。"}, "sentence_index": 0, "correct_answer": "担任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该担任责任，认真完成工作。", "explanation": "这里应该用〈承担〉。“担任”用于职务，不能带“责任”作宾语；〈承担〉可以带责任。"}, {"text": "妈妈担任着生活的压力，从不抱怨。", "explanation": "这里应该用〈承受〉。“担任”表示任职，不能带“压力”作宾语；〈承受〉可以带压力。"}, {"text": "学校担任了一场比赛，很多同学参加。", "explanation": "这里应该用〈举办〉。“担任”只用于职务，不能带“比赛”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担任", "is_correct": true, "explanation": "正确答案，“担任”表示担当职务，填入后符合“我想……学生会的主席”的句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语法：“游泳”不能带“主席”作宾语。"}, {"text": "睡觉", "is_correct": false, "explanation": "语法：“睡觉”是不及物动词，不能带宾语。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”需要有审批权的主体，不能用于“我想……学生会的主席”。"}], "explanations": {"担任": "正确答案，“担任”表示担当职务，填入后符合“我想……学生会的主席”的句意。", "游泳": "语法：“游泳”不能带“主席”作宾语。", "睡觉": "语法：“睡觉”是不及物动词，不能带宾语。", "批准": "搭配：“批准”需要有审批权的主体，不能用于“我想……学生会的主席”。"}, "sentence_index": 6, "correct_answer": "担任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他担任着两桶水，慢慢走到井边。", "explanation": "这里应该用〈挑〉。“担任”只表示任职，不表示用肩挑东西；〈挑〉表示用扁担等挑着东西。"}, {"text": "他担任了三年兵，每天训练很累。", "explanation": "这里应该用〈当〉。“担任”表示任职，不能说“担任兵”；“当兵”指服兵役，不是任职。"}, {"text": "他是我们班的担任，很认真地负责。", "explanation": "这里应该用〈负责人〉。“担任”是动词，不能直接当名词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她希望担任了班长。", "corrected_sentence": "她希望担任班长。", "error_description": "“希望”表示打算，后面不能加“了”，应说“希望担任班长”，不说“希望担任了班长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天担任了比赛的裁判。", "corrected_sentence": "他明天担任比赛的裁判。", "error_description": "“明天”表示还没发生，“担任”后面不能加“了”。错误形式是「担任了」，正确形式是「担任」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88524, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卸任", "is_correct": true, "explanation": "与“担任”构成反义：卸任指解除职务，与担任相反。"}, {"text": "游泳", "is_correct": false, "explanation": "与“担任”没有反义关系，游泳指在水中运动。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“担任”没有反义关系，睡觉指休息入睡。"}, {"text": "写字", "is_correct": false, "explanation": "与“担任”没有反义关系，写字指书写文字。"}], "correct_answer": "卸任", "explanations": {"卸任": "与“担任”构成反义：卸任指解除职务，与担任相反。", "游泳": "与“担任”没有反义关系，游泳指在水中运动。", "睡觉": "与“担任”没有反义关系，睡觉指休息入睡。", "写字": "与“担任”没有反义关系，写字指书写文字。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88524, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卸任", "is_correct": true, "explanation": "与“担任”构成反义：卸任指解除职务，与担任相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“担任”没有反义关系，唱歌指发声演唱。"}, {"text": "散步", "is_correct": false, "explanation": "与“担任”没有反义关系，散步指慢慢走路。"}, {"text": "读书", "is_correct": false, "explanation": "与“担任”没有反义关系，读书指阅读书籍。"}], "correct_answer": "卸任", "explanations": {"卸任": "与“担任”构成反义：卸任指解除职务，与担任相反。", "唱歌": "与“担任”没有反义关系，唱歌指发声演唱。", "散步": "与“担任”没有反义关系，散步指慢慢走路。", "读书": "与“担任”没有反义关系，读书指阅读书籍。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88524, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "承担某项职务或工作。", "primary_collocate": null, "pronunciation": "dān rèn", "ipa": "tan˥ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "他在这家医院担任院长。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学时，我担任过班长。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸以前在学校担任数学老师。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行由小李担任导游。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她担任市长已经三年了。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在球队里担任守门员。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他担任小组长。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王教授担任这个项目的总负责人。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她担任着会议的翻译，一点也不紧张。", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你愿意担任我们公司的法律顾问吗？", "target_word": "担任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担任了", "label": "体标"}, {"form": "担任过", "label": "体标"}, {"form": "担任着", "label": "体标"}, {"form": "擔任", "label": "繁体"}], "register": "书面", "sense_fingerprint": "承担某项职务或工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担任", "is_correct": true, "explanation": "正确答案，“担任”表示担当职务，填入后符合“在这家医院担任院长”的句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语法：“睡觉”不能带“院长”作宾语。"}, {"text": "跑步", "is_correct": false, "explanation": "语法：“跑步”不能带宾语。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是地方，不能是“院长”。"}], "explanations": {"担任": "正确答案，“担任”表示担当职务，填入后符合“在这家医院担任院长”的句意。", "睡觉": "语法：“睡觉”不能带“院长”作宾语。", "跑步": "语法：“跑步”不能带宾语。", "打扫": "搭配：“打扫”的对象是地方，不能是“院长”。"}, "sentence_index": 0, "correct_answer": "担任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要担任这个计划，一步一步地做。", "explanation": "这里应该用〈实施〉。“担任”用于职务，不能带“计划”作宾语。"}, {"text": "他担任着很大的压力，每天都很累。", "explanation": "这里应该用〈承受〉。“担任”不能带“压力”作宾语。"}, {"text": "我们担任了一场比赛，大家都很兴奋。", "explanation": "这里应该用〈参加〉。“担任”只用于职务，不能带“比赛”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担任", "is_correct": true, "explanation": "正确答案，“担任”表示担当职务，填入后符合“大家选他……小组长”的句意。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”指不接受，与“大家选他”的情况矛盾。"}, {"text": "辞去", "is_correct": false, "explanation": "语义：“辞去”指离开现任职务，与“选他”的语境不符。"}, {"text": "卸下", "is_correct": false, "explanation": "搭配：“卸下”一般搭配“担子”“重担”，不说卸下职务。"}], "explanations": {"担任": "正确答案，“担任”表示担当职务，填入后符合“大家选他……小组长”的句意。", "拒绝": "语义：“拒绝”指不接受，与“大家选他”的情况矛盾。", "辞去": "语义：“辞去”指离开现任职务，与“选他”的语境不符。", "卸下": "搭配：“卸下”一般搭配“担子”“重担”，不说卸下职务。"}, "sentence_index": 6, "correct_answer": "担任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他担任了朋友一些钱，帮他交房租。", "explanation": "这里应该用〈借〉。“担任”只用于职务，不能带“钱”作宾语；〈借〉可以带钱。"}, {"text": "他担任着一个大箱子，走得很慢。", "explanation": "这里应该用〈扛〉。“担任”只表示任职，不表示用肩搬东西；〈扛〉表示用肩负担重物。"}, {"text": "他愿意担任我的贷款，我很感激。", "explanation": "这里应该用〈担保〉。“担任”表示任职，不能带“贷款”作宾语；〈担保〉可以用于贷款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想担任了社团的负责人。", "corrected_sentence": "他想担任社团的负责人。", "error_description": "“想”表示打算，后面不能加“了”，应说“想担任社团的负责人”，不说“想担任了社团的负责人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她下个月要担任了社团的负责人。", "corrected_sentence": "她下个月要担任社团的负责人。", "error_description": "“下个月要”表示还没发生，“担任”后面不能加“了”。错误形式是「担任了」，正确形式是「担任」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
