INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天体是天上的太阳、月亮和星星。", "primary_collocate": null, "pronunciation": "tiān tǐ", "ipa": "tʰjɛn˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "太阳是天上最亮的天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮是围着地球转的天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里天上有很多天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问我，星星是不是天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学习了天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用眼睛能看到的天体不多。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了一张天体的照片。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳、月亮和星星都是天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天体离我们很远。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把天体画在了本子上。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "天体物理", "label": "复合词"}], "register": "中性", "sense_fingerprint": "天上的太阳、月亮和星星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天体", "is_correct": true, "explanation": "正确答案。太阳是离地球最近的恒星，属于天体。"}, {"text": "动物", "is_correct": false, "explanation": "语义：太阳不是生物，不能说是“动物”。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：太阳不是用来演奏的器具，与句意不符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天上最亮的”后接的是星体，“天空”指空间，不能用来指太阳。"}], "explanations": {"天体": "正确答案。太阳是离地球最近的恒星，属于天体。", "动物": "语义：太阳不是生物，不能说是“动物”。", "乐器": "语义：太阳不是用来演奏的器具，与句意不符。", "天空": "搭配：“天上最亮的”后接的是星体，“天空”指空间，不能用来指太阳。"}, "sentence_index": 0, "correct_answer": "天体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天体很干净，一朵云也没有。", "explanation": "这里应该用〈天空〉。“天体”指太阳、月亮和星星，不指天空本身，所以不能用来形容天空干净。"}, {"text": "今天天体很冷，要多穿衣服。", "explanation": "这里应该用〈天气〉。“天气”描述冷暖晴雨，“天体”是星体，不能用来描述天气。"}, {"text": "老人常说，做好事的人会去天体。", "explanation": "这里应该用〈天堂〉。“天堂”是传说中好人死后的去处，“天体”是宇宙中的星体，不是那个地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天体", "is_correct": true, "explanation": "正确答案。“一张……的照片”指拍下的天体的照片。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不是可以拍成照片的对象。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声是声音，不能拍成照片。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“一张……的照片”要求拍摄对象是可见的事物，“味道”不能拍成照片。"}], "explanations": {"天体": "正确答案。“一张……的照片”指拍下的天体的照片。", "空气": "语义：空气看不见，不是可以拍成照片的对象。", "歌声": "语义：歌声是声音，不能拍成照片。", "味道": "搭配：“一张……的照片”要求拍摄对象是可见的事物，“味道”不能拍成照片。"}, "sentence_index": 6, "correct_answer": "天体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学的专业是天体。", "explanation": "这里应该用〈天文〉。“天文”是研究天体的学科，“天体”指星体本身，不能当作学科名称。"}, {"text": "天体一共有二百多块骨头。", "explanation": "这里应该用〈人体〉。“天体”指宇宙中的星体，没有骨头，说人的身体要用“人体”。"}, {"text": "这个小女孩真像个天体。", "explanation": "这里应该用〈天使〉。“天使”是传说中的神，常用来夸可爱的孩子；“天体”指宇宙中的星体，不能用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台望远镜能看清楚一只天体。", "corrected_sentence": "这台望远镜能看清楚一个天体。", "error_description": "错误：量词用错。“只”多用于动物，天体应该用量词“个”，应说“一个天体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去天文台看了很多天体们。", "corrected_sentence": "他去天文台看了很多天体。", "error_description": "错误：在“天体”后加了复数词尾“们”。“们”一般用于人，天体是事物，应直接说“很多天体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
