INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "宇宙间各种星体的总称，如恒星、行星、卫星。", "primary_collocate": null, "pronunciation": "tiān tǐ", "ipa": "tʰjɛn˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "太阳和月亮都是天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家专门研究天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天体有很多种，比如恒星和行星。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "望远镜可以看到很远的天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天体在宇宙里不停地运动。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球也是一种天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了天体的知识。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天体的大小和远近都不一样。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他晚上用望远镜观察天体。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有很多天体的照片。", "target_word": "天体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "天体运动", "label": "复合词"}], "register": "中性", "sense_fingerprint": "宇宙中恒星、行星、卫星等星体的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天体", "is_correct": true, "explanation": "正确答案。太阳和月亮都属于宇宙中的星体。"}, {"text": "动物", "is_correct": false, "explanation": "语义：太阳和月亮不是生物，不能说是“动物”。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：太阳和月亮不是用来演奏的器具，与“乐器”不符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“都是”后接的是同类的星体，“天空”指空间场所，不能与太阳、月亮并列为同类。"}], "explanations": {"天体": "正确答案。太阳和月亮都属于宇宙中的星体。", "动物": "语义：太阳和月亮不是生物，不能说是“动物”。", "乐器": "语义：太阳和月亮不是用来演奏的器具，与“乐器”不符。", "天空": "搭配：“都是”后接的是同类的星体，“天空”指空间场所，不能与太阳、月亮并列为同类。"}, "sentence_index": 0, "correct_answer": "天体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的天体一片蔚蓝，很漂亮。", "explanation": "这里应该用〈天空〉。“天体”指宇宙中的星体，不指头顶的天空，所以不能说“天体一片蔚蓝”。"}, {"text": "今天天体很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“天气”指晴、雨、冷、热等气候状况，“天体”是星体，不能用来描述天气。"}, {"text": "人们说好人死后会上天体。", "explanation": "这里应该用〈天堂〉。“天堂”是宗教或传说中好人死后的去处，“天体”指宇宙中的星体，不是那个地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天体", "is_correct": true, "explanation": "正确答案。“……的知识”指讲授天体方面的内容。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是身体分泌的液体，不是可以讲授的知识领域。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声是声音，不能作为“知识”的内容。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“……的知识”要接学科或领域，“脚步”不能与“知识”搭配。"}], "explanations": {"天体": "正确答案。“……的知识”指讲授天体方面的内容。", "眼泪": "语义：眼泪是身体分泌的液体，不是可以讲授的知识领域。", "笑声": "语义：笑声是声音，不能作为“知识”的内容。", "脚步": "搭配：“……的知识”要接学科或领域，“脚步”不能与“知识”搭配。"}, "sentence_index": 6, "correct_answer": "天体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的专业是天体，每天在实验室里做研究。", "explanation": "这里应该用〈天文〉。“天文”是研究天体的学科，“天体”指星体本身，不能当作学科名称。"}, {"text": "医生在研究天体的器官。", "explanation": "这里应该用〈人体〉。“天体”指宇宙中的星体，没有器官，研究人的器官要说“人体”。"}, {"text": "秦始皇统一了天体。", "explanation": "这里应该用〈天下〉。“统一天下”是常用说法，“天下”指整个国家或世界；“天体”指宇宙中的星体，不能用来说统一。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位科学家正在研究遥远的天体们。", "corrected_sentence": "这位科学家正在研究遥远的天体。", "error_description": "错误：在“天体”后面加了复数词尾“们”。“们”一般只用于人，天体是事物，应直接说“天体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用望远镜拍下了一只天体。", "corrected_sentence": "他用望远镜拍下了一个天体。", "error_description": "错误：量词用错。“天体”应用量词“个”，不能用“只”（“只”多用于动物等）。应说“拍下了一个天体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
