INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "医生用器械在病人身体上进行的治疗。", "primary_collocate": null, "pronunciation": "shǒu shù", "ipa": "ʂoʊ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "医生说爷爷明天要做手术。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次手术很成功，病人已经醒了。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术做了三个小时。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做完手术以后要休息一个月。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术前，病人不能吃东西。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的手术是一位女医生做的。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做手术的医生很年轻。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很怕手术，所以一直不敢去医院。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这个手术并不太难。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术以后，他的腿慢慢好起来了。", "target_word": "手术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次手术", "label": "量词"}, {"form": "一台手术", "label": "量词"}, {"form": "手术刀", "label": "复合"}], "register": "中性", "sense_fingerprint": "医生用器械给病人做的治疗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88528, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手术", "is_correct": true, "explanation": "正确：手术指医生用器械对病人进行的治疗。"}, {"text": "首饰", "is_correct": false, "explanation": "shì 与 shù 韵母不同（i 与 u），意思是戒指、耳环等装饰品。"}, {"text": "手速", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是打字或操作的速度。"}, {"text": "手书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是亲笔写的信。"}, {"text": "寿数", "is_correct": false, "explanation": "shòu 与 shǒu 声调不同，意思是寿命的长短，多用于书面语。"}], "explanations": {"手术": "正确：手术指医生用器械对病人进行的治疗。", "首饰": "shì 与 shù 韵母不同（i 与 u），意思是戒指、耳环等装饰品。", "手速": "sù 与 shù 声母不同（s 与 sh），意思是打字或操作的速度。", "手书": "shū（第一声）与 shù（第四声）声调不同，意思是亲笔写的信。", "寿数": "shòu 与 shǒu 声调不同，意思是寿命的长短，多用于书面语。"}, "sentence_index": null, "correct_answer": "手术"}, "level_3": {"options": [{"text": "手套", "is_correct": false, "explanation": "语义：“做手套”指制作手套，与医生安排爷爷的治疗不符，句意不通。"}, {"text": "手术", "is_correct": true, "explanation": "正确：“手术”指医生的治疗，符合“医生说爷爷明天要做……”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：爷爷“做作业”与医生说的治疗不符，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试”要说“参加考试”，不说“做考试”。"}], "explanations": {"手套": "语义：“做手套”指制作手套，与医生安排爷爷的治疗不符，句意不通。", "手术": "正确：“手术”指医生的治疗，符合“医生说爷爷明天要做……”。", "作业": "语义：爷爷“做作业”与医生说的治疗不符，句意不通。", "考试": "搭配：“考试”要说“参加考试”，不说“做考试”。"}, "sentence_index": 0, "correct_answer": "手术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上去公园做手术。", "explanation": "这里应该用〈锻炼〉。手术是医生在医院为病人做的医疗操作，不能在公园进行；早上去公园做的是锻炼身体。"}, {"text": "老师每天在教室里给学生做手术。", "explanation": "这里应该用〈上课〉。手术是医生在医院给病人做的治疗，老师在教室里给学生做的是上课。"}, {"text": "我每天晚上去超市做手术。", "explanation": "这里应该用〈购物〉。手术是医生在医院为病人做的医疗操作，不能去超市进行；晚上去超市做的是购物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手表", "is_correct": false, "explanation": "语义：“做手表”的是钟表匠，与句中的“医生”不符。"}, {"text": "手术", "is_correct": true, "explanation": "正确：“做手术的医生”指进行手术的医生，符合句意。"}, {"text": "试卷", "is_correct": false, "explanation": "语义：“做试卷”的不是医生，句意不通。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“病”不能说“做病”，应说“得病”。"}], "explanations": {"手表": "语义：“做手表”的是钟表匠，与句中的“医生”不符。", "手术": "正确：“做手术的医生”指进行手术的医生，符合句意。", "试卷": "语义：“做试卷”的不是医生，句意不通。", "病": "搭配：“病”不能说“做病”，应说“得病”。"}, "sentence_index": 6, "correct_answer": "手术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子昨天做了手术。", "explanation": "这里应该用〈修理〉。手术只用于人的身体，不能用于椅子。"}, {"text": "妈妈把破裤子做了手术。", "explanation": "这里应该用〈缝补〉。手术只用于人体的病变，不能用于衣服。"}, {"text": "这套房子做了手术，很漂亮。", "explanation": "这里应该用〈装修〉。手术只用于人体，不能用于房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈上个月做了一只手术。", "corrected_sentence": "妈妈上个月做了一次手术。", "error_description": "量词错误：“手术”应用“次”或“台”，“只”用于动物，不能用于“手术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷做了过手术。", "corrected_sentence": "爷爷做过手术。", "error_description": "体标错误：“了”与“过”不能同时用在“做”后面。应为“做过手术”，不能说“做了过手术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
