INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88529, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "装修是把新房子里面弄得漂漂亮亮，可以住人。", "primary_collocate": null, "pronunciation": "zhuāng xiū", "ipa": "ʈʂwɑŋ˥ ɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "我们刚买了新房，下个月开始装修。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子装修好以后，我们就搬进去住。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算先装修房子，再买家具。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套新房装修了三个月才能住人。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把新房的客厅装修得明亮一点。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房还没装修，现在不能住人。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请了工人来装修新家。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新家装修完了，朋友都来参观。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说新房装修以后要先通风。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房正在装修，我们暂时住在爸妈家。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "装修了", "label": "体标"}, {"form": "装修过", "label": "体标"}, {"form": "装修公司", "label": "复合"}, {"form": "装修队", "label": "复合"}], "register": "中性", "sense_fingerprint": "把新房子内部弄好以便入住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88529, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "装修", "is_correct": true, "explanation": "“装修”指把新房内部弄好以便入住，与“刚买了新房”前后呼应，符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：新房刚买，下个月就拆除，与“刚买了新房”的情况矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：刚买下新房就“放弃”，与“下个月开始”的常规安排不合，句意不通。"}, {"text": "装配", "is_correct": false, "explanation": "搭配：“装配”多用于机器、零件，不用于新房的内部布置。"}], "explanations": {"装修": "“装修”指把新房内部弄好以便入住，与“刚买了新房”前后呼应，符合句意。", "拆除": "语义：新房刚买，下个月就拆除，与“刚买了新房”的情况矛盾。", "放弃": "语义：刚买下新房就“放弃”，与“下个月开始”的常规安排不合，句意不通。", "装配": "搭配：“装配”多用于机器、零件，不用于新房的内部布置。"}, "sentence_index": 0, "correct_answer": "装修"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在客厅装修了一盏吊灯。", "explanation": "这里应该用〈安装〉。装修指对房屋内部进行整体修整、装饰，不用来指安装一盏灯；把灯具固定好要用“安装”。"}, {"text": "老张去装修了坏掉的热水器。", "explanation": "这里应该用〈修理〉。装修针对房屋内部的修整和装饰，不用于修理热水器等家电。"}, {"text": "政府装修了一座大桥。", "explanation": "这里应该用〈修建〉。装修只用于房屋内部，不能用于大桥这类建筑物的建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装修", "is_correct": true, "explanation": "“装修”指修整、布置新家，与“请了工人”相符，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "语义：请工人的目的不是参观，“请了工人来参观新家”不合常理。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”是卖出，与“请了工人来装修新家”的目的正好相反，句意矛盾。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：房子无法“搬运”，请工人来搬运新家不合常理。"}], "explanations": {"装修": "“装修”指修整、布置新家，与“请了工人”相符，符合句意。", "参观": "语义：请工人的目的不是参观，“请了工人来参观新家”不合常理。", "出售": "语义：“出售”是卖出，与“请了工人来装修新家”的目的正好相反，句意矛盾。", "搬运": "语义：房子无法“搬运”，请工人来搬运新家不合常理。"}, "sentence_index": 6, "correct_answer": "装修"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他装修了破损的凳子。", "explanation": "这里应该用〈修补〉。装修针对房屋内部的整体修整，不用于修补一件家具上的破损。"}, {"text": "车间里，他装修了一台新机器。", "explanation": "这里应该用〈装配〉。装修指对房屋内部进行修整、装饰，组装或安装机器要用“装配”。"}, {"text": "专家装修了这幅古画。", "explanation": "这里应该用〈修复〉。装修是对房屋内部的修整、装饰，不用于修复古画等文物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把新房子装修，下个月就搬进去。", "corrected_sentence": "我们把新房子装修好了，下个月就搬进去。", "error_description": "“把新房子装修”后缺少结果补语，应说“装修好了”。“把”字句中动词后面要有补充成分表示结果，所以错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间房子以前装修了过。", "corrected_sentence": "这间房子以前装修过。", "error_description": "“装修了过”同时用了“了”和“过”，错误。表示曾经做过只说“装修过”，不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
