INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88530, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对房屋内部进行修整、装饰。", "primary_collocate": null, "pronunciation": "zhuāng xiū", "ipa": "ʈʂwɑŋ˥ ɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "这家饭馆明天开始装修，暂停营业。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的老房子去年装修过一次。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把旧厨房重新装修了。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "装修卫生间花了两万块钱。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居在装修，白天很吵。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想把书房装修成日式风格。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店装修得很有特色。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子装修前要先检查水管。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店装修期间，门口贴了通知。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自己动手装修了卧室。", "target_word": "装修", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "装修了", "label": "体标"}, {"form": "装修过", "label": "体标"}, {"form": "装修公司", "label": "复合"}, {"form": "装修队", "label": "复合"}], "register": "中性", "sense_fingerprint": "修整并装饰房屋或店铺的内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "装修", "is_correct": true, "explanation": "“装修”指对房屋内部进行修整，与“暂停营业”的原因相符，符合句意。"}, {"text": "开业", "is_correct": false, "explanation": "语义：“开业”表示开始营业，与后句“暂停营业”矛盾。"}, {"text": "营业", "is_correct": false, "explanation": "语义：“明天开始营业”与“暂停营业”直接矛盾。"}, {"text": "完工", "is_correct": false, "explanation": "体貌：“完工”表示已经结束，与“明天开始”的起点不合。"}], "explanations": {"装修": "“装修”指对房屋内部进行修整，与“暂停营业”的原因相符，符合句意。", "开业": "语义：“开业”表示开始营业，与后句“暂停营业”矛盾。", "营业": "语义：“明天开始营业”与“暂停营业”直接矛盾。", "完工": "体貌：“完工”表示已经结束，与“明天开始”的起点不合。"}, "sentence_index": 0, "correct_answer": "装修"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在墙上装修了一幅画。", "explanation": "这里应该用〈挂〉。装修指对房屋内部进行整体修整、装饰，不用来指在墙上挂一幅画。"}, {"text": "政府装修了一座公园。", "explanation": "这里应该用〈修建〉。装修只用于房屋内部，不能用于公园这类场所的建造。"}, {"text": "他把坏掉的椅子拿去装修了。", "explanation": "这里应该用〈修补〉。装修针对房屋内部的修整，不用于修补椅子等家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装修", "is_correct": true, "explanation": "“装修”指对房屋内部进行修整、装饰，与“有特色”的描述相符，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对损坏的东西，这家店不是坏了，与“很有特色”的说法不搭。"}, {"text": "清洁", "is_correct": false, "explanation": "搭配：“清洁”侧重卫生，“有特色”一般用于装修、设计、风格，不说“清洁得很有特色”。"}, {"text": "搬迁", "is_correct": false, "explanation": "语义：“搬迁”指换地方，与“很有特色”描述的外观和风格无关。"}], "explanations": {"装修": "“装修”指对房屋内部进行修整、装饰，与“有特色”的描述相符，符合句意。", "修理": "语义：“修理”针对损坏的东西，这家店不是坏了，与“很有特色”的说法不搭。", "清洁": "搭配：“清洁”侧重卫生，“有特色”一般用于装修、设计、风格，不说“清洁得很有特色”。", "搬迁": "语义：“搬迁”指换地方，与“很有特色”描述的外观和风格无关。"}, "sentence_index": 6, "correct_answer": "装修"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这盒茶叶精心装修了一番。", "explanation": "这里应该用〈装潢〉。装修指对房屋内部进行修整、装饰，不用于茶叶礼盒；包装的美化设计要用“装潢”。"}, {"text": "博物馆装修了一件古瓷器。", "explanation": "这里应该用〈修复〉。装修是对房屋内部的修整和装饰，不用于修复古瓷器等文物。"}, {"text": "妈妈装修了脏衣服。", "explanation": "这里应该用〈清洗〉。装修针对房屋内部，不用于洗涤衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间茶馆去年装修了过，现在很有名。", "corrected_sentence": "这间茶馆去年装修过，现在很有名。", "error_description": "“装修了过”同时用了“了”和“过”，错误。表示曾经做过只说“装修过”，不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把厨房装修，马上就开业。", "corrected_sentence": "他们把厨房装修好了，马上就开业。", "error_description": "“把厨房装修”后缺少结果补语，应说“装修好了”。“把”字句中动词后面要有补充成分表示结果，所以错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
