INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88531, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文学是用文字写成的故事、诗和文章。", "primary_collocate": null, "pronunciation": "wén xué", "ipa": "wən˧˥ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "我很喜欢看中国文学。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最喜欢的是俄国文学，尤其是小说。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套丛书收录了很多外国文学。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都读一点文学。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文学里有故事，也有诗。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了古代文学。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不爱读文学，只爱看电影。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店左边的书是文学，右边的是历史。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把中国文学介绍给外国朋友。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你对文学很有兴趣？", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文學", "label": "繁体"}, {"form": "文学家", "label": "复合"}, {"form": "文学作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "用文字写成的故事、诗和文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文学", "is_correct": true, "explanation": "文学：指用文字写成的作品，“看中国文学”搭配自然。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“歌曲”一般用“听”，不用“看”。"}, {"text": "茶叶", "is_correct": false, "explanation": "搭配：“茶叶”不是用“看”来欣赏的对象。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不是可以欣赏的文艺内容。"}], "explanations": {"文学": "文学：指用文字写成的作品，“看中国文学”搭配自然。", "歌曲": "搭配：“歌曲”一般用“听”，不用“看”。", "茶叶": "搭配：“茶叶”不是用“看”来欣赏的对象。", "桌子": "语义：“桌子”是家具，不是可以欣赏的文艺内容。"}, "sentence_index": 0, "correct_answer": "文学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去图书馆借了一本文学。", "explanation": "“文学”是一类作品的体裁，不能直接用“本”计数，应说“一本文学书”。"}, {"text": "这封信的文学写得很清楚。", "explanation": "这里应该用〈文字〉。“文学”指用文字写成的作品，说信的表达要用“文字”。"}, {"text": "他是一位很有名的文学。", "explanation": "这里应该用〈作家〉。“文学”是作品的体裁，不能指人，指人要说“作家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文学", "is_correct": true, "explanation": "文学：指文字作品，与“读”搭配，符合句意。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“游戏”用“玩”，不用“读”。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“音乐”用“听”，不用“读”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是可以阅读的内容。"}], "explanations": {"文学": "文学：指文字作品，与“读”搭配，符合句意。", "游戏": "搭配：“游戏”用“玩”，不用“读”。", "音乐": "搭配：“音乐”用“听”，不用“读”。", "石头": "语义：“石头”不是可以阅读的内容。"}, "sentence_index": 6, "correct_answer": "文学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文学很感人，我读哭了。", "explanation": "这里应该用〈文章〉。“文学”是一类作品的总称，不能用“篇”计量单篇作品。"}, {"text": "这首歌的文学很好听。", "explanation": "这里应该用〈歌词〉。“文学”指文字作品，歌的文字应该说“歌词”。"}, {"text": "这位作家的文学很流畅，读者都很喜欢他的书。", "explanation": "这里应该用〈文笔〉。“文学”指作品体裁，描述写作的流畅要用“文笔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写的文学们很多。", "corrected_sentence": "他写的文学作品很多。", "error_description": "错误：“文学”指文学作品这一类，是不可数的抽象名词，不能加复数后缀“们”。正确：“文学作品很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我最近在读一个俄国文学。", "corrected_sentence": "我最近在读俄国文学。", "error_description": "错误：“文学”是抽象的体裁名词，不能用个体量词“个”计量，应去掉“一个”。正确：“我最近在读俄国文学。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
