INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以语言文字为工具,塑造形象、反映生活的艺术,包括诗歌、小说、散文等。", "primary_collocate": null, "pronunciation": "wén xué", "ipa": "wən˧˥ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "文学是一种用语言创造的艺术。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的文学能让人看到生活。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗歌和小说都属于文学。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一生的时间研究文学。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文学和音乐一样，都是艺术。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教我们怎么欣赏文学。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文学能反映一个时代的生活。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就爱好文学，后来写了小说。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代文学比古代文学更接近生活。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟喜欢音乐，不太喜欢文学。", "target_word": "文学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文學", "label": "繁体"}, {"form": "文学家", "label": "复合"}, {"form": "文学作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "用语言塑造形象、反映生活的一门艺术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文学", "is_correct": true, "explanation": "文学：以语言为工具塑造形象的艺术，与“用语言创造”相符。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”靠声音表达，不是用语言创造的艺术。"}, {"text": "绘画", "is_correct": false, "explanation": "搭配：“绘画”用颜料和线条，不能说“用语言”创造。"}, {"text": "雕塑", "is_correct": false, "explanation": "语义：“雕塑”用材料造型，与“用语言创造”不合。"}], "explanations": {"文学": "文学：以语言为工具塑造形象的艺术，与“用语言创造”相符。", "音乐": "语义：“音乐”靠声音表达，不是用语言创造的艺术。", "绘画": "搭配：“绘画”用颜料和线条，不能说“用语言”创造。", "雕塑": "语义：“雕塑”用材料造型，与“用语言创造”不合。"}, "sentence_index": 0, "correct_answer": "文学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只文学，放在书架上。", "explanation": "“文学”是抽象的艺术，不能用“只”计量；应说“一部文学作品”。"}, {"text": "他用一生的时间写了一篇文学，很有名。", "explanation": "这里应该用〈作品〉。“文学”是艺术门类，不能用“篇”计量。"}, {"text": "这首诗的文学写得很好，我很喜欢。", "explanation": "这里应该用〈文字〉。“文学”指作品体裁，描述写作水平要用“文字”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文学", "is_correct": true, "explanation": "文学：以语言塑造形象、反映生活的艺术，与句意相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是工具，不能反映一个时代的生活。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：“水杯”是日用品，与“反映生活”的意思不合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“反映生活”的主语多为作品或报道，“石头”不能作此主语。"}], "explanations": {"文学": "文学：以语言塑造形象、反映生活的艺术，与句意相符。", "电脑": "语义：“电脑”是工具，不能反映一个时代的生活。", "水杯": "语义：“水杯”是日用品，与“反映生活”的意思不合。", "石头": "搭配：“反映生活”的主语多为作品或报道，“石头”不能作此主语。"}, "sentence_index": 6, "correct_answer": "文学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟买了三台文学，放在书桌上。", "explanation": "“文学”是抽象的艺术，不能用“台”计量；说“三部文学作品”更合适。"}, {"text": "这篇小说的文学很精彩，大家都在读。", "explanation": "这里应该用〈文笔〉。“文学”指作品体裁，描述写作的好坏要用“文笔”。"}, {"text": "这首歌的文学很动人，大家都在唱。", "explanation": "这里应该用〈歌词〉。“文学”指文字作品，歌的文字应该说“歌词”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小说和散文都是很重要的文学们。", "corrected_sentence": "小说和散文都是很重要的文学。", "error_description": "错误：“文学们”。正确：“文学”。“文学”是表示艺术门类的抽象名词，不能加复数后缀“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很喜欢现代文学的。", "corrected_sentence": "他很喜欢现代文学。", "error_description": "错误：宾语“现代文学”后多出句末“的”，此处不成立。正确：“他很喜欢现代文学。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
