INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88535, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "托是用手掌在下面撑着东西。", "primary_collocate": null, "pronunciation": "tuō", "ipa": "tʰwo˥˥", "syllable_count": 1, "sentences": [{"text": "他用手托着一杯热茶。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员一只手托着盘子。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她累了，用手托着下巴。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈轻轻托住小宝宝的头。", "target_word": "托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把小鸟托在手心里。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用手托起地上的小猫。", "target_word": "托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你托好盘子，别让汤洒了。", "target_word": "托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸托着我，让我够到苹果。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她托着一碗面，慢慢走过来。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一手托着书，一手写字。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "托着", "label": "体标"}, {"form": "托了", "label": "体标"}, {"form": "托举", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手掌从下面撑着、端着东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ed2684-d9cf-47cd-bea6-80ea625cf249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88535, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "托", "is_correct": true, "explanation": "托 tuō 为第一声，意思是用手掌从下面撑着。"}, {"text": "驼", "is_correct": false, "explanation": "驼 tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。"}, {"text": "妥", "is_correct": false, "explanation": "妥 tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。"}, {"text": "拓", "is_correct": false, "explanation": "拓 tuò（第四声）与 tuō（第一声）声调不同，意思是开拓。"}, {"text": "多", "is_correct": false, "explanation": "多 duō 声母为 d 而不是 t，意思是数量大。"}, {"text": "挪", "is_correct": false, "explanation": "挪 nuó 声母为 n，声调也不同，意思是移动。"}, {"text": "夺", "is_correct": false, "explanation": "夺 duó 声母为 d，声调为第二声，意思是抢夺。"}], "explanations": {"托": "托 tuō 为第一声，意思是用手掌从下面撑着。", "驼": "驼 tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。", "妥": "妥 tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。", "拓": "拓 tuò（第四声）与 tuō（第一声）声调不同，意思是开拓。", "多": "多 duō 声母为 d 而不是 t，意思是数量大。", "挪": "挪 nuó 声母为 n，声调也不同，意思是移动。", "夺": "夺 duó 声母为 d，声调为第二声，意思是抢夺。"}, "sentence_index": null, "correct_answer": "托"}, "level_3": {"options": [{"text": "托", "is_correct": true, "explanation": "正确：“托”表示手掌在下面撑着，符合“用手托着一杯热茶”。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”要用嘴，不能说用手喝。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛出去，与端着热茶的动作矛盾。"}, {"text": "泼", "is_correct": false, "explanation": "语义：“泼”是把液体倒出去，不是托着杯子。"}], "explanations": {"托": "正确：“托”表示手掌在下面撑着，符合“用手托着一杯热茶”。", "喝": "配价：“喝”要用嘴，不能说用手喝。", "扔": "语义：“扔”是抛出去，与端着热茶的动作矛盾。", "泼": "语义：“泼”是把液体倒出去，不是托着杯子。"}, "sentence_index": 0, "correct_answer": "托"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她托着孩子的手过马路。", "explanation": "这里应该用〈牵〉。托是用手掌在下面撑着，拉着孩子的手走路要说牵。"}, {"text": "他托着一把伞走进雨里。", "explanation": "这里应该用〈撑〉。托是用手掌在下面撑住东西，雨伞要握住伞柄举在头顶，应说撑。"}, {"text": "他托着两桶水走了很远。", "explanation": "这里应该用〈提〉。托是手掌在下面撑住东西，两桶水要用手拎着，应说提。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88535, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "托", "is_correct": true, "explanation": "托 tuō 为第一声，意思是用手掌从下面撑着。"}, {"text": "唾", "is_correct": false, "explanation": "唾 tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}, {"text": "诺", "is_correct": false, "explanation": "诺 nuò 声母为 n，声调也不同，意思是承诺。"}, {"text": "跺", "is_correct": false, "explanation": "跺 duò 声母为 d，声调为第四声，意思是用脚重重踏地。"}, {"text": "陀", "is_correct": false, "explanation": "陀 tuó（第二声）与 tuō（第一声）声调不同，如陀螺。"}, {"text": "椭", "is_correct": false, "explanation": "椭 tuǒ（第三声）与 tuō（第一声）声调不同，如椭圆。"}], "explanations": {"托": "托 tuō 为第一声，意思是用手掌从下面撑着。", "唾": "唾 tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。", "诺": "诺 nuò 声母为 n，声调也不同，意思是承诺。", "跺": "跺 duò 声母为 d，声调为第四声，意思是用脚重重踏地。", "陀": "陀 tuó（第二声）与 tuō（第一声）声调不同，如陀螺。", "椭": "椭 tuǒ（第三声）与 tuō（第一声）声调不同，如椭圆。"}, "sentence_index": null, "correct_answer": "托"}, "level_3": {"options": [{"text": "托", "is_correct": true, "explanation": "正确：“托好”表示用手掌托稳，符合“你托好盘子”。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不说穿盘子。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”会使盘子掉落，与“别让汤洒了”的稳当要求相反。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”指挂在墙上或钩子上，不用于端着盘子。"}], "explanations": {"托": "正确：“托好”表示用手掌托稳，符合“你托好盘子”。", "穿": "搭配：“穿”用于衣服、鞋袜，不说穿盘子。", "摔": "语义：“摔”会使盘子掉落，与“别让汤洒了”的稳当要求相反。", "挂": "搭配：“挂”指挂在墙上或钩子上，不用于端着盘子。"}, "sentence_index": 6, "correct_answer": "托"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他托着行李箱的拉杆走出机场。", "explanation": "这里应该用〈拉〉。托是手掌在下面撑住东西，拉着拉杆走要说拉。"}, {"text": "他把书托在腋下，急匆匆地走了。", "explanation": "这里应该用〈夹〉。托是手掌撑住东西，夹在腋下要说夹。"}, {"text": "他托着一个大背包爬上了山。", "explanation": "这里应该用〈背〉。大背包要背在背上，托在手里不合理，应说背。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶用手着托一碗饺子，慢慢走过来。", "corrected_sentence": "奶奶用手托着一碗饺子，慢慢走过来。", "error_description": "“着”应紧跟动词，写作“托着”，不能放在“托”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他托了住盘子，慢慢走进厨房。", "corrected_sentence": "他托住了盘子，慢慢走进厨房。", "error_description": "“住”是结果补语，“了”应放在补语之后，写作“托住了”，不能写成“托了住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
