INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手掌或其他东西向上承受。", "primary_collocate": null, "pronunciation": "tuō", "ipa": "tʰwo˥˥", "syllable_count": 1, "sentences": [{"text": "一根柱子托着屋顶。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水托着小船慢慢往前走。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有个架子托着花盆。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树枝托着一个小鸟窝。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥墩托着那座大桥。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个架子托不住那么多书。", "target_word": "托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用一块木板托住了箱子。", "target_word": "托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人用千斤顶把车托起一点。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水托着大船，船不会沉。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳时，老师用手托着我的背。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "托着", "label": "体标"}, {"form": "托住", "label": "复合"}, {"form": "托举", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手掌或柱子、架子、水等从下面向上承受物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ed2684-d9cf-47cd-bea6-80ea625cf249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "托", "is_correct": true, "explanation": "托 tuō 为第一声，意思是从下面向上承受。"}, {"text": "唾", "is_correct": false, "explanation": "唾 tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}, {"text": "妥", "is_correct": false, "explanation": "妥 tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。"}, {"text": "多", "is_correct": false, "explanation": "多 duō 声母为 d 而不是 t，意思是数量大。"}, {"text": "拓", "is_correct": false, "explanation": "拓 tuò（第四声）与 tuō（第一声）声调不同，意思是开拓。"}], "explanations": {"托": "托 tuō 为第一声，意思是从下面向上承受。", "唾": "唾 tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。", "妥": "妥 tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。", "多": "多 duō 声母为 d 而不是 t，意思是数量大。", "拓": "拓 tuò（第四声）与 tuō（第一声）声调不同，意思是开拓。"}, "sentence_index": null, "correct_answer": "托"}, "level_3": {"options": [{"text": "托", "is_correct": true, "explanation": "正确：“托”表示从下面向上承受，符合“一根柱子托着屋顶”。"}, {"text": "压", "is_correct": false, "explanation": "语义：“压”是从上往下施力，与柱子从下面承受屋顶相反。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”要借助钩子或墙面，不说挂屋顶。"}, {"text": "吊", "is_correct": false, "explanation": "语义：“吊”是从上方悬着，与从下面承受的意思不符。"}], "explanations": {"托": "正确：“托”表示从下面向上承受，符合“一根柱子托着屋顶”。", "压": "语义：“压”是从上往下施力，与柱子从下面承受屋顶相反。", "挂": "搭配：“挂”要借助钩子或墙面，不说挂屋顶。", "吊": "语义：“吊”是从上方悬着，与从下面承受的意思不符。"}, "sentence_index": 0, "correct_answer": "托"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一盏灯托在天花板上。", "explanation": "这里应该用〈吊〉。托是从下面向上承受，灯悬在天花板上要说吊。"}, {"text": "一根铁丝托着一只鸟笼，挂在树上。", "explanation": "这里应该用〈挂〉。鸟笼悬在树上是从上方吊着，托是从下往上承受，应说挂。"}, {"text": "他用绳子托着一桶水，从井里拉了上来。", "explanation": "这里应该用〈提〉。托是从下面向上承受，用绳子从上面拉水桶要说提。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "托", "is_correct": true, "explanation": "托 tuō 为第一声，意思是从下面向上承受。"}, {"text": "驼", "is_correct": false, "explanation": "驼 tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。"}, {"text": "陀", "is_correct": false, "explanation": "陀 tuó（第二声）与 tuō（第一声）声调不同，如陀螺。"}, {"text": "椭", "is_correct": false, "explanation": "椭 tuǒ（第三声）与 tuō（第一声）声调不同，如椭圆。"}], "explanations": {"托": "托 tuō 为第一声，意思是从下面向上承受。", "驼": "驼 tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。", "陀": "陀 tuó（第二声）与 tuō（第一声）声调不同，如陀螺。", "椭": "椭 tuǒ（第三声）与 tuō（第一声）声调不同，如椭圆。"}, "sentence_index": null, "correct_answer": "托"}, "level_3": {"options": [{"text": "托", "is_correct": true, "explanation": "正确：“托住”表示用手或物体从下面承受，符合“用木板托住了箱子”。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是猛力撞击，与稳稳承受箱子不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛出去，与用木板承住箱子的意思相反。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”是拆开、拆除，不能说拆住箱子。"}], "explanations": {"托": "正确：“托住”表示用手或物体从下面承受，符合“用木板托住了箱子”。", "砸": "语义：“砸”是猛力撞击，与稳稳承受箱子不符。", "扔": "语义：“扔”是抛出去，与用木板承住箱子的意思相反。", "拆": "搭配：“拆”是拆开、拆除，不能说拆住箱子。"}, "sentence_index": 6, "correct_answer": "托"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他托着一担柴走过了小桥。", "explanation": "这里应该用〈挑〉。托是手掌在下面撑着，用扁担担柴要说挑。"}, {"text": "两个人托着一张大床上楼。", "explanation": "这里应该用〈抬〉。大件家具要两人合力，应说抬，托不这么用。"}, {"text": "他把一幅画托在墙上。", "explanation": "这里应该用〈挂〉。托是从下往上承受，画挂在墙上要说挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖水托了住那只小船，轻轻晃动。", "corrected_sentence": "湖水托住了那只小船，轻轻晃动。", "error_description": "“住”是结果补语，“了”应放在补语之后，写作“托住了”，不能写成“托了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "架子托了着一盆花。", "corrected_sentence": "架子托着一盆花。", "error_description": "“了”不能插在“托”和“着”之间。“着”是动词的状态标记，应直接跟在“托”后，写作“托着”，“托了着”有误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
