INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88537, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88537, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "说不上是没办法说清楚，也不能说是这样。", "primary_collocate": null, "pronunciation": "shuō bu shàng", "ipa": "ʂwo˥˥ pu ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他为什么哭，我也说不上，可能是想家了。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是什么鸟？我说不上。", "target_word": "说不上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他到底几岁，我说不上，大概三十吧。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天心里怪怪的，说不上是高兴还是难过。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是什么感觉？我也说不上。", "target_word": "说不上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个办法哪个好，一时说不上。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是好人还是坏人，我说不上。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我为什么喜欢这首歌，我说不上。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哪里变了？我说不上，但觉得不一样。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆什么菜好吃？我吃得少，说不上。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说得上", "label": "肯定形式"}], "register": "口语", "sense_fingerprint": "说不清楚、不能断定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说不上", "is_correct": true, "explanation": "正确。“说不上”表示说不清楚，与“他为什么哭，我也……，可能是想家了”的推测语境相符。"}, {"text": "确定", "is_correct": false, "explanation": "语义：“确定”表示肯定，与句中“可能”的推测语气冲突。"}, {"text": "保证", "is_correct": false, "explanation": "语义：“保证”表示有把握地担保，与句中“可能”的推测语气矛盾。"}, {"text": "证明", "is_correct": false, "explanation": "语义：“证明”需要确凿的依据，与“可能”的推测语气矛盾。"}], "explanations": {"说不上": "正确。“说不上”表示说不清楚，与“他为什么哭，我也……，可能是想家了”的推测语境相符。", "确定": "语义：“确定”表示肯定，与句中“可能”的推测语气冲突。", "保证": "语义：“保证”表示有把握地担保，与句中“可能”的推测语气矛盾。", "证明": "语义：“证明”需要确凿的依据，与“可能”的推测语气矛盾。"}, "sentence_index": 0, "correct_answer": "说不上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚刚亲口告诉我为什么哭，我说不上他为什么哭。", "explanation": "这里应该用〈说得出〉。句中“亲口告诉我”说明我已经知道原因，能说清楚；“说不上”表示说不清楚，与语境矛盾。"}, {"text": "他哭得那么厉害，说不上他很伤心。", "explanation": "这里应该用〈说明〉。“说明”用于由明显迹象推出结论；“哭得那么厉害”已是明显迹象，“说不上”表示不能确切地说，与语境矛盾。"}, {"text": "他的每个答案我都确定无误，说不上哪个是对的。", "explanation": "这里应该用〈说得出〉。句中“确定无误”说明我很清楚答案，能说清楚；“说不上”表示说不清楚，与语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说不上", "is_correct": true, "explanation": "正确。“说不上”表示不能确切地说，与“他是好人还是坏人”的两可语境相符。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”表示赞成别人的意见，句中没有可以赞成的意见，与“好人还是坏人”的疑问不合。"}, {"text": "断定", "is_correct": false, "explanation": "配价：“断定”需要带判断内容的宾语，句末缺少宾语，不能成立。"}, {"text": "认定", "is_correct": false, "explanation": "配价：“认定”需要带宾语，句末缺少宾语，不能成立。"}], "explanations": {"说不上": "正确。“说不上”表示不能确切地说，与“他是好人还是坏人”的两可语境相符。", "同意": "语义：“同意”表示赞成别人的意见，句中没有可以赞成的意见，与“好人还是坏人”的疑问不合。", "断定": "配价：“断定”需要带判断内容的宾语，句末缺少宾语，不能成立。", "认定": "配价：“认定”需要带宾语，句末缺少宾语，不能成立。"}, "sentence_index": 6, "correct_answer": "说不上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "菜单是我写的，每道菜什么味道，我都说不上。", "explanation": "这里应该用〈说得出〉。菜单是“我”写的，“我”很清楚每道菜的味道；“说不上”表示说不清楚，与语境矛盾。"}, {"text": "这家饭馆的菜我天天吃，哪道最好吃我说不上，一口就能告诉你。", "explanation": "这里应该用〈说得出〉。“一口就能告诉你”说明我很清楚；“说不上”表示说不清楚，与语境矛盾。"}, {"text": "我在这家饭馆当了十年厨师，每道菜怎么做都记得清清楚楚，可哪道好吃我说不上。", "explanation": "这里应该用〈说得出〉。“记得清清楚楚”说明我很了解这些菜；“说不上”表示说不清楚，与语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事我也说不上了为什么。", "corrected_sentence": "这件事我也说不上为什么。", "error_description": "“说不上了为什么”错误，应为“说不上为什么”。“了”插在“说不上”和“为什么”之间，破坏了“说不上为什么”的结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对他的想法，实在说不上了什么。", "corrected_sentence": "我对他的想法，实在说不上什么。", "error_description": "“说不上了什么”错误，应为“说不上什么”。“了”插在可能补语“说不上”与宾语之间，破坏了结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
