INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88538, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "不能确切地说；谈不上。", "primary_collocate": null, "pronunciation": "shuō bu shàng", "ipa": "ʂwo˥˥ pu ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我们才见过两次面，说不上是朋友。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天只跑五分钟，说不上喜欢运动。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店东西一般，说不上好，也说不上坏。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只去过一次，说不上了解这个城市。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语刚入门，说不上流利。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么小的房子，说不上舒服。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只是一次考试，说不上能看出他的水平。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点钱太少，说不上帮了他多大的忙。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只会几句话，说不上懂英语。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "才学了三天，说不上会游泳。", "target_word": "说不上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说得上", "label": "肯定形式"}], "register": "口语", "sense_fingerprint": "够不上、谈不上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说不上", "is_correct": true, "explanation": "正确。“说不上”表示不能确切地说，与“才见过两次面”的语境相符。"}, {"text": "确定", "is_correct": false, "explanation": "语义：“确定”表示有把握地断定，与“才见过两次面”的语境矛盾。"}, {"text": "承认", "is_correct": false, "explanation": "搭配：“承认”多用于既成的事实或错误，不能用于尚未形成的交情。"}, {"text": "证明", "is_correct": false, "explanation": "语义：“证明”需要充分依据，“才见过两次面”的语境下不能证明双方是朋友。"}], "explanations": {"说不上": "正确。“说不上”表示不能确切地说，与“才见过两次面”的语境相符。", "确定": "语义：“确定”表示有把握地断定，与“才见过两次面”的语境矛盾。", "承认": "搭配：“承认”多用于既成的事实或错误，不能用于尚未形成的交情。", "证明": "语义：“证明”需要充分依据，“才见过两次面”的语境下不能证明双方是朋友。"}, "sentence_index": 0, "correct_answer": "说不上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的汉语很流利，说不上是流利。", "explanation": "这里应该用〈说得上〉。句中“很流利”已是明确的评价，应用肯定的“说得上”；“说不上”表示不能确切地说，与语境矛盾。"}, {"text": "他每天跑十公里，周末还去爬山，说不上喜欢运动。", "explanation": "这里应该用〈说得上〉。每天跑十公里、周末爬山已足以说明他喜欢运动；“说不上”表示够不上、谈不上，与语境矛盾。"}, {"text": "他已经连续三年拿第一，说不上是优秀。", "explanation": "这里应该用〈说得上〉。句中“连续三年拿第一”已足以确定优秀，应用肯定的“说得上”；“说不上”表示不能确切地说，与语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说不上", "is_correct": true, "explanation": "正确。“说不上”表示不能确切地说，与“只是一次考试”的语境相符。"}, {"text": "说得上", "is_correct": false, "explanation": "语义：“说得上”表示能够确切地说，与“只是一次考试”的限定矛盾。"}, {"text": "说得准", "is_correct": false, "explanation": "语义：“说得准”表示能够确定地说，与“只是一次考试”的局限不符。"}, {"text": "认定", "is_correct": false, "explanation": "搭配：“认定”用于对事实作出判定，不用于对能力的估计，与“能看出”不搭配。"}], "explanations": {"说不上": "正确。“说不上”表示不能确切地说，与“只是一次考试”的语境相符。", "说得上": "语义：“说得上”表示能够确切地说，与“只是一次考试”的限定矛盾。", "说得准": "语义：“说得准”表示能够确定地说，与“只是一次考试”的局限不符。", "认定": "搭配：“认定”用于对事实作出判定，不用于对能力的估计，与“能看出”不搭配。"}, "sentence_index": 6, "correct_answer": "说不上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他才学了三天，说不上会游泳，他已经能游一公里了。", "explanation": "这里应该用〈说得上〉。句中“能游一公里了”已能确定他会游泳，应用肯定的“说得上”；“说不上”表示不能确切地说，与语境矛盾。"}, {"text": "他已经拿了游泳冠军，却说不上会游泳。", "explanation": "这里应该用〈说得上〉。句中“拿了游泳冠军”已是确切的依据，应用肯定的“说得上”；“说不上”表示不能确切地说，与语境冲突。"}, {"text": "他在游泳池里来回游了一百圈，却说不上会游泳。", "explanation": "这里应该用〈说得上〉。句中“来回游了一百圈”已有充分的依据，应用肯定的“说得上”；“说不上”表示不能确切地说，与语境冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们刚认识一个星期，说不上了是好朋友。", "corrected_sentence": "我们刚认识一个星期，说不上是好朋友。", "error_description": "“说不上了是好朋友”错误，应为“说不上是好朋友”。“了”不能插在“说不上”和后面的成分之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只学了三天，说不上了会游泳。", "corrected_sentence": "他只学了三天，说不上会游泳。", "error_description": "“说不上了会游泳”错误，应为“说不上会游泳”。“了”不能插在“说不上”和后面的成分之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
