INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88539, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "更新就是把旧的换成新的。", "primary_collocate": null, "pronunciation": "gēng xīn", "ipa": "kɤŋ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "我的手机该更新系统了。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校去年更新了所有电脑。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年更新一次办公软件。", "target_word": "更新", "complexity_tier": "T3", "furigana": "gōngsī měinián gēngxīn yí cì bàngōng ruǎnjiàn。", "sentence_source": "generated"}, {"text": "请你把软件更新一下。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每天更新菜单。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在更新图书馆的旧书。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师每学期更新一次课本内容。", "target_word": "更新", "complexity_tier": "T3", "furigana": "lǎoshī měi xuéqī gēngxīn yí cì kèběn nèiróng。", "sentence_source": "generated"}, {"text": "爸爸想更新一下家里的旧电视。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站每周更新两次新闻。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司更新了办公室里的桌椅。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更新了", "label": "体标（完成）"}, {"form": "更新过", "label": "体标（经历）"}, {"form": "自动更新", "label": "复合"}], "register": "中性", "sense_fingerprint": "把旧的东西换成新的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88539, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更新", "is_correct": true, "explanation": "正确：“更新”表示把旧系统换成新版本，与“系统”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于系统。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与系统无关。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于去除表面的污物，不能说擦系统。"}], "explanations": {"更新": "正确：“更新”表示把旧系统换成新版本，与“系统”搭配，符合句意。", "吃": "语义：“吃”指进食，不能用于系统。", "唱": "语义：“唱”指发声演唱，与系统无关。", "擦": "搭配：“擦”用于去除表面的污物，不能说擦系统。"}, "sentence_index": 0, "correct_answer": "更新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的运行速度更新了。", "explanation": "这里应该用〈提高〉。更新指把旧的换成新的，速度的变化要用提高。"}, {"text": "我把墙上的裂缝更新了。", "explanation": "这里应该用〈修补〉。裂缝要修补，更新指把旧的换成新的，不用于修补破损之处。"}, {"text": "学校这学期更新了一千名学生。", "explanation": "这里应该用〈增加〉。更新用于物品或内容，学生人数增多要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更新", "is_correct": true, "explanation": "正确：“更新”表示把课本内容换成新的，与“每学期”搭配，符合句意。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”指身体腾起，与课本内容无关。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“课本内容”作宾语。"}, {"text": "飞", "is_correct": false, "explanation": "配价：“飞”是不及物动词，不能带“课本内容”作宾语。"}], "explanations": {"更新": "正确：“更新”表示把课本内容换成新的，与“每学期”搭配，符合句意。", "跳": "语义：“跳”指身体腾起，与课本内容无关。", "睡": "配价：“睡”是不及物动词，不能带“课本内容”作宾语。", "飞": "配价：“飞”是不及物动词，不能带“课本内容”作宾语。"}, "sentence_index": 6, "correct_answer": "更新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他更新了作业里的错误。", "explanation": "这里应该用〈改正〉。更新指换成新的，纠正作业中的错误要用改正。"}, {"text": "这个月的花费更新了一半。", "explanation": "这里应该用〈减少〉。更新表示把旧的换新，花费变少要用减少。"}, {"text": "这家公司的规模更新得很快。", "explanation": "这里应该用〈扩大〉。更新指换成新的，规模变大要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把软件更新。", "corrected_sentence": "我把软件更新了。", "error_description": "错误：“把”字句中“更新”后缺少“了”，应为“我把软件更新了”，把字句的动词后要有补语或“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校正在更新了教室的电脑。", "corrected_sentence": "学校正在更新教室的电脑。", "error_description": "错误：“正在”表示动作正在进行，不能与“了”同用，应为“学校正在更新教室的电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
