INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88540, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变换旧的,使成为新的。", "primary_collocate": null, "pronunciation": "gēng xīn", "ipa": "kɤŋ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这个手机应用需要马上更新。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院今年更新了不少旧设备。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂更新机器以后，工作快多了。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月更新一次自己的博客。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的旧公交车正在更新。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的电脑已经更新过了吗？", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家里的旧家具都更新了。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店每天更新货架上的商品。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说词典也要及时更新。", "target_word": "更新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校更新了教室里的旧投影仪。", "target_word": "更新", "complexity_tier": "T3", "furigana": "xuéxiào gēngxīn le jiàoshì lǐ de jiù tóuyǐngyí。", "sentence_source": "generated"}], "morphological_forms": [{"form": "更新了", "label": "体标（完成）"}, {"form": "更新过", "label": "体标（经历）"}, {"form": "自动更新", "label": "复合"}], "register": "中性", "sense_fingerprint": "变换旧的使其成为新的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更新", "is_correct": true, "explanation": "正确：“更新”表示使应用换成新版本，与“需要马上”搭配，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，与应用无关。"}, {"text": "钓", "is_correct": false, "explanation": "语义：“钓”指用鱼竿捕鱼，与应用无关。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于去除表面的污物，不能用于手机应用。"}], "explanations": {"更新": "正确：“更新”表示使应用换成新版本，与“需要马上”搭配，符合句意。", "煮": "语义：“煮”指用水加热食物，与应用无关。", "钓": "语义：“钓”指用鱼竿捕鱼，与应用无关。", "擦": "搭配：“擦”用于去除表面的污物，不能用于手机应用。"}, "sentence_index": 0, "correct_answer": "更新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她更新了屋顶的漏洞。", "explanation": "这里应该用〈修补〉。漏洞要修补，更新指把旧的换成新的，不用于修补破损之处。"}, {"text": "他们更新了三个孩子。", "explanation": "这里应该用〈培养〉。更新用于物品或内容，人的成长与教育要用培养。"}, {"text": "医生更新了病人。", "explanation": "这里应该用〈治疗〉。更新用于物品或内容，给病人看病要用治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更新", "is_correct": true, "explanation": "正确：“更新”表示把旧家具换成新的，与“把……都”搭配，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，不能用于家具。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于家具。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能用于“把”字句的宾语位置。"}], "explanations": {"更新": "正确：“更新”表示把旧家具换成新的，与“把……都”搭配，符合句意。", "唱": "语义：“唱”指发声演唱，不能用于家具。", "吃": "语义：“吃”指进食，不能用于家具。", "睡": "配价：“睡”是不及物动词，不能用于“把”字句的宾语位置。"}, "sentence_index": 6, "correct_answer": "更新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他更新了地上的垃圾。", "explanation": "这里应该用〈打扫〉。垃圾要打扫干净，更新指把旧的换成新的，不用于清除垃圾。"}, {"text": "他们终于更新了两人的矛盾。", "explanation": "这里应该用〈解决〉。矛盾要解决，更新指把旧的换成新的，不用于处理矛盾。"}, {"text": "他更新了我们的时间。", "explanation": "这里应该用〈节省〉。时间要节省，更新指把旧的换成新的，不用于时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的电脑更新着一次。", "corrected_sentence": "我的电脑更新过一次。", "error_description": "错误：“着”表示持续状态，不能用于“一次”这种计次的已完成动作。正确应为“更新过一次”，“过”表示经历，紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你更新了系统。", "corrected_sentence": "请你更新一下系统。", "error_description": "错误：请求对方做某事时，动作尚未发生，而“了”表示动作已经完成，二者不能搭配；应为“请你更新一下系统”，“一下”表示尝试、随便做做的语气。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
