INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "子宫是妈妈肚子里的一个地方，小宝宝在这里长大。", "primary_collocate": null, "pronunciation": "zǐ gōng", "ipa": "tsz̩˨˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "小宝宝在妈妈的子宫里睡觉。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子宫在妈妈的肚子里。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝出生以前住在子宫里。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我以前在她的子宫里。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子宫里很暖和，宝宝很安全。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫也是在妈妈的子宫里长大的。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的子宫里有一个小宝宝。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝在子宫里动了一下。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道子宫是什么吗？", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了子宫的图片。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "子宮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "妈妈肚子里宝宝长大的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88541, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "子宫", "is_correct": true, "explanation": "“子宫”是妈妈体内宝宝生长的地方，句中“里睡觉”合理。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是能睡觉的地方，“在冰箱里睡觉”不成立。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉不适合睡觉，“在抽屉里睡觉”说法不通。"}, {"text": "信箱", "is_correct": false, "explanation": "语义：信箱是用来收信的，“在妈妈的信箱里睡觉”说不通。"}], "explanations": {"子宫": "“子宫”是妈妈体内宝宝生长的地方，句中“里睡觉”合理。", "冰箱": "语义：冰箱不是能睡觉的地方，“在冰箱里睡觉”不成立。", "抽屉": "语义：抽屉不适合睡觉，“在抽屉里睡觉”说法不通。", "信箱": "语义：信箱是用来收信的，“在妈妈的信箱里睡觉”说不通。"}, "sentence_index": 0, "correct_answer": "子宫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈的一颗子宫里有一个小宝宝。", "explanation": "这里应该用〈个〉。“颗”用于粒状或圆形的东西，子宫是单个器官，要说“一个子宫”。"}, {"text": "医生指着屏幕上的一根子宫。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，子宫不能用“根”计量。"}, {"text": "妈妈的一本子宫里有一个小宝宝。", "explanation": "这里应该用〈个〉。“本”用于书籍等，子宫不能用“本”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "子宫", "is_correct": true, "explanation": "“子宫”是妈妈体内孕育宝宝的地方，与“有一个小宝宝”相符。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包装的是钱和卡，不能装小宝宝。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：牙齿是用来吃东西的，里面不可能有一个小宝宝。"}, {"text": "脑子", "is_correct": false, "explanation": "语义：脑子里装的是想法，不能说“有一个小宝宝”。"}], "explanations": {"子宫": "“子宫”是妈妈体内孕育宝宝的地方，与“有一个小宝宝”相符。", "钱包": "语义：钱包装的是钱和卡，不能装小宝宝。", "牙齿": "语义：牙齿是用来吃东西的，里面不可能有一个小宝宝。", "脑子": "语义：脑子里装的是想法，不能说“有一个小宝宝”。"}, "sentence_index": 6, "correct_answer": "子宫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈的一只子宫里有一个宝宝。", "explanation": "这里应该用〈个〉。子宫是单个器官，“只”不用于计量子宫。"}, {"text": "妈妈肚子里有一张子宫。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，子宫要说“一个子宫”。"}, {"text": "妈妈的一条子宫里有一个宝宝。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不能用来计量子宫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小宝宝每天都在妈妈的子宫们里长大。", "corrected_sentence": "小宝宝每天都在妈妈的子宫里长大。", "error_description": "“们”只用于表示人的复数，不能加在“子宫”后面，应说“妈妈的子宫里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生告诉她，宝宝在子宫上很安全。", "corrected_sentence": "医生告诉她，宝宝在子宫里很安全。", "error_description": "“子宫”是体内器官，表示位置应用方位词“里”，不能用“上”（“上”指表面）。应把“上”改为“里”，说“医生告诉她，宝宝在子宫里很安全。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
