INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女性和雌性哺乳动物生殖系统中孕育胎儿的器官。", "primary_collocate": null, "pronunciation": "zǐ gōng", "ipa": "tsz̩˨˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "医生说她的子宫很健康。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝在妈妈的子宫里慢慢长大。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子宫是女性身体里的一个器官。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的子宫里有一个小肿瘤。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果显示，她的子宫没有问题。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怀孕时，胎儿住在子宫里。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做了子宫检查。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用机器看了看她的子宫。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母牛的子宫里也有小牛。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为子宫不舒服去了医院。", "target_word": "子宫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "子宮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "女性和雌性哺乳动物孕育胎儿的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "子宫", "is_correct": true, "explanation": "“子宫”是器官，“很健康”描述身体器官的状况，正相符。"}, {"text": "方向", "is_correct": false, "explanation": "语义：“方向”不是身体器官，不能说“她的方向很健康”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”一般说“好”或“不好”，不说“很健康”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人体部位，不能说“她的天气很健康”。"}], "explanations": {"子宫": "“子宫”是器官，“很健康”描述身体器官的状况，正相符。", "方向": "语义：“方向”不是身体器官，不能说“她的方向很健康”。", "心情": "搭配：“心情”一般说“好”或“不好”，不说“很健康”。", "天气": "语义：“天气”不是人体部位，不能说“她的天气很健康”。"}, "sentence_index": 0, "correct_answer": "子宫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说她的一颗子宫很健康。", "explanation": "这里应该用〈个〉。“颗”用于粒状或圆形的东西，子宫是单个器官，要说“一个子宫”。"}, {"text": "医生在屏幕上看到了她的一根子宫。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，子宫不能用“根”计量。"}, {"text": "她的一片子宫有点不舒服。", "explanation": "这里应该用〈个〉。“片”用于薄而平的东西，子宫不能用“片”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "子宫", "is_correct": true, "explanation": "“子宫检查”是常见的妇科检查说法，与句意相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是可以检查的身体部位，句子不成立。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“故事”不是身体部位，不能说“做了故事检查”。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“检查”前面一般是身体、设备、作业，不说“感情检查”。"}], "explanations": {"子宫": "“子宫检查”是常见的妇科检查说法，与句意相符。", "天空": "语义：“天空”不是可以检查的身体部位，句子不成立。", "故事": "语义：“故事”不是身体部位，不能说“做了故事检查”。", "感情": "搭配：“检查”前面一般是身体、设备、作业，不说“感情检查”。"}, "sentence_index": 6, "correct_answer": "子宫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的一只子宫很健康。", "explanation": "这里应该用〈个〉。子宫是单个器官，“只”用于动物或成对的器官，不用于计量子宫。"}, {"text": "医生检查了她的一张子宫。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，子宫要说“一个子宫”。"}, {"text": "她的一条子宫有点不舒服。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不能用来计量子宫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "检查后医生说她的一只子宫一切正常。", "corrected_sentence": "检查后医生说她的子宫一切正常。", "error_description": "子宫是单个器官，计量词应用“个”，“只”多用于动物或成对的器官，应说“她的子宫”或“她的一个子宫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大夫仔细检查了她的一根子宫。", "corrected_sentence": "大夫仔细检查了她的子宫。", "error_description": "子宫是单个器官，不能用“根”计量（“根”用于细长的东西），这里直接说“她的子宫”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
