INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88543, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比对是把两样东西放在一起，看看哪里一样，哪里不一样。", "primary_collocate": null, "pronunciation": "bǐ duì", "ipa": "pi˨˩˦ tweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我把两本书的内容比对了一遍。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈比对着两张表，找出了不同。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你比对这两种药的名字。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子比对两幅画，发现了三个不同。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们比对了两个人的名字，发现一样。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比对两个答案，我才知道错在哪里。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在比对照片和本人。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机前，我比对过几家店的价格。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们比对着课本检查作业。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字很像，要仔细比对才能看出来。", "target_word": "比对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比对了", "label": "体标"}, {"form": "比对过", "label": "体标"}, {"form": "比对着", "label": "体标"}], "register": "中性", "sense_fingerprint": "把两样东西放一起看异同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢掉，与“内容”的核对比较不合。"}, {"text": "比对", "is_correct": true, "explanation": "“比对”表示把两本书的内容放在一起看异同，与句意相合。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象要是饮料，“内容”不能喝。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，不能带“两本书的内容”作宾语。"}], "explanations": {"扔": "语义：“扔”表示丢掉，与“内容”的核对比较不合。", "比对": "“比对”表示把两本书的内容放在一起看异同，与句意相合。", "喝": "语义：“喝”的对象要是饮料，“内容”不能喝。", "游": "配价：“游”是不及物动词，不能带“两本书的内容”作宾语。"}, "sentence_index": 0, "correct_answer": "比对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈比对了一碗汤，觉得有点咸。", "explanation": "这里应该用〈尝〉。比对是把两样东西放在一起看异同，试汤的味道要用〈尝〉。"}, {"text": "他比对了一下陌生人。", "explanation": "这里应该用〈打量〉。比对是对照找异同，只是看一眼陌生人要用〈打量〉。"}, {"text": "爸爸比对了一杯热茶。", "explanation": "这里应该用〈喝〉。比对表示把两样东西对照找异同，对一杯茶的动作要用〈喝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象要是能吃东西的动物或人，照片不能被喂。"}, {"text": "逛", "is_correct": false, "explanation": "配价：“逛”是不及物动词，不能带“照片和本人”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象要能吃，照片不能吃。"}, {"text": "比对", "is_correct": true, "explanation": "“比对”表示把照片与本人放在一起核对异同，与句意相合。"}], "explanations": {"喂": "语义：“喂”的对象要是能吃东西的动物或人，照片不能被喂。", "逛": "配价：“逛”是不及物动词，不能带“照片和本人”作宾语。", "吃": "语义：“吃”的对象要能吃，照片不能吃。", "比对": "“比对”表示把照片与本人放在一起核对异同，与句意相合。"}, "sentence_index": 6, "correct_answer": "比对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶比对了一件毛衣送给我。", "explanation": "这里应该用〈织〉。比对是把两样东西对照找异同，做毛衣送人要用〈织〉。"}, {"text": "小猫比对了一只老鼠。", "explanation": "这里应该用〈捉〉。比对表示对照找异同，小猫对老鼠的动作要用〈捉〉。"}, {"text": "摄影师比对了一张风景照。", "explanation": "这里应该用〈拍〉。比对表示对照找异同，给风景拍照要用〈拍〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板比对地两张表，一行一行地核查。", "corrected_sentence": "老板比对着两张表，一行一行地核查。", "error_description": "表示动作持续的“着”应紧跟动词“比对”，说“比对着两张表”；“地”不能放在动词和宾语之间，此处应用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察正在比对了指纹和档案。", "corrected_sentence": "警察正在比对指纹和档案。", "error_description": "“正在”表示动作正在进行，不能与表示完成的“了”同用，应说“正在比对”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
