INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88545, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说实话是把真的想法讲出来。", "primary_collocate": null, "pronunciation": "shuō shí huà", "ipa": "ʂwo˥ ʂʅ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "你要对老师说实话。", "target_word": "说实话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不敢跟妈妈说实话。", "target_word": "说实话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子做错了事，最好对爸爸妈妈说实话。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友问我好不好看，我没有说实话。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕大家生气，所以不愿意说实话。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察问了很久，他才说实话。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在医生面前，你一定要说实话。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就喜欢说实话，从不骗人。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师希望学生们都能说实话。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么总是不对我说实话？", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "说了实话", "label": "体标"}, {"form": "说过实话", "label": "体标"}], "register": "口语", "sense_fingerprint": "作谓语，把真实情况或真实想法讲出来，不骗人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aa1c745-16a8-430c-a276-d96c4b94600f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88545, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说实话", "is_correct": true, "explanation": "正确：“说实话”是讲出真实想法，与“你要对老师”的劝告相符。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“跑步”不能带“对老师”这样的对象，“对老师跑步”不成话。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能以人为主语，也不能带“对老师”。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”不能带“对老师”引出对象，“对老师毕业”不成话。"}], "explanations": {"说实话": "正确：“说实话”是讲出真实想法，与“你要对老师”的劝告相符。", "跑步": "搭配：“跑步”不能带“对老师”这样的对象，“对老师跑步”不成话。", "下雨": "语义：“下雨”是天气现象，不能以人为主语，也不能带“对老师”。", "毕业": "搭配：“毕业”不能带“对老师”引出对象，“对老师毕业”不成话。"}, "sentence_index": 0, "correct_answer": "说实话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子一坐上去就说实话，吱吱地响。", "explanation": "这里应该用〈吱嘎作响〉。说实话只表示人把真想法讲出来，不能表示椅子发出声响。"}, {"text": "这个闹钟一到七点就说实话，把全家都吵醒了。", "explanation": "这里应该用〈响〉。说实话只表示人讲真话，不能表示闹钟响起来。"}, {"text": "这台冰箱一开机就说实话，嗡嗡地吵个不停。", "explanation": "这里应该用〈发出〉（嗡嗡声）。说实话不能表示机器发出声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88545, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说实话", "is_correct": true, "explanation": "正确：“说实话”表示讲真话，与“在医生面前，你一定要”的要求相符。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：在医生面前吵架与“一定要”所提出的礼貌要求相矛盾。"}, {"text": "抽烟", "is_correct": false, "explanation": "语义：在医生面前抽烟不合场合，与“一定要”的劝告不一致。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：“下雪”是天气现象，不能以“你”为主语。"}], "explanations": {"说实话": "正确：“说实话”表示讲真话，与“在医生面前，你一定要”的要求相符。", "吵架": "语义：在医生面前吵架与“一定要”所提出的礼貌要求相矛盾。", "抽烟": "语义：在医生面前抽烟不合场合，与“一定要”的劝告不一致。", "下雪": "语义：“下雪”是天气现象，不能以“你”为主语。"}, "sentence_index": 6, "correct_answer": "说实话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫一饿就说实话，喵喵叫个不停。", "explanation": "这里应该用〈叫〉。说实话只表示人讲真话，不能表示猫叫。"}, {"text": "这只鸟停在树上一直说实话，叫个没完。", "explanation": "这里应该用〈鸣叫〉。说实话只表示人讲真话，不能表示鸟儿鸣叫。"}, {"text": "孩子们在操场上说实话，玩得很开心。", "explanation": "这里应该用〈玩耍〉。说实话不能表示游戏和嬉戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以后一定会爸爸说实话。", "corrected_sentence": "我以后一定会对爸爸说实话。", "error_description": "介词缺失：“说实话”的对象“爸爸”前需要介词“对”引出，应说“对爸爸说实话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天我跟老板了说实话，他居然没生气。", "corrected_sentence": "昨天我跟老板说了实话，他居然没生气。", "error_description": "错误形式：“了说实话”，“了”放在动词“说”之前。正确形式：“说了实话”，体标“了”应紧跟动词“说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
