INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "讲真话；老实说。", "primary_collocate": null, "pronunciation": "shuō shí huà", "ipa": "ʂwo˥ ʂʅ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "说实话，我不太喜欢这个电影。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说实话，这道菜有点儿太咸了。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说实话，你的字写得不太好。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说实话，我昨天晚上一点也没睡好。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说实话，这个办法我觉得不太好。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说实话，那次考试我根本没有准备。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说实话，我真的有点儿怕他。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友问我这件衣服怎么样，说实话，不太好看。", "target_word": "说实话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说实话，在这儿住了三年，我还是不习惯。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板，说实话，这个价钱我真的买不起。", "target_word": "说实话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "常放在句首或句中，引出自己的真实看法，相当于「老实说」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aa1c745-16a8-430c-a276-d96c4b94600f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说实话", "is_correct": true, "explanation": "正确：“说实话”引出真实看法，与后面“不太喜欢”的评价相符。"}, {"text": "推荐", "is_correct": false, "explanation": "语义：推荐是介绍好的事物，与“我不太喜欢这个电影”的评价冲突。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：夸奖表示肯定，与后半句的否定评价矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需要带受事或事由，不能单独放在句首引出评价。"}], "explanations": {"说实话": "正确：“说实话”引出真实看法，与后面“不太喜欢”的评价相符。", "推荐": "语义：推荐是介绍好的事物，与“我不太喜欢这个电影”的评价冲突。", "夸奖": "语义：夸奖表示肯定，与后半句的否定评价矛盾。", "感谢": "配价：“感谢”需要带受事或事由，不能单独放在句首引出评价。"}, "sentence_index": 0, "correct_answer": "说实话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台老式收音机一开就说实话，吵得人头疼。", "explanation": "这里应该用〈发出杂音〉。说实话表示讲真话或老实说，不能表示机器发出杂音。"}, {"text": "小狗在院子里说实话，叫了一个下午。", "explanation": "这里应该用〈叫〉。说实话不能表示狗的吠叫。"}, {"text": "池塘边的鸭子一直说实话，嘎嘎地闹个不停。", "explanation": "这里应该用〈嘎嘎叫〉。说实话不能表示鸭子的叫声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说实话", "is_correct": true, "explanation": "正确：“说实话”引出真实的感受，与“我真的有点儿怕他”相符。"}, {"text": "请教", "is_correct": false, "explanation": "语义：请教是请人指点，与“我真的有点儿怕他”的情感表达不相干。"}, {"text": "告别", "is_correct": false, "explanation": "语义：告别表示分开，与句中的情感陈述不相符。"}, {"text": "请客", "is_correct": false, "explanation": "搭配：请客的对象是宾客或费用，不能用来引出对人的感受。"}], "explanations": {"说实话": "正确：“说实话”引出真实的感受，与“我真的有点儿怕他”相符。", "请教": "语义：请教是请人指点，与“我真的有点儿怕他”的情感表达不相干。", "告别": "语义：告别表示分开，与句中的情感陈述不相符。", "请客": "搭配：请客的对象是宾客或费用，不能用来引出对人的感受。"}, "sentence_index": 6, "correct_answer": "说实话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们在工地上一直说实话，吵得附近居民睡不着。", "explanation": "这里应该用〈喧闹〉。说实话表示讲真话，不能表示大声吵闹。"}, {"text": "他坐在窗边一直说实话，看起来很无聊。", "explanation": "这里应该用〈发呆〉。说实话只表示讲真话，不能表示发呆。"}, {"text": "孩子们在操场上说实话，追着皮球跑来跑去。", "explanation": "这里应该用〈奔跑〉。说实话不能表示跑来跑去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "说实话过，我觉得这个计划太难了。", "corrected_sentence": "说实话，我觉得这个计划太难了。", "error_description": "错误形式：“说实话过”，体标“过”应紧接动词，写作“说过实话”；作插入语时“说实话”后不加体标。正确形式：“说实话，我觉得这个计划太难了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "了说实话，我真的不想去。", "corrected_sentence": "说实话，我真的不想去。", "error_description": "错误形式：“了说实话”，“了”放在“说实话”之前。正确形式：“说实话，我真的不想去”，“说实话”作插入语，前面不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
