INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "依法设立,股东以出资额为限对公司负责的企业法人。", "primary_collocate": null, "pronunciation": "yǒu xiàn gōng sī", "ipa": "jou˨˩˦ ɕjɛn˥˩ kʊŋ˥ sɨ˥", "syllable_count": 4, "sentences": [{"text": "有限公司的股东只对自己的钱负责。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有限公司要按法律去登记。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开有限公司时，要先有一些钱。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有限公司欠了钱，要用公司的财产来还，股东只以出资额为限负责。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家有限公司已经依法登记了。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有限公司是法人，可以用公司的名字做事。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开有限公司之前，要先想好公司的名字。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把小店改成了有限公司。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家有限公司的股东有三个人。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有限公司出问题时，股东不用拿出全部的钱。", "target_word": "有限公司", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "股份有限公司", "label": "复合"}], "register": "正式", "sense_fingerprint": "依法设立、股东只以出资额为限负责的企业法人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有限公司", "is_correct": true, "explanation": "正确。有限公司的出资人是股东，句子说股东只对自己的钱负责。"}, {"text": "合伙企业", "is_correct": false, "explanation": "语义：合伙企业的出资人称合伙人，没有“股东”这个说法。"}, {"text": "个人独资企业", "is_correct": false, "explanation": "语义：个人独资企业只有一个投资人，没有股东。"}, {"text": "农民合作社", "is_correct": false, "explanation": "搭配：合作社的成员称社员，“股东”一般只用于公司。"}], "explanations": {"有限公司": "正确。有限公司的出资人是股东，句子说股东只对自己的钱负责。", "合伙企业": "语义：合伙企业的出资人称合伙人，没有“股东”这个说法。", "个人独资企业": "语义：个人独资企业只有一个投资人，没有股东。", "农民合作社": "搭配：合作社的成员称社员，“股东”一般只用于公司。"}, "sentence_index": 0, "correct_answer": "有限公司"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们合伙开了一家有限公司，每人出一部分钱，欠的钱也一起还。", "explanation": "这里应该用〈合伙企业〉。有限公司的股东只以出资额为限负责，不用一起还公司欠的钱。"}, {"text": "这家有限公司是他一个人开的，公司欠的所有钱都要他用自己家的钱来还。", "explanation": "这里应该用〈个人独资企业〉。有限公司的股东只以出资额为限负责，不用拿自己家的全部财产还公司的债。"}, {"text": "他买了一只有限公司。", "explanation": "量词〈只〉多用于动物，有限公司应该用〈家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有限公司", "is_correct": true, "explanation": "正确。句中“公司的名字”说明要开的是公司，“有限公司”符合这一点。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大学是教育机构，不是公司，与句中“公司的名字”不一致。"}, {"text": "寺庙", "is_correct": false, "explanation": "语义：寺庙是宗教场所，不能设立公司，与句中“公司的名字”不一致。"}, {"text": "法院", "is_correct": false, "explanation": "语义：法院是审判机关，不是公司，与句中“公司的名字”不一致。"}], "explanations": {"有限公司": "正确。句中“公司的名字”说明要开的是公司，“有限公司”符合这一点。", "大学": "语义：大学是教育机构，不是公司，与句中“公司的名字”不一致。", "寺庙": "语义：寺庙是宗教场所，不能设立公司，与句中“公司的名字”不一致。", "法院": "语义：法院是审判机关，不是公司，与句中“公司的名字”不一致。"}, "sentence_index": 6, "correct_answer": "有限公司"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家有限公司没有法人资格，所以它不能以自己的名义签合同。", "explanation": "这里应该用〈个体户〉。有限公司是企业法人，能以自己的名义签合同；个体户没有法人资格。"}, {"text": "这家有限公司是政府部门，专门给市民办身份证。", "explanation": "这里应该用〈公安局〉等政府机关。有限公司是企业法人，不是政府部门。"}, {"text": "有限公司还不上钱时，股东要卖掉自己的房子把公司的债全部还清。", "explanation": "这是〈合伙企业〉或个体户的情况。有限公司的股东只以出资额为限负责，不用拿个人全部财产还债。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅有限公司依法登记了。", "corrected_sentence": "我舅舅的有限公司依法登记了。", "error_description": "“有限公司”前面漏了结构助词“的”。应说“我舅舅的有限公司”，表示这家公司属于舅舅。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "李阿姨开了一只有限公司。", "corrected_sentence": "李阿姨开了一家有限公司。", "error_description": "量词用错了。“有限公司”应用量词“家”计量，应说“一家有限公司”；“只”用于动物，不能用于公司。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
