INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88549, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "容忍是别人做得不对，你忍住，不生气。", "primary_collocate": null, "pronunciation": "róng rěn", "ipa": "ɻʊŋ˧˥ ɻən˨˩", "syllable_count": 2, "sentences": [{"text": "我不能容忍他一直迟到。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不容忍学生作弊。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她容忍了弟弟的坏习惯。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又在公共场合大声说话，我实在容忍不了。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经容忍他很久了。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种错误，公司不会容忍。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他容忍了同事的很多错误。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么要容忍这样的事？", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不容忍我撒谎。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居的噪音，我再也容忍不了了。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "容忍了", "label": "体标"}, {"form": "容忍过", "label": "体标"}, {"form": "容忍着", "label": "体标"}], "register": "中性", "sense_fingerprint": "别人做错时忍住不生气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容忍", "is_correct": true, "explanation": "正确：“容忍”表示对别人一再迟到的行为忍住不发火，与句意相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示接纳和喜爱，与“一直迟到”的不满语境相矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”针对好的表现，不能用于一再迟到这种不良行为。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是别人的帮助或好意，不能与“一直迟到”搭配。"}], "explanations": {"容忍": "正确：“容忍”表示对别人一再迟到的行为忍住不发火，与句意相符。", "欢迎": "语义：“欢迎”表示接纳和喜爱，与“一直迟到”的不满语境相矛盾。", "表扬": "语义：“表扬”针对好的表现，不能用于一再迟到这种不良行为。", "感谢": "搭配：“感谢”的对象是别人的帮助或好意，不能与“一直迟到”搭配。"}, "sentence_index": 0, "correct_answer": "容忍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他咬紧牙关，容忍着手术后的剧痛。", "explanation": "这里应该用〈忍受〉。容忍针对别人不对的言行，不用于忍受身体的疼痛。"}, {"text": "老师很容忍这个学生的努力。", "explanation": "这里应该用〈欣赏〉。容忍用于令人不满的人或事，不用于值得肯定的努力。"}, {"text": "这个礼堂可以容忍五百人同时就座。", "explanation": "这里应该用〈容纳〉。容忍指忍受不合意的人或事，不表示空间能装下多少人，那要用容纳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容忍", "is_correct": true, "explanation": "正确：“容忍”表示对同事的错误忍耐，与句意相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”针对做得好的地方，不能用于“很多错误”。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“很多错误”的语义相矛盾。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是优点或作品，不能与“错误”搭配。"}], "explanations": {"容忍": "正确：“容忍”表示对同事的错误忍耐，与句意相符。", "夸奖": "语义：“夸奖”针对做得好的地方，不能用于“很多错误”。", "赞美": "语义：“赞美”表示称赞，与“很多错误”的语义相矛盾。", "欣赏": "搭配：“欣赏”的对象是优点或作品，不能与“错误”搭配。"}, "sentence_index": 6, "correct_answer": "容忍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都容忍这幅画的美。", "explanation": "这里应该用〈赞叹〉。容忍表示忍受不合意的人或事，不用于称赞美丽的事物。"}, {"text": "我常常容忍想起小时候的村庄。", "explanation": "这里应该用〈怀念〉。容忍表示忍受不合意的人或事，不用于回想美好的过去。"}, {"text": "我到处容忍丢失的钥匙。", "explanation": "这里应该用〈寻找〉。容忍表示忍耐，不表示寻找丢失的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我实在不能容忍了他这样迟到。", "corrected_sentence": "我实在不能容忍他这样迟到。", "error_description": "错误：“容忍”后面多加了“了”。“不能”后面的动词不带“了”，应说“不能容忍”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种吵闹，我真的容忍不。", "corrected_sentence": "这种吵闹，我真的容忍不了。", "error_description": "错误：“容忍不”后缺少补语“了”。“V不了”是可能补语的否定形式，应说“容忍不了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
