INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88550, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对不合意的人或事忍耐、宽容。", "primary_collocate": null, "pronunciation": "róng rěn", "ipa": "ɻʊŋ˧˥ ɻən˨˩", "syllable_count": 2, "sentences": [{"text": "他很难容忍不同的意见。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学会容忍不一样的人。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不能容忍别人插队。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板容忍员工有不同的想法。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会应该容忍不同的生活方式。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直容忍着邻居的吵闹。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我无法容忍这样的态度。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容忍别人的缺点，是一种修养。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她容忍了他的坏脾气好几年。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校不能容忍任何形式的欺负。", "target_word": "容忍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "容忍了", "label": "体标"}, {"form": "容忍过", "label": "体标"}, {"form": "容忍着", "label": "体标"}], "register": "中性", "sense_fingerprint": "对不合意的人或事忍耐宽容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容忍", "is_correct": true, "explanation": "正确：“容忍”表示勉强忍受不同的意见，与句意相符。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的对象是申请、计划等，不能用于“不同的意见”。"}, {"text": "撕毁", "is_correct": false, "explanation": "搭配：“撕毁”的对象是纸张、合同等具体物件，不能用于抽象的“意见”。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶、头发等，不能用于抽象的“意见”。"}], "explanations": {"容忍": "正确：“容忍”表示勉强忍受不同的意见，与句意相符。", "批准": "搭配：“批准”的对象是申请、计划等，不能用于“不同的意见”。", "撕毁": "搭配：“撕毁”的对象是纸张、合同等具体物件，不能用于抽象的“意见”。", "修剪": "搭配：“修剪”的对象是枝叶、头发等，不能用于抽象的“意见”。"}, "sentence_index": 0, "correct_answer": "容忍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常容忍老师的帮助。", "explanation": "这里应该用〈感激〉。容忍用于令人不满的人或事，不用于值得感谢的帮助。"}, {"text": "大家都容忍这里的风景。", "explanation": "这里应该用〈赞美〉。容忍用于不合意的人或事，不用于称赞美丽的风景。"}, {"text": "老师很容忍他的才华。", "explanation": "这里应该用〈欣赏〉。容忍表示勉强忍受，不用于对才华的肯定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容忍", "is_correct": true, "explanation": "正确：“容忍”表示勉强忍受这样的态度，与句意相符。"}, {"text": "撕毁", "is_correct": false, "explanation": "搭配：“撕毁”的对象是纸张、合同等具体物件，不能用于“态度”。"}, {"text": "同情", "is_correct": false, "explanation": "语义：“同情”针对别人的遭遇或处境，与对“态度”的评价不相符。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是生活、待遇等，不能用于“态度”。"}], "explanations": {"容忍": "正确：“容忍”表示勉强忍受这样的态度，与句意相符。", "撕毁": "搭配：“撕毁”的对象是纸张、合同等具体物件，不能用于“态度”。", "同情": "语义：“同情”针对别人的遭遇或处境，与对“态度”的评价不相符。", "享受": "搭配：“享受”的对象是生活、待遇等，不能用于“态度”。"}, "sentence_index": 6, "correct_answer": "容忍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都容忍他获得了冠军。", "explanation": "这里应该用〈祝贺〉。容忍用于不合意的人或事，不用于为别人的喜事道贺。"}, {"text": "她常常容忍远方的父母。", "explanation": "这里应该用〈思念〉。容忍表示忍耐，不用于想念亲人。"}, {"text": "学生们容忍这位老教授的学问。", "explanation": "这里应该用〈仰慕〉。容忍表示勉强忍受，不用于敬佩别人的学问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把容忍了这种欺骗行为。", "corrected_sentence": "我们容忍了这种欺骗行为。", "error_description": "错误：“把”字句中“把”后须接受事名词，“把容忍”中“把”后直接接动词，不成立。应删去“把”，说“我们容忍了这种欺骗行为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种粗鲁的言语，我真的很无法容忍。", "corrected_sentence": "这种粗鲁的言语，我真的无法容忍。", "error_description": "错误：“无法”是副词，前面不能再加程度副词“很”，应删去“很”，说“这种粗鲁的言语，我真的无法容忍。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
