INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88551, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "比年是一年又一年，连着很多年。", "primary_collocate": null, "pronunciation": "bǐ nián", "ipa": "pi˨˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个地方比年遭受干旱，农民很辛苦。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条河比年泛滥，村民只好搬家了。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比年在外工作，很少回家。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂比年亏损，老板很着急。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里比年下大雪，路常常不通。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家比年打仗，人民过得很苦。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城比年缺水，大家都很担心。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比年生病，身体越来越差了。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片田比年歉收，农民没有钱。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校比年招不到老师，孩子们很可怜。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，一年又一年，连着很多年（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88551, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比年", "is_correct": true, "explanation": "比年表示一年又一年、连着很多年，与“遭受干旱”反复发生的意思相符。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有过，与句中已经发生的“遭受干旱”相矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”一般修饰形容词或心理动词，不能说“十分遭受”。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”多修饰形容词，不能说“格外遭受”。"}], "explanations": {"比年": "比年表示一年又一年、连着很多年，与“遭受干旱”反复发生的意思相符。", "从未": "语义：“从未”表示从来没有过，与句中已经发生的“遭受干旱”相矛盾。", "十分": "搭配：“十分”一般修饰形容词或心理动词，不能说“十分遭受”。", "格外": "搭配：“格外”多修饰形容词，不能说“格外遭受”。"}, "sentence_index": 0, "correct_answer": "比年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪比年一下子停了。", "explanation": "这里应该用〈突然〉。比年指连年反复，不能与“一下子停了”这种突然发生的变化搭配。"}, {"text": "这个问题比年解决了。", "explanation": "这里应该用〈一次〉。比年指连年反复，不能修饰“解决了”这种只发生一次的事件。"}, {"text": "这次比赛他比年夺冠了。", "explanation": "这里应去掉〈比年〉，直接说“这次比赛他夺冠了。”比年表示连年反复，不能修饰“夺冠”这种只发生一次的事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比年", "is_correct": true, "explanation": "比年表示一年又一年，与“年年缺水、大家一直担心”的持续性相符。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意去做，缺水不可能是有意造成的，与句意不合。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”多修饰发展、变化等，不能说“迅速缺水”。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳无益，与“缺水、大家担心”的描述不合。"}], "explanations": {"比年": "比年表示一年又一年，与“年年缺水、大家一直担心”的持续性相符。", "特意": "语义：“特意”表示有意去做，缺水不可能是有意造成的，与句意不合。", "迅速": "搭配：“迅速”多修饰发展、变化等，不能说“迅速缺水”。", "白白": "语义：“白白”表示徒劳无益，与“缺水、大家担心”的描述不合。"}, "sentence_index": 6, "correct_answer": "比年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我比年一个星期去一次超市。", "explanation": "这里应该用〈每周〉。比年按年计，不能用于“一个星期去一次超市”这样的短周期。"}, {"text": "他比年考上了大学，全家都很高兴。", "explanation": "这里应该用〈当年〉。比年指连年反复，“考上大学”是一次性的事件，应说当年。"}, {"text": "我们学校比年一学期考三次试。", "explanation": "这里应该用〈每学期〉。比年按年计，不能用于“一学期考三次试”这样按学期的重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子比年地下雨，庄稼长得很好。", "corrected_sentence": "这个村子比年下雨，庄稼长得很好。", "error_description": "错误：“比年地下雨”。正确：“比年下雨”。“比年”是书面副词，后面一般不加“地”，直接修饰动词即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市比年的发生洪水，市民很害怕。", "corrected_sentence": "这个城市比年发生洪水，市民很害怕。", "error_description": "错误：“比年的发生”。正确：“比年发生”。副词“比年”直接修饰动词，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
