INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88552, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "连年；每年。", "primary_collocate": null, "pronunciation": "bǐ nián", "ipa": "pi˨˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个城市比年举办国际会议。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比年回乡祭祖，从不间断。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司比年增加投资，规模越来越大。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里比年举行龙舟比赛，游客很多。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人比年去山上种树，已经十年了。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校比年招收新学生。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府比年发放补助，帮助穷人。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比年出国旅行，去过很多地方。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村比年评选好人，大家很高兴。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场比年种新菜，卖得很好。", "target_word": "比年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，连年，每年（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比年", "is_correct": true, "explanation": "比年表示连年、每年，与“定期举办国际会议”的意思相符。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”一般修饰形容词，不修饰“举办”这类动作动词。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”多修饰形容词，不能说“格外举办”。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能说“非常举办”。"}], "explanations": {"比年": "比年表示连年、每年，与“定期举办国际会议”的意思相符。", "十分": "搭配：“十分”一般修饰形容词，不修饰“举办”这类动作动词。", "格外": "搭配：“格外”多修饰形容词，不能说“格外举办”。", "非常": "搭配：“非常”修饰形容词或心理动词，不能说“非常举办”。"}, "sentence_index": 0, "correct_answer": "比年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我比年一个小时跑一次步。", "explanation": "这里应该用〈每小时〉。比年按年计，不能用于“一个小时跑一次步”这样的短周期。"}, {"text": "妈妈比年一个星期买一次菜。", "explanation": "这里应该用〈每周〉。比年按年计，不能用于“一个星期买一次菜”这样的短周期。"}, {"text": "这个工厂比年倒闭了。", "explanation": "这里应去掉〈比年〉，直接说“这个工厂倒闭了。”比年表示连年反复，不能修饰“倒闭”这种一次性的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比年", "is_correct": true, "explanation": "比年表示连年、每年，与“每年发放补助、帮助穷人”的持续性相符。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有过，与“发放补助，帮助穷人”的做法相矛盾。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能说“很发放”。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”修饰形容词或表示程度的词语，不能修饰“发放”这类动词。"}], "explanations": {"比年": "比年表示连年、每年，与“每年发放补助、帮助穷人”的持续性相符。", "从不": "语义：“从不”表示从来没有过，与“发放补助，帮助穷人”的做法相矛盾。", "很": "搭配：“很”修饰形容词，不能说“很发放”。", "最": "搭配：“最”修饰形容词或表示程度的词语，不能修饰“发放”这类动词。"}, "sentence_index": 6, "correct_answer": "比年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他比年早上喝一杯咖啡。", "explanation": "这里应该用〈每天〉。比年按年计，不能修饰“早上喝一杯咖啡”这种每天都会有的习惯。"}, {"text": "农场的新菜比年一下子卖光了。", "explanation": "这里应该用〈突然〉。比年表示每年、连年，不能与“一下子卖光”这种突然发生的结果搭配。"}, {"text": "农场比年一个月收一次菜。", "explanation": "这里应该用〈每月〉。比年按年计，不能用于“一个月收一次菜”这样的短周期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市比年地召开会议，大家都很忙。", "corrected_sentence": "这个城市比年召开会议，大家都很忙。", "error_description": "错误：“比年地召开”。正确：“比年召开”。“比年”是书面副词，后面一般不加“地”，直接修饰动词即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府比年的发放补助，村民都很感谢。", "corrected_sentence": "政府比年发放补助，村民都很感谢。", "error_description": "错误：“比年的发放”。正确：“比年发放”。副词“比年”直接修饰动词，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
