INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "变元是数学里可以换成不同数的符号。", "primary_collocate": null, "pronunciation": "biàn yuán", "ipa": "pi̯ɛn˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个式子里有两个变元。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个变元x。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变元可以换成不同的数。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把变元换成三，再算一算。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个题只有一个变元，很简单。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先找出式子中的变元。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变元常常用字母来表示。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变元不是一个固定的数。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "式子是变元加一，把变元换成五，得六。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂什么是变元，去问老师。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "變元", "label": "繁体"}], "register": "书面", "sense_fingerprint": "数学式子里可以换成不同数的符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：式子里不会有学生，与数学语境冲突。"}, {"text": "变元", "is_correct": true, "explanation": "变元是式子中可以换成不同数的符号，此处语义和搭配都正确。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不属于数学式子，与“式子里有两个”的语境不符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的物件，不是式子中的成分，与“式子里有两个”的语境冲突。"}], "explanations": {"学生": "语义：式子里不会有学生，与数学语境冲突。", "变元": "变元是式子中可以换成不同数的符号，此处语义和搭配都正确。", "苹果": "语义：苹果是水果，不属于数学式子，与“式子里有两个”的语境不符。", "黑板": "语义：黑板是教室里的物件，不是式子中的成分，与“式子里有两个”的语境冲突。"}, "sentence_index": 0, "correct_answer": "变元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个数始终不变，它是一个变元。", "explanation": "这里应该用〈常数〉。“始终不变”说的是常数，变元的值可以换成不同的数。"}, {"text": "这个式子的变元是固定的，不能换成别的数。", "explanation": "这里应该用〈系数〉。系数是固定的，而变元是可以换成不同数的符号，“固定的”不能用于变元。"}, {"text": "二加三的变元是五。", "explanation": "这里应该用〈结果〉。五是算出来的数，不是可以换成不同数的符号，不能叫变元。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变元", "is_correct": true, "explanation": "变元常用字母表示，作主语时语义和搭配都正确。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不用字母表示，与数学语境不符。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节不用字母来表示，与句意冲突。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：口语称呼，作这句说明的主语既不合语域，语义也不通。"}], "explanations": {"变元": "变元常用字母表示，作主语时语义和搭配都正确。", "颜色": "语义：颜色不用字母表示，与数学语境不符。", "季节": "语义：季节不用字母来表示，与句意冲突。", "哥们儿": "语域：口语称呼，作这句说明的主语既不合语域，语义也不通。"}, "sentence_index": 6, "correct_answer": "变元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方程的变元只有一个解，要把它求出来。", "explanation": "这里应该用〈未知数〉。变元可以换成不同的数，“只有一个解，要求出来”指的是未知数。"}, {"text": "这个变元两边要相等，才能算对。", "explanation": "这里应该用〈等式〉。变元是可以换成不同数的符号，“两边要相等”说的是等式，变元并不具有这一性质。"}, {"text": "他算了半天，最后得出的变元是十。", "explanation": "这里应该用〈答案〉。算出来的是一个确定的数，变元是可以换成不同数的符号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个式子里有一只变元，能换成三。", "corrected_sentence": "这个式子里有一个变元，能换成三。", "error_description": "量词错误：变元是符号，应用“个”，“只”用于动物。正确形式是“有一个变元”，错误形式是“有一只变元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们变元换成了三。", "corrected_sentence": "我们把变元换成了三。", "error_description": "缺少介词“把”：“换成”的处置对象要用把字句提前，应说“我们把变元换成了三”，不能说“我们变元换成了三”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
