INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88554, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学或逻辑中可以取不同值的符号，即变量。", "primary_collocate": null, "pronunciation": "biàn yuán", "ipa": "pi̯ɛn˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个函数有两个变元。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "逻辑课上，老师讲了什么是变元。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变元可以取不同的值。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个变元都有自己的取值范围。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道逻辑题里，变元用字母表示。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变元也叫变量。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公式中的变元太多了，很难算。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这个变元能取哪些值。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变元的值变了，结果也会变。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在逻辑式里写了一个变元p。", "target_word": "变元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "變元", "label": "繁体"}], "register": "书面", "sense_fingerprint": "数学或逻辑中可以取不同值的符号，即变量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小猫", "is_correct": false, "explanation": "语义：函数里不会有小猫，与数学语境冲突。"}, {"text": "变元", "is_correct": true, "explanation": "变元是可以取不同值的符号，此处语义和搭配都正确。"}, {"text": "城市", "is_correct": false, "explanation": "语义：函数不包含城市，这句话在数学上说不通。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：口语词，与这句数学书面表述不协调。"}], "explanations": {"小猫": "语义：函数里不会有小猫，与数学语境冲突。", "变元": "变元是可以取不同值的符号，此处语义和搭配都正确。", "城市": "语义：函数不包含城市，这句话在数学上说不通。", "家伙": "语域：口语词，与这句数学书面表述不协调。"}, "sentence_index": 0, "correct_answer": "变元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个符号的值始终是三，它是变元。", "explanation": "这里应该用〈常数〉。“值始终是三”说的是固定的数，变元的值可以取不同的值。"}, {"text": "这组变元要先展开再计算，它本身就是一个式子。", "explanation": "这里应该用〈多项式〉。变元是可以取不同值的符号，要展开计算的是多项式这样的式子，变元本身并不是式子。"}, {"text": "这道题算完了，变元是八。", "explanation": "这里应该用〈答案〉。算出来的是确定的数，变元是可以取不同值的符号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变元", "is_correct": true, "explanation": "变元是公式中的成分，此处语义和搭配都正确。"}, {"text": "小路", "is_correct": false, "explanation": "语义：公式中不会有小路，与“太多了，很难算”的语境冲突。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：公式的成分不是颜色，这句话在数学上说不通。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶是昆虫，不是公式的成分，与“太多了，很难算”的语境冲突。"}], "explanations": {"变元": "变元是公式中的成分，此处语义和搭配都正确。", "小路": "语义：公式中不会有小路，与“太多了，很难算”的语境冲突。", "颜色": "语义：公式的成分不是颜色，这句话在数学上说不通。", "蝴蝶": "语义：蝴蝶是昆虫，不是公式的成分，与“太多了，很难算”的语境冲突。"}, "sentence_index": 6, "correct_answer": "变元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道方程的变元只有唯一的答案，我们要把它算出来。", "explanation": "这里应该用〈未知数〉。变元可以取不同的值，“只有唯一的答案，要算出来”指的是未知数。"}, {"text": "这个变元在计算中是固定的，不能换成别的数。", "explanation": "这里应该用〈系数〉。系数在计算中是固定的，变元则是可以换成不同数的符号，“固定的”不能用于变元。"}, {"text": "这个逻辑题的变元是“所以他去了学校”。", "explanation": "这里应该用〈结论〉。推出来的结论是一句话，变元是可以取不同值的符号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个公式里有一条变元，可以取不同的值。", "corrected_sentence": "这个公式里有一个变元，可以取不同的值。", "error_description": "量词错误：变元是符号，应用“个”，“条”用于细长的东西。正确形式是“有一个变元”，错误形式是“有一条变元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师变元写在黑板上了。", "corrected_sentence": "老师把变元写在黑板上了。", "error_description": "缺少介词“把”：“写”的对象要用把字句提前，应说“老师把变元写在黑板上了”，不能说“老师变元写在黑板上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入学", "is_correct": true, "explanation": "「入学」指进入学校开始学习，与「毕业」相对，是反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "「唱歌」指用声音演唱，与「毕业」没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "「跑步」指快速跑动，与「毕业」没有反义关系。"}, {"text": "写信", "is_correct": false, "explanation": "「写信」指用文字写书信，与「毕业」没有反义关系。"}], "correct_answer": "入学", "explanations": {"入学": "「入学」指进入学校开始学习，与「毕业」相对，是反义词。", "唱歌": "「唱歌」指用声音演唱，与「毕业」没有反义关系。", "跑步": "「跑步」指快速跑动，与「毕业」没有反义关系。", "写信": "「写信」指用文字写书信，与「毕业」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入学", "is_correct": true, "explanation": "「入学」指进入学校开始学习，与「毕业」相对，是反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "「睡觉」指闭眼休息，与「毕业」没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "「洗澡」指清洗身体，与「毕业」没有反义关系。"}, {"text": "下棋", "is_correct": false, "explanation": "「下棋」指对弈棋类游戏，与「毕业」没有反义关系。"}], "correct_answer": "入学", "explanations": {"入学": "「入学」指进入学校开始学习，与「毕业」相对，是反义词。", "睡觉": "「睡觉」指闭眼休息，与「毕业」没有反义关系。", "洗澡": "「洗澡」指清洗身体，与「毕业」没有反义关系。", "下棋": "「下棋」指对弈棋类游戏，与「毕业」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "毕业是学完了一个学校的课,可以离开了。", "primary_collocate": null, "pronunciation": "bì yè", "ipa": "pi˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟中学毕业了。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想早点儿毕业，找一份工作。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候毕业？", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹今年小学毕业，要去中学了。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业的时候，同学们都哭了。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业三年了，现在在银行工作。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是同一年毕业的。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还有一年才毕业。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学完所有的课，我就可以毕业了。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我们还常常见面。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毕业了", "label": "体标"}, {"form": "毕业生", "label": "复合"}, {"form": "毕业证", "label": "复合"}], "register": "中性", "sense_fingerprint": "学完一个学校的课程，可以离开学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e1ab4a-5687-4830-8ee0-0311191f4520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毕业", "is_correct": true, "explanation": "「毕业」指学完中学课程、可以离开学校，与句中的「弟弟」「中学」搭配，正确。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」指成立婚姻关系，弟弟是中学生，不能结婚。"}, {"text": "退休", "is_correct": false, "explanation": "语义：「退休」指离开工作岗位，与中学生的身份不符。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：「上班」说到工作单位，学生应说「上学」，不能说「中学上班」。"}], "explanations": {"毕业": "「毕业」指学完中学课程、可以离开学校，与句中的「弟弟」「中学」搭配，正确。", "结婚": "语义：「结婚」指成立婚姻关系，弟弟是中学生，不能结婚。", "退休": "语义：「退休」指离开工作岗位，与中学生的身份不符。", "上班": "搭配：「上班」说到工作单位，学生应说「上学」，不能说「中学上班」。"}, "sentence_index": 0, "correct_answer": "毕业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们参加的夏令营学了两周，今天毕业了。", "explanation": "这里应该用〈结业〉。毕业用于学完学校的规定课程，夏令营结束要用结业。"}, {"text": "他因为家里穷，初二就毕业了。", "explanation": "这里应该用〈辍学〉。毕业表示学完规定课程，中途不读了要用辍学。"}, {"text": "他在木匠铺学了三年，已经毕业了。", "explanation": "这里应该用〈出师〉。毕业用于学校的学业，学徒学成离开师傅要用出师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕业", "is_correct": true, "explanation": "「毕业」指学完规定课程，句中「她们」「同一年」「……的」都与之相合，正确。"}, {"text": "出版", "is_correct": false, "explanation": "语义：「出版」指书籍、报刊等印行，不能用于人。"}, {"text": "竣工", "is_correct": false, "explanation": "语义：「竣工」指工程建成，不能用于人。"}, {"text": "开花", "is_correct": false, "explanation": "语义：「开花」指植物长出花朵，不能用于「她们」这样的人。"}], "explanations": {"毕业": "「毕业」指学完规定课程，句中「她们」「同一年」「……的」都与之相合，正确。", "出版": "语义：「出版」指书籍、报刊等印行，不能用于人。", "竣工": "语义：「竣工」指工程建成，不能用于人。", "开花": "语义：「开花」指植物长出花朵，不能用于「她们」这样的人。"}, "sentence_index": 6, "correct_answer": "毕业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生因为转学，中途毕业了。", "explanation": "这里应该用〈离校〉。毕业表示学完全部课程，中途因转学离开学校要用离校。"}, {"text": "我们的暑期英语班，上周毕业了。", "explanation": "这里应该用〈结束〉。毕业只用于学完学校的规定课程，英语班结束只说结束。"}, {"text": "他因为身体原因，毕业在家养病。", "explanation": "这里应该用〈休学〉。毕业表示学完规定课程，因病暂时停学要用休学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表弟今年把小学毕业了，下个月要去中学读书。", "corrected_sentence": "我表弟今年小学毕业了，下个月要去中学读书。", "error_description": "错误：“毕业”是不及物动词，不能用“把”字句，“把”后不能接“小学”作宾语。正确：应说“小学毕业了”，不加“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹还没毕业了，还在上初三。", "corrected_sentence": "我妹妹还没毕业，还在上初三。", "error_description": "「还没」表示尚未完成，句末不加「了」。错误形式是「还没毕业了」，应改为「还没毕业」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
