INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "宁可是选一个比较好的，不选更糟的。", "primary_collocate": null, "pronunciation": "nìng kě", "ipa": "niŋ⁵¹ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "我宁可走路，也不坐那辆很挤的车。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他宁可少睡觉，也要把工作做完。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宁可早点儿出门，也不要迟到。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹宁可饿着，也不吃不新鲜的饭。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁可多花点钱，也要买好东西。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王宁可自己累一点，也不麻烦别人。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她宁可不去旅行，也不想跟不熟的人一起。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁可等一个小时，也不想坐下一班车。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他宁可饿肚子，也不愿意吃那家的菜。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宁可慢一点，也不要做错。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "宁可：在两种坏结果中选较好的一个，常与“也不”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df93761e-3099-453a-be8c-fa0da9ef77d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宁可", "is_correct": true, "explanation": "正确：「宁可」表示在两种不好的选择中取舍，后面用「也不」与之配合，与句意相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，不能表示主动权衡后的选择，与「也不坐那辆很挤的车」的取舍不合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词或心理动词，不能修饰「走路」这类动作。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示与事先预料相符，句中没有这样的前提，也无法引出被放弃的一方。"}], "explanations": {"宁可": "正确：「宁可」表示在两种不好的选择中取舍，后面用「也不」与之配合，与句意相符。", "竟然": "语义：「竟然」表示出乎意料，不能表示主动权衡后的选择，与「也不坐那辆很挤的车」的取舍不合。", "非常": "搭配：「非常」修饰形容词或心理动词，不能修饰「走路」这类动作。", "果然": "语义：「果然」表示与事先预料相符，句中没有这样的前提，也无法引出被放弃的一方。"}, "sentence_index": 0, "correct_answer": "宁可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他本来很累，听了这话宁可精神了。", "explanation": "这里应该用〈反而〉。宁可表示两种情况之间的取舍，不能表示与预期相反的结果；听了这话后精神起来是出乎意料的变化，要用〈反而〉。"}, {"text": "这个房间宁可很大。", "explanation": "这里应该去掉〈宁可〉，直接说「这个房间很大」。宁可只用于取舍，不能用来描述大小。"}, {"text": "经过多次尝试，他宁可成功了。", "explanation": "这里应该用〈终于〉。宁可表示取舍，后面要有被放弃的一方，不能表示经过努力后最终实现；表示结果要用〈终于〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宁可", "is_correct": true, "explanation": "正确：「宁可」表示权衡后宁愿选前一种，后面的「也不」与之配合，与句意相符。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：「格外」修饰形容词，如「格外好看」，不能修饰「不去旅行」这样的动词短语。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：「十分」修饰形容词或心理动词，不能直接修饰「不去旅行」这样的否定动作短语，句子不通。"}, {"text": "敢情", "is_correct": false, "explanation": "语域：「敢情」是口语色彩较浓的副词，表示恍然大悟，用在这里语义不合，也不符合书面的取舍表达。"}], "explanations": {"宁可": "正确：「宁可」表示权衡后宁愿选前一种，后面的「也不」与之配合，与句意相符。", "格外": "搭配：「格外」修饰形容词，如「格外好看」，不能修饰「不去旅行」这样的动词短语。", "十分": "搭配：「十分」修饰形容词或心理动词，不能直接修饰「不去旅行」这样的否定动作短语，句子不通。", "敢情": "语域：「敢情」是口语色彩较浓的副词，表示恍然大悟，用在这里语义不合，也不符合书面的取舍表达。"}, "sentence_index": 6, "correct_answer": "宁可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宁可明天天气好。", "explanation": "这里应该用〈但愿〉。宁可表示取舍，后面要有被放弃的一方；表示希望要用〈但愿〉。"}, {"text": "雨宁可马上就停了。", "explanation": "这里应该去掉〈宁可〉，直接说「雨马上就停了」。宁可表示取舍，不能表示即将发生。"}, {"text": "天宁可黑了。", "explanation": "这里应该用〈忽然〉。宁可表示取舍，不能描述天色突然变暗这种意外变化；要用〈忽然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很宁可晚点到，也不想让大家等。", "corrected_sentence": "我宁可晚点到，也不想让大家等。", "error_description": "错误：「宁可」前多加了程度副词「很」。「宁可」本身是副词，不能再受「很」修饰，正确形式是「我宁可晚点到」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我宁可多等一会儿，就不想催别人。", "corrected_sentence": "我宁可多等一会儿，也不想催别人。", "error_description": "错误：「也不」误写成「就不」。「宁可……也不……」表示宁愿承受前一种，也不选后一种；「就不」无法表达这种取舍，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88559, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名与知名相反，指没有名气、不为人知。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容声音或环境的状态，与名气无关，不是反义词。"}, {"text": "巨大", "is_correct": false, "explanation": "巨大形容体积或数量，与名气的有无无关。"}, {"text": "新鲜", "is_correct": false, "explanation": "新鲜形容事物刚出现或刚制作，与名气的有无无关。"}], "correct_answer": "无名", "explanations": {"无名": "无名与知名相反，指没有名气、不为人知。", "安静": "安静形容声音或环境的状态，与名气无关，不是反义词。", "巨大": "巨大形容体积或数量，与名气的有无无关。", "新鲜": "新鲜形容事物刚出现或刚制作，与名气的有无无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88559, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名与知名相反，指没有名气、不为人知。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄形容空间或宽度，与名气无关，不是反义词。"}, {"text": "温柔", "is_correct": false, "explanation": "温柔形容性格或态度，与名气无关，不是反义词。"}, {"text": "沉重", "is_correct": false, "explanation": "沉重形容重量或心情，与名气无关，不是反义词。"}], "correct_answer": "无名", "explanations": {"无名": "无名与知名相反，指没有名气、不为人知。", "狭窄": "狭窄形容空间或宽度，与名气无关，不是反义词。", "温柔": "温柔形容性格或态度，与名气无关，不是反义词。", "沉重": "沉重形容重量或心情，与名气无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88559, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "知名是很多人都听说过，有名气。", "primary_collocate": null, "pronunciation": "zhī míng", "ipa": "ʈʂɨ˥ mɪŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他是一位知名的医生，病人很多。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家知名的饭店在市中心。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是国内知名的歌手，很多人喜欢她。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位知名作家昨天来我们学校了。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京有很多知名的大学。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座知名的老桥已经有一百年历史了。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请来了几位知名的老师讲课。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子很知名，大家都买过。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开了一家知名的书店。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位知名演员正在拍新电影。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "知名度", "label": "复合"}, {"form": "知名人士", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词，很多人都听说过，有名气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知名", "is_correct": true, "explanation": "知名指很多人都听说过、有名气，与“医生”的身份及“病人很多”相符。"}, {"text": "空闲", "is_correct": false, "explanation": "语义：“空闲”指没有事情做，与“病人很多”正相矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”多形容场所或场面，不能用来形容医生。"}, {"text": "简陋", "is_correct": false, "explanation": "搭配：“简陋”多形容设施或房屋，不能说“简陋的医生”。"}], "explanations": {"知名": "知名指很多人都听说过、有名气，与“医生”的身份及“病人很多”相符。", "空闲": "语义：“空闲”指没有事情做，与“病人很多”正相矛盾。", "冷清": "搭配：“冷清”多形容场所或场面，不能用来形容医生。", "简陋": "搭配：“简陋”多形容设施或房屋，不能说“简陋的医生”。"}, "sentence_index": 0, "correct_answer": "知名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作家很知名，但是没有人知道他是谁。", "explanation": "这里应该用〈默默无闻〉。知名指很多人都知道，不能与“没有人知道他是谁”这种情况搭配。"}, {"text": "那位作家很知名，却没有一个人听说过他。", "explanation": "这里应该用〈无名〉。知名指很多人都听说过，不能与“没有一个人听说过他”这种情况搭配。"}, {"text": "他知名地来我们学校了。", "explanation": "这里应该用〈专程〉。知名描述人或事物有名气，不能描写“来”这个动作的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知名", "is_correct": true, "explanation": "知名指很多人都听说过，与“请来几位老师讲课”的做法相符。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容人心里孤单，与“请来讲课”的理由无关，句意不通。"}, {"text": "狭小", "is_correct": false, "explanation": "搭配：“狭小”形容空间，不能修饰指人的“老师”。"}, {"text": "空洞", "is_correct": false, "explanation": "语义：“空洞”指内容缺乏实质，与“请来讲课”的目的不合。"}], "explanations": {"知名": "知名指很多人都听说过，与“请来几位老师讲课”的做法相符。", "寂寞": "语义：“寂寞”形容人心里孤单，与“请来讲课”的理由无关，句意不通。", "狭小": "搭配：“狭小”形容空间，不能修饰指人的“老师”。", "空洞": "语义：“空洞”指内容缺乏实质，与“请来讲课”的目的不合。"}, "sentence_index": 6, "correct_answer": "知名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位导演很知名，却从来没有一个人听说过他。", "explanation": "这里应该用〈不为人知〉。知名指很多人都知道，不能与“从来没有一个人听说过他”这种情况搭配。"}, {"text": "这位演员很知名，但是没有一个人知道他是谁。", "explanation": "这里应该用〈默默无闻〉。知名指很多人都知道，不能与“没有一个人知道他是谁”搭配。"}, {"text": "那位演员知名地拍了一部新电影。", "explanation": "这里应该用〈亲自〉。知名描述人或事物有名气，不能描写“拍”这个动作的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家知名地饭店在当地，每天都有很多人来吃。", "corrected_sentence": "这家知名的饭店在当地，每天都有很多人来吃。", "error_description": "错误：“知名地饭店”。正确：“知名的饭店”。修饰名词时要用“的”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位演员被知名，大家都想见他。", "corrected_sentence": "那位演员很知名，大家都想见他。", "error_description": "错误：“被知名”。正确：“很知名”。“知名”是形容词，不能用“被”字句，表示程度要用“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88560, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名与知名相反，指没有名气、不为人知。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面质地，与名气无关，不是反义词。"}, {"text": "迟缓", "is_correct": false, "explanation": "迟缓形容动作或反应慢，与名气无关，不是反义词。"}, {"text": "沉重", "is_correct": false, "explanation": "沉重形容重量或心情，与名气无关，不是反义词。"}], "correct_answer": "无名", "explanations": {"无名": "无名与知名相反，指没有名气、不为人知。", "粗糙": "粗糙形容表面质地，与名气无关，不是反义词。", "迟缓": "迟缓形容动作或反应慢，与名气无关，不是反义词。", "沉重": "沉重形容重量或心情，与名气无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88560, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名与知名相反，指没有名气、不为人知。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容声音或环境的状态，与名气无关，不是反义词。"}, {"text": "巨大", "is_correct": false, "explanation": "巨大形容体积或数量，与名气的有无无关。"}, {"text": "新鲜", "is_correct": false, "explanation": "新鲜形容事物刚出现或刚制作，与名气的有无无关。"}], "correct_answer": "无名", "explanations": {"无名": "无名与知名相反，指没有名气、不为人知。", "安静": "安静形容声音或环境的状态，与名气无关，不是反义词。", "巨大": "巨大形容体积或数量，与名气的有无无关。", "新鲜": "新鲜形容事物刚出现或刚制作，与名气的有无无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88560, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，名声很大，为许多人所知道。", "primary_collocate": null, "pronunciation": "zhī míng", "ipa": "ʈʂɨ˥ mɪŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这是一家知名的公司，工资不错。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李教授在世界上很知名。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的菜很知名，外地人也来吃。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是本地知名的画家。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一双知名品牌的鞋。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位知名教授的讲座每次都坐满了人。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位知名运动员刚拿了金牌。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山很知名，每年有很多人来爬。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的书让他变得很知名。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位知名的老师，学生都很尊敬她。", "target_word": "知名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "知名度", "label": "复合"}, {"form": "知名人士", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词，名声很大，为许多人所知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知名", "is_correct": true, "explanation": "知名指名声很大、为许多人所知道，与“这是一家公司，工资不错”的描述相符。"}, {"text": "年迈", "is_correct": false, "explanation": "搭配：“年迈”形容人年纪大，不能修饰“公司”。"}, {"text": "蹩脚", "is_correct": false, "explanation": "语义：“蹩脚”指质量差，与“工资不错”的评价相矛盾。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，不能用来修饰“公司”。"}], "explanations": {"知名": "知名指名声很大、为许多人所知道，与“这是一家公司，工资不错”的描述相符。", "年迈": "搭配：“年迈”形容人年纪大，不能修饰“公司”。", "蹩脚": "语义：“蹩脚”指质量差，与“工资不错”的评价相矛盾。", "沙哑": "搭配：“沙哑”形容嗓音，不能用来修饰“公司”。"}, "sentence_index": 0, "correct_answer": "知名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事很知名，但是大家都没听说过。", "explanation": "这里应该用〈不为人知〉。知名指名气大、许多人都知道，不能与“大家都没听说过”搭配。"}, {"text": "这位画家很知名，但是没有人认识他。", "explanation": "这里应该用〈默默无闻〉。知名指很多人都知道，不能与“没有人认识他”这种情况搭配。"}, {"text": "这幅画知名地挂在墙上。", "explanation": "这里应该用〈醒目〉。知名描述人或事物有名气，不能描写“挂”这个动作的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知名", "is_correct": true, "explanation": "知名指名声很大、为许多人所知道，与“刚拿了金牌”的成就相符。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“刚拿了金牌”的成就相矛盾。"}, {"text": "破旧", "is_correct": false, "explanation": "搭配：“破旧”形容东西旧而破，不能用来修饰人。"}, {"text": "荒凉", "is_correct": false, "explanation": "搭配：“荒凉”形容地方，不能用来修饰人。"}], "explanations": {"知名": "知名指名声很大、为许多人所知道，与“刚拿了金牌”的成就相符。", "懒惰": "语义：“懒惰”与“刚拿了金牌”的成就相矛盾。", "破旧": "搭配：“破旧”形容东西旧而破，不能用来修饰人。", "荒凉": "搭配：“荒凉”形容地方，不能用来修饰人。"}, "sentence_index": 6, "correct_answer": "知名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师很知名，但是没有一个人听说过她。", "explanation": "这里应该用〈默默无闻〉。知名指很多人都知道，不能与“没有一个人听说过她”这种情况搭配。"}, {"text": "这位演员很知名，可是三年都没有一个人知道她。", "explanation": "这里应该用〈无名〉。知名指很多人都知道，不能与“三年都没有一个人知道她”搭配。"}, {"text": "她知名地教书，学生很喜欢。", "explanation": "这里应该用〈认真〉。知名描述人或事物有名气，不能描写“教书”这种动作的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
