INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88561, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变为是从这个样子变成了那个样子。", "primary_collocate": null, "pronunciation": "biàn wéi", "ipa": "pi̯ɛn˥˩ weɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "冰变为水，要加热。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气从晴天变为阴天。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河慢慢变为一条大河。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛毛虫会变为蝴蝶。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天慢慢变为黑夜，路灯也亮了。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水变为冰，需要很冷的天气。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头发变为白色了。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地以前是田，现在变为公园了。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水放久了，会变为冷水。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝色和黄色放在一起，会变为绿色。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变为了", "label": "体标"}, {"form": "變為", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物的样子或状态变成另一种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88561, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变为", "is_correct": true, "explanation": "正确答案：变为（biàn wéi），表示事物从一种样子变成另一种。"}, {"text": "变味", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，变味意思是味道或性质变坏，不是转变成另一种样子。"}, {"text": "贬为", "is_correct": false, "explanation": "biǎn（第三声）与 biàn（第四声）声调不同，贬为意思是降低地位成为，不是一般的变化。"}, {"text": "编为", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）声调不同，编为意思是编成，不是事物自己转变。"}], "explanations": {"变为": "正确答案：变为（biàn wéi），表示事物从一种样子变成另一种。", "变味": "wèi（第四声）与 wéi（第二声）声调不同，变味意思是味道或性质变坏，不是转变成另一种样子。", "贬为": "biǎn（第三声）与 biàn（第四声）声调不同，贬为意思是降低地位成为，不是一般的变化。", "编为": "biān（第一声）与 biàn（第四声）声调不同，编为意思是编成，不是事物自己转变。"}, "sentence_index": null, "correct_answer": "变为"}, "level_3": {"options": [{"text": "喜欢", "is_correct": false, "explanation": "语义：冰不会“喜欢”水，这里要的是表示状态转变的动词。"}, {"text": "变为", "is_correct": true, "explanation": "变为表示冰转变成水，与“要加热”的物理变化语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：冰不能“唱”水，与加热引起的物态变化不合。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的结果是碎片，不能得到“水”，不能接“水”作变化的结果。"}], "explanations": {"喜欢": "语义：冰不会“喜欢”水，这里要的是表示状态转变的动词。", "变为": "变为表示冰转变成水，与“要加热”的物理变化语境相合。", "唱": "语义：冰不能“唱”水，与加热引起的物态变化不合。", "打碎": "搭配：“打碎”的结果是碎片，不能得到“水”，不能接“水”作变化的结果。"}, "sentence_index": 0, "correct_answer": "变为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的力气变为了一头牛。", "explanation": "这里应该用〈相当于〉。“变为”表示事物转化成另一种东西，力气不能变成一头牛；说力气的大小相当，应用“相当于”。"}, {"text": "红色变为热情。", "explanation": "这里应该用〈代表〉。红色是热情的象征，并不会真的变成热情，“变为”指实际的转化。"}, {"text": "他把生活变为大海。", "explanation": "这里应该用〈比作〉。这是比喻，生活并没有真的变成大海，“变为”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：头发不能“吃”白色，这句话在语义上说不通。"}, {"text": "变为", "is_correct": true, "explanation": "变为表示头发从原来的颜色转变成白色，与“了”搭配自然。"}, {"text": "咬", "is_correct": false, "explanation": "语义：头发不会“咬”白色，动作与颜色变化不相关。"}, {"text": "添", "is_correct": false, "explanation": "搭配：“添”表示增加，不能说“头发添白色”，应说“变为白色”。"}], "explanations": {"吃": "语义：头发不能“吃”白色，这句话在语义上说不通。", "变为": "变为表示头发从原来的颜色转变成白色，与“了”搭配自然。", "咬": "语义：头发不会“咬”白色，动作与颜色变化不相关。", "添": "搭配：“添”表示增加，不能说“头发添白色”，应说“变为白色”。"}, "sentence_index": 6, "correct_answer": "变为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上变为一杯牛奶。", "explanation": "这里应该用〈喝〉。人不会变成牛奶，这里说的是喝牛奶，“变为”用错了。"}, {"text": "二加三变为五。", "explanation": "这里应该用〈等于〉。二加三只是等于五，不是转变成五，“变为”不能表示相等。"}, {"text": "他变为了一首曲子。", "explanation": "这里应该用〈演奏〉。人不会变成曲子，这里说的是他演奏了一首曲子，“变为”用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块冰慢慢变为着水。", "corrected_sentence": "这块冰慢慢变为了水。", "error_description": "体标错误：“变为”表示已完成的转变，应用“了”说“变为了水”，不能用“着”说“变为着水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天色慢慢变为成灰色了。", "corrected_sentence": "天色慢慢变为灰色了。", "error_description": "搭配错误：“变为”本身已包含“成为”的意思，后面不能再加“成”说“变为成”，应直接说“变为灰色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88562, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
