INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88562, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转变成；变成。", "primary_collocate": null, "pronunciation": "biàn wéi", "ipa": "pi̯ɛn˥˩ weɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "他的想法从反对变为支持。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇变为一座大城市。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里已经变为一个热闹的地方。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的担心变为了高兴。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏事有时会变为好事。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的敌人变为了朋友。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店变为了有名的大店。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慢慢地，害怕变为了勇气。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活变为了另一个样子。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子由穷变为富裕。", "target_word": "变为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变为了", "label": "体标"}, {"form": "變為", "label": "繁体"}], "register": "书面", "sense_fingerprint": "想法、关系、处境等转变成另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88562, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变为", "is_correct": true, "explanation": "正确答案：变为（biàn wéi），表示想法、关系或处境转变成另一种。"}, {"text": "变味", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，变味意思是味道或性质变坏，与转变成另一种状态不同。"}, {"text": "贬为", "is_correct": false, "explanation": "biǎn（第三声）与 biàn（第四声）声调不同，贬为意思是降低地位，不是一般的转变。"}, {"text": "编为", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）声调不同，编为意思是编成，与想法或处境的转变无关。"}], "explanations": {"变为": "正确答案：变为（biàn wéi），表示想法、关系或处境转变成另一种。", "变味": "wèi（第四声）与 wéi（第二声）声调不同，变味意思是味道或性质变坏，与转变成另一种状态不同。", "贬为": "biǎn（第三声）与 biàn（第四声）声调不同，贬为意思是降低地位，不是一般的转变。", "编为": "biān（第一声）与 biàn（第四声）声调不同，编为意思是编成，与想法或处境的转变无关。"}, "sentence_index": null, "correct_answer": "变为"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“从反对吃支持”说不通，想法不会“吃”支持。"}, {"text": "变为", "is_correct": true, "explanation": "变为表示想法从反对转变成支持，与“从……”的句式相合。"}, {"text": "送", "is_correct": false, "explanation": "语义：想法不能“送”支持，动作与想法的转变无关。"}, {"text": "搞", "is_correct": false, "explanation": "语义：“从反对搞支持”说不通，“搞”不能表示想法的转变。"}], "explanations": {"吃": "语义：“从反对吃支持”说不通，想法不会“吃”支持。", "变为": "变为表示想法从反对转变成支持，与“从……”的句式相合。", "送": "语义：想法不能“送”支持，动作与想法的转变无关。", "搞": "语义：“从反对搞支持”说不通，“搞”不能表示想法的转变。"}, "sentence_index": 0, "correct_answer": "变为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于变为了想法，决定参加。", "explanation": "这里应该用〈改变〉。“想法”是被改动的对象，“变为”表示自身转化，不能说“变为了想法”。"}, {"text": "我们要变为两人之间的误会。", "explanation": "这里应该用〈消除〉。要去掉误会，“变为”表示转成另一种状态，不能说要变成误会。"}, {"text": "他们终于变为了解决争议。", "explanation": "这里应该用〈解决〉。“变为”后接的是事物的新状态，不能接动作，应说“解决了争议”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打", "is_correct": false, "explanation": "语义：“这家小店打了有名的大店”说的是击打，与店铺变化无关。"}, {"text": "变为", "is_correct": true, "explanation": "变为表示小店转变成大店，与“了”搭配自然。"}, {"text": "骂", "is_correct": false, "explanation": "语义：小店不能“骂”大店，动作与规模的变化不相关。"}, {"text": "整", "is_correct": false, "explanation": "语义：“小店整了大店”说不通，“整”不能表示店铺转变成另一种样子。"}], "explanations": {"打": "语义：“这家小店打了有名的大店”说的是击打，与店铺变化无关。", "变为": "变为表示小店转变成大店，与“了”搭配自然。", "骂": "语义：小店不能“骂”大店，动作与规模的变化不相关。", "整": "语义：“小店整了大店”说不通，“整”不能表示店铺转变成另一种样子。"}, "sentence_index": 6, "correct_answer": "变为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一夜之间变为了二十岁。", "explanation": "这里应该用〈长到〉。变为表示事物转变成另一种性质或状态，年龄增长要说“长到”，不能说“变为”。"}, {"text": "他刚跑完比赛，就变为了一块奖牌。", "explanation": "这里应该用〈获得〉。变为表示事物转化成另一种东西，人不会变成奖牌；跑完比赛得到奖牌要说“获得”，不能说“变为”。"}, {"text": "他变为了自己的想法。", "explanation": "这里应该用〈放弃〉。这里是舍弃原来的想法，“变为”不能表示丢掉某个想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的态度慢慢变为着支持。", "corrected_sentence": "他的态度慢慢变为了支持。", "error_description": "体标错误：“变为”表示已完成的转变，应用“了”说“变为了支持”，不能用“着”说“变为着支持”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇变为成了一座大城市。", "corrected_sentence": "这个小镇变为了一座大城市。", "error_description": "重复错误：“变为”中的“为”已表示“成”，不能再加“成”说“变为成”，应说“变为了一座大城市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
