INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88563, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "统计就是把东西一个一个数清楚,再加在一起。", "primary_collocate": null, "pronunciation": "tǒng jì", "ipa": "tʰʊŋ˨˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "他把桌上的书一本一本统计清楚。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先统计一下，教室里有几把椅子。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈统计了家里的鸡蛋，一共十二个。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在统计今天来了多少学生。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要统计一下，有多少人想去。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他统计着箱子里的苹果，一个也不少。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请统计一下，一共有多少本书。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把今天卖出的杯子统计了两次，还是不对。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先统计每种水果有几个，再写下来。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里的东西，他已经统计完了。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "统计了", "label": "体标"}, {"form": "统计过", "label": "体标"}, {"form": "统计着", "label": "体标"}, {"form": "统计统计", "label": "重叠"}, {"form": "统计学", "label": "复合"}, {"form": "統計", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词；把东西逐个数清楚，再合计总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbc60e8-a9d1-4985-8b02-39b76cfdb0b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88563, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "统计", "is_correct": true, "explanation": "正确答案：统计（tǒng jì），指把东西逐个数清楚再合计总数。"}, {"text": "统治", "is_correct": false, "explanation": "zhì 与 jì 的声母不同（zh 与 j），声调相同。tǒng zhì 意思是统治、支配。"}, {"text": "同级", "is_correct": false, "explanation": "tóng jí 与 tǒng jì 两个音节的声调都不同，意思是同一等级。"}, {"text": "通缉", "is_correct": false, "explanation": "tōng jī 与 tǒng jì 两个音节的声调都不同，意思是通缉、悬赏追捕。"}], "explanations": {"统计": "正确答案：统计（tǒng jì），指把东西逐个数清楚再合计总数。", "统治": "zhì 与 jì 的声母不同（zh 与 j），声调相同。tǒng zhì 意思是统治、支配。", "同级": "tóng jí 与 tǒng jì 两个音节的声调都不同，意思是同一等级。", "通缉": "tōng jī 与 tǒng jì 两个音节的声调都不同，意思是通缉、悬赏追捕。"}, "sentence_index": null, "correct_answer": "统计"}, "level_3": {"options": [{"text": "统计", "is_correct": true, "explanation": "统计：指把书逐个数清楚，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝指饮用，不能用来数清楚书的数目。"}, {"text": "跳", "is_correct": false, "explanation": "配价：跳是不及物动词，后面不能带“清楚”作结果补语。"}, {"text": "哭", "is_correct": false, "explanation": "配价：哭是不及物动词，不能带“清楚”这样的补语，句子不成立。"}], "explanations": {"统计": "统计：指把书逐个数清楚，符合句意。", "喝": "语义：喝指饮用，不能用来数清楚书的数目。", "跳": "配价：跳是不及物动词，后面不能带“清楚”作结果补语。", "哭": "配价：哭是不及物动词，不能带“清楚”这样的补语，句子不成立。"}, "sentence_index": 0, "correct_answer": "统计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他统计了妈妈的爱。", "explanation": "这里应该用〈体会〉。统计只能用于可以逐个数清的对象，爱无法统计，应说“体会妈妈的爱”。"}, {"text": "他统计了老师的脾气。", "explanation": "这里应该用〈了解〉。统计只能用于可以逐个数清的对象，脾气无法统计，应说“了解老师的脾气”。"}, {"text": "他统计了一下窗外的风景。", "explanation": "这里应该用〈欣赏〉。统计要求对象可以逐个数清，风景不能这样处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88563, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "统计", "is_correct": true, "explanation": "正确答案：统计（tǒng jì），指把东西逐个数清楚再合计总数。"}, {"text": "痛击", "is_correct": false, "explanation": "tòng jī 与 tǒng jì 只有声调不同，意思是狠狠地打击。"}, {"text": "痛极", "is_correct": false, "explanation": "tòng 与 tǒng 声调不同，jí 与 jì 声调也不同，意思是痛到极点。"}, {"text": "同机", "is_correct": false, "explanation": "tóng jī 与 tǒng jì 两个音节的声调都不同，意思是同乘一架飞机。"}], "explanations": {"统计": "正确答案：统计（tǒng jì），指把东西逐个数清楚再合计总数。", "痛击": "tòng jī 与 tǒng jì 只有声调不同，意思是狠狠地打击。", "痛极": "tòng 与 tǒng 声调不同，jí 与 jì 声调也不同，意思是痛到极点。", "同机": "tóng jī 与 tǒng jì 两个音节的声调都不同，意思是同乘一架飞机。"}, "sentence_index": null, "correct_answer": "统计"}, "level_3": {"options": [{"text": "统计", "is_correct": true, "explanation": "统计：指把书的数量逐个数清再汇总，符合句意。"}, {"text": "摸", "is_correct": false, "explanation": "语义：摸是触碰，不能用来数清书的数量。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚的动作，与数书的数量无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱不能和“一下，一共有多少本书”搭配。"}], "explanations": {"统计": "统计：指把书的数量逐个数清再汇总，符合句意。", "摸": "语义：摸是触碰，不能用来数清书的数量。", "踢": "语义：踢是用脚的动作，与数书的数量无关。", "唱": "搭配：唱不能和“一下，一共有多少本书”搭配。"}, "sentence_index": 6, "correct_answer": "统计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书统计整齐了。", "explanation": "这里应该用〈排列〉。统计是数清并加总，不是摆放书的位置。"}, {"text": "他把仓库里的旧东西统计掉了。", "explanation": "这里应该用〈扔掉〉。统计表示数清并汇总，不能表示丢弃。"}, {"text": "他统计干净了桌子。", "explanation": "这里应该用〈擦〉。统计表示数清并汇总，不能表示擦掉灰尘或污渍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我统计了过这批货，一共三百件。", "corrected_sentence": "我统计过这批货，一共三百件。", "error_description": "“统计”后面只能用“过”或“了”其中之一，不能同时用。正确形式是“统计过这批货”，“统计了过这批货”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他统计很仔细。", "corrected_sentence": "他统计得很仔细。", "error_description": "“统计”后面的程度补语要用“得”连接，正确形式是“统计得很仔细”，“统计很仔细”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
