INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88564, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对有关数据进行汇总、计算和分析。", "primary_collocate": null, "pronunciation": "tǒng jì", "ipa": "tʰʊŋ˨˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "老师正在统计考试的成绩。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个月的销售数据统计一下。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年都要统计员工的人数。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他统计了全班同学的身高。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用电脑统计了去年的用电量。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份表格是他统计出来的。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生统计了病人的年龄和体重。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站每天都会统计有多少人来看。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想统计一下大家喜欢的运动。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让小王统计这个季度的收入。", "target_word": "统计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "统计了", "label": "体标"}, {"form": "统计过", "label": "体标"}, {"form": "统计着", "label": "体标"}, {"form": "统计统计", "label": "重叠"}, {"form": "统计学", "label": "复合"}, {"form": "統計", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词；对数据进行汇总、计算和分析", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbc60e8-a9d1-4985-8b02-39b76cfdb0b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88564, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "统计", "is_correct": true, "explanation": "正确答案：统计（tǒng jì），指对有关数据进行汇总、计算和分析。"}, {"text": "统治", "is_correct": false, "explanation": "zhì 与 jì 的声母不同（zh 与 j），声调相同。tǒng zhì 意思是统治、支配。"}, {"text": "同级", "is_correct": false, "explanation": "tóng jí 与 tǒng jì 两个音节的声调都不同，意思是同一等级。"}, {"text": "通缉", "is_correct": false, "explanation": "tōng jī 与 tǒng jì 两个音节的声调都不同，意思是通缉、悬赏追捕。"}], "explanations": {"统计": "正确答案：统计（tǒng jì），指对有关数据进行汇总、计算和分析。", "统治": "zhì 与 jì 的声母不同（zh 与 j），声调相同。tǒng zhì 意思是统治、支配。", "同级": "tóng jí 与 tǒng jì 两个音节的声调都不同，意思是同一等级。", "通缉": "tōng jī 与 tǒng jì 两个音节的声调都不同，意思是通缉、悬赏追捕。"}, "sentence_index": null, "correct_answer": "统计"}, "level_3": {"options": [{"text": "统计", "is_correct": true, "explanation": "统计：与“成绩”搭配，指对考试成绩进行汇总计算，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃指进食，不能用来处理考试成绩。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱指歌唱，不能和“成绩”搭配。"}, {"text": "发抖", "is_correct": false, "explanation": "配价：发抖是不及物动词，后面不能直接带“考试的成绩”作宾语。"}], "explanations": {"统计": "统计：与“成绩”搭配，指对考试成绩进行汇总计算，符合句意。", "吃": "语义：吃指进食，不能用来处理考试成绩。", "唱": "搭配：唱指歌唱，不能和“成绩”搭配。", "发抖": "配价：发抖是不及物动词，后面不能直接带“考试的成绩”作宾语。"}, "sentence_index": 0, "correct_answer": "统计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他统计了这块蛋糕的味道。", "explanation": "这里应该用〈品尝〉。统计用于汇总数据，味道不能统计。"}, {"text": "他统计了桌子的长度。", "explanation": "这里应该用〈测量〉。统计用于汇总数量或数据，量长度要用测量。"}, {"text": "他统计了这首歌的感情。", "explanation": "这里应该用〈体会〉。统计只用于可以数清或汇总的对象，感情无法统计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88564, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "统计", "is_correct": true, "explanation": "正确答案：统计（tǒng jì），指对有关数据进行汇总、计算和分析。"}, {"text": "痛击", "is_correct": false, "explanation": "tòng jī 与 tǒng jì 只有声调不同（第四声与第三声、第一声与第四声），意思是狠狠地打击。"}, {"text": "痛极", "is_correct": false, "explanation": "tòng 与 tǒng 声调不同，jí 与 jì 声调也不同，意思是痛到极点。"}, {"text": "同机", "is_correct": false, "explanation": "tóng jī 与 tǒng jì 两个音节的声调都不同，意思是同乘一架飞机。"}], "explanations": {"统计": "正确答案：统计（tǒng jì），指对有关数据进行汇总、计算和分析。", "痛击": "tòng jī 与 tǒng jì 只有声调不同（第四声与第三声、第一声与第四声），意思是狠狠地打击。", "痛极": "tòng 与 tǒng 声调不同，jí 与 jì 声调也不同，意思是痛到极点。", "同机": "tóng jī 与 tǒng jì 两个音节的声调都不同，意思是同乘一架飞机。"}, "sentence_index": null, "correct_answer": "统计"}, "level_3": {"options": [{"text": "统计", "is_correct": true, "explanation": "统计：对病人的年龄和体重进行记录汇总，符合句意。"}, {"text": "拍", "is_correct": false, "explanation": "语义：拍是击打或拍摄，不能用来记录病人的年龄和体重。"}, {"text": "抓", "is_correct": false, "explanation": "搭配：抓指用手握住，不能和“年龄和体重”搭配。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚的动作，与记录病人的数据毫无关系。"}], "explanations": {"统计": "统计：对病人的年龄和体重进行记录汇总，符合句意。", "拍": "语义：拍是击打或拍摄，不能用来记录病人的年龄和体重。", "抓": "搭配：抓指用手握住，不能和“年龄和体重”搭配。", "踢": "语义：踢是用脚的动作，与记录病人的数据毫无关系。"}, "sentence_index": 6, "correct_answer": "统计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计统计了明年的利润。", "explanation": "这里应该用〈预测〉。统计针对已经发生或已知的数据，明年的利润还没有发生，要用预测。"}, {"text": "售货员统计了一斤苹果。", "explanation": "这里应该用〈称〉。统计用于汇总数量，称重量要用称。"}, {"text": "经理统计了下个季度的计划。", "explanation": "这里应该用〈制定〉。统计的对象是可以汇总的数据，计划要用制定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把数据统计，结果很清楚。", "corrected_sentence": "我们把数据统计完了，结果很清楚。", "error_description": "“把”字句中的动词不能是光杆形式，需带“了”“完”等成分。原句缺少动词后的成分，正确形式是“把数据统计完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们还没统计了报名的人数。", "corrected_sentence": "他们还没统计报名的人数。", "error_description": "否定句中“没”与“了”不能同时使用，应去掉“了”，正确形式是“还没统计报名的人数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
