INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88567, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "纷纷是很多人一个接一个地做同一件事。", "primary_collocate": null, "pronunciation": "fēn fēn", "ipa": "fən˥ fən˥", "syllable_count": 2, "sentences": [{"text": "听到这个消息，大家纷纷站了起来。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学们纷纷走出教室。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店打折，很多人纷纷去买东西。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人到了以后，纷纷坐下来吃饭。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲完，学生们纷纷举手提问。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老板来了，工人们纷纷打招呼。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷，路上的人纷纷穿上了外套。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一结束，观众纷纷离开了球场。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们听说他结婚了，纷纷送来礼物。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说公司要发奖金，大家纷纷问经理。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紛紛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人一个接一个做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”强调本人动作，“大家”站起来不能说是“亲自”站起来。"}, {"text": "纷纷", "is_correct": true, "explanation": "正确：“纷纷”表示很多人接连做同一件事，符合大家接连站起来的情况。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”表示一个人单独行动，与“大家”不合。"}, {"text": "相互", "is_correct": false, "explanation": "搭配：“相互”要求彼此施动，站起来这个动作不是互相进行的。"}], "explanations": {"亲自": "语义：“亲自”强调本人动作，“大家”站起来不能说是“亲自”站起来。", "纷纷": "正确：“纷纷”表示很多人接连做同一件事，符合大家接连站起来的情况。", "独自": "语义：“独自”表示一个人单独行动，与“大家”不合。", "相互": "搭配：“相互”要求彼此施动，站起来这个动作不是互相进行的。"}, "sentence_index": 0, "correct_answer": "纷纷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人纷纷坐在角落里吃饭。", "explanation": "这里应该用〈独自〉。纷纷表示很多人接连做同一件事，一个人单独吃饭要用〈独自〉。"}, {"text": "两位选手纷纷登场。", "explanation": "这里应该用〈相继〉。纷纷强调很多人接连做同一件事，只有两位选手时要用〈相继〉。"}, {"text": "妈妈纷纷提醒我上学别迟到。", "explanation": "这里应该用〈一再〉。纷纷要求很多人接连做，一个人多次提醒要用〈一再〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擅自", "is_correct": false, "explanation": "语义：“擅自”指未经允许就做，穿外套是自然反应，语义不合。"}, {"text": "纷纷", "is_correct": true, "explanation": "正确：“纷纷”表示很多人接连做同一件事，符合天冷后大家接连穿外套的情况。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”修饰说话或喊叫，不能修饰“穿上外套”这类动作。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”要与说话或喊叫搭配，不能用来修饰穿衣服。"}], "explanations": {"擅自": "语义：“擅自”指未经允许就做，穿外套是自然反应，语义不合。", "纷纷": "正确：“纷纷”表示很多人接连做同一件事，符合天冷后大家接连穿外套的情况。", "大声": "语义：“大声”修饰说话或喊叫，不能修饰“穿上外套”这类动作。", "齐声": "搭配：“齐声”要与说话或喊叫搭配，不能用来修饰穿衣服。"}, "sentence_index": 6, "correct_answer": "纷纷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他纷纷问经理同一个问题。", "explanation": "这里应该用〈反复〉。纷纷强调很多人接连做同一件事，一个人多次问同一个问题要用〈反复〉。"}, {"text": "雨纷纷停了。", "explanation": "这里应该用〈渐渐〉。纷纷不用来说一件事慢慢变化，雨慢慢停下要用〈渐渐〉。"}, {"text": "小明纷纷吃完了三碗饭。", "explanation": "这里应该用〈一连〉。纷纷要求很多人接连做，一个人连着吃三碗要用〈一连〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们纷纷了报名参加比赛。", "corrected_sentence": "同学们纷纷报名参加比赛。", "error_description": "错误：「纷纷了报名」；正确：「纷纷报名」。「了」应附在动词之后，不能放在副词「纷纷」后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们很纷纷给老师打电话。", "corrected_sentence": "同学们纷纷给老师打电话。", "error_description": "错误：「很纷纷」；正确：「纷纷」。副词「纷纷」本身已表示程度和状态，前面不能再加程度副词「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
