INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88568, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，形容许多人或事物接连不断地出现。", "primary_collocate": null, "pronunciation": "fēn fēn", "ipa": "fən˥ fən˥", "syllable_count": 2, "sentences": [{"text": "秋天到了，树叶纷纷落下来。", "target_word": "纷纷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨以后，路边的花纷纷开了。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪花纷纷飘下来，地上白了。", "target_word": "纷纷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新年快到了，各种广告纷纷出现。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消息传出后，各种说法纷纷出现。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天一到，小草纷纷从地里长出来。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机上市以后，网上评论纷纷出现。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点纷纷打在窗户上。", "target_word": "纷纷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最近，各地的好消息纷纷传来。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事发生后，各种问题纷纷冒了出来。", "target_word": "纷纷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紛紛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "许多人或事物接连不断地出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”要求有施事的人，树叶不能“亲自”落下来。"}, {"text": "纷纷", "is_correct": true, "explanation": "正确：“纷纷”表示很多事物接连出现或落下，符合树叶接连落下的情况。"}, {"text": "故意", "is_correct": false, "explanation": "语义：落叶是自然现象，不能“故意”落下来。"}, {"text": "相互", "is_correct": false, "explanation": "搭配：“相互”要求双方彼此施动，不能说树叶“相互”落下来。"}], "explanations": {"亲自": "语义：“亲自”要求有施事的人，树叶不能“亲自”落下来。", "纷纷": "正确：“纷纷”表示很多事物接连出现或落下，符合树叶接连落下的情况。", "故意": "语义：落叶是自然现象，不能“故意”落下来。", "相互": "搭配：“相互”要求双方彼此施动，不能说树叶“相互”落下来。"}, "sentence_index": 0, "correct_answer": "纷纷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气纷纷变冷了。", "explanation": "这里应该用〈逐渐〉。纷纷形容许多人或事物接连出现，不用来说一个事物逐渐变化。"}, {"text": "他纷纷想起来了。", "explanation": "这里应该用〈忽然〉。纷纷要求许多人或事物接连出现，只有一个人时不能用。"}, {"text": "两名学生纷纷到了教室。", "explanation": "这里应该用〈陆续〉。纷纷强调许多人接连做同一件事，只有两名学生时要用〈陆续〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擅自", "is_correct": false, "explanation": "语义：“擅自”指未经允许就做，评论出现不需要谁批准，语义不合。"}, {"text": "纷纷", "is_correct": true, "explanation": "正确：“纷纷”表示很多评论接连出现，符合新手机上市后的情况。"}, {"text": "亲笔", "is_correct": false, "explanation": "语义：“亲笔”指本人亲手书写，网上评论的出现不是手写，语义不合。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”修饰说话或喊叫，不能修饰“评论出现”。"}], "explanations": {"擅自": "语义：“擅自”指未经允许就做，评论出现不需要谁批准，语义不合。", "纷纷": "正确：“纷纷”表示很多评论接连出现，符合新手机上市后的情况。", "亲笔": "语义：“亲笔”指本人亲手书写，网上评论的出现不是手写，语义不合。", "齐声": "搭配：“齐声”修饰说话或喊叫，不能修饰“评论出现”。"}, "sentence_index": 6, "correct_answer": "纷纷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店纷纷打了三天折。", "explanation": "这里应该用〈连续〉。纷纷强调许多人或事物接连出现，一家店持续多天做同一件事时要用〈连续〉。"}, {"text": "两名工人纷纷抬起了箱子。", "explanation": "这里应该用〈同时〉。纷纷强调许多人接连做同一件事，只有两名工人一起抬时要用〈同时〉。"}, {"text": "他把三箱书纷纷搬走了。", "explanation": "这里应该用〈逐一〉。纷纷强调许多人或事物接连出现，一个人一件件搬要用〈逐一〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多游客很纷纷拍照留念。", "corrected_sentence": "很多游客纷纷拍照留念。", "error_description": "错误：「很纷纷」；正确：「纷纷」。副词「纷纷」本身已表示状态，前面不能再加程度副词「很」，应直接修饰动词「拍照」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一片树叶纷纷落了下来。", "corrected_sentence": "很多树叶纷纷落了下来。", "error_description": "错误：「一片」；正确：「很多」。「纷纷」形容许多人或事物接连不断地出现，主语只有一片树叶时不能用「纷纷」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
