INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88569, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转用是换一个别的东西来用。", "primary_collocate": null, "pronunciation": "zhuǎn yòng", "ipa": "ʈʂwan˨˩˦ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这笔钱不能转用，只能买书。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间旧仓库转用来做宿舍了。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把买菜的钱转用来交房租。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器可以转用到别的工作上。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把旧车间转用做仓库。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地以前种菜，现在转用来盖房子。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把广告的钱转用到新产品上。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧衣服可以转用做抹布。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这个房间转用来放书。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经费一旦定了，就不能随便转用。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转用了", "label": "体标（了）"}, {"form": "转用过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把原有的东西挪作别的用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88569, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转用", "is_correct": true, "explanation": "正确：转用指把原有的东西挪作别的用途。"}, {"text": "专用", "is_correct": false, "explanation": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是“专门使用”，与“挪作别的用途”不同。"}, {"text": "转运", "is_correct": false, "explanation": "zhuǎn yùn 与 zhuǎn yòng 第二个字韵母不同，意思是“转移运送”，与“挪作别的用途”不同。"}, {"text": "占用", "is_correct": false, "explanation": "zhàn（第四声）与 zhuǎn（第三声）少了介音 u，声调也不同，意思是“占据使用”，与“挪作别的用途”不同。"}], "explanations": {"转用": "正确：转用指把原有的东西挪作别的用途。", "专用": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是“专门使用”，与“挪作别的用途”不同。", "转运": "zhuǎn yùn 与 zhuǎn yòng 第二个字韵母不同，意思是“转移运送”，与“挪作别的用途”不同。", "占用": "zhàn（第四声）与 zhuǎn（第三声）少了介音 u，声调也不同，意思是“占据使用”，与“挪作别的用途”不同。"}, "sentence_index": null, "correct_answer": "转用"}, "level_3": {"options": [{"text": "转用", "is_correct": true, "explanation": "正确：“这笔钱不能转用”指这笔钱不能挪作别的用途，只能买书，符合语境。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：钱不能“睡觉”，搭配不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：钱不能“唱歌”，搭配不通。"}, {"text": "思考", "is_correct": false, "explanation": "语义：钱不会思考，这里要的是“挪作别的用途”。"}], "explanations": {"转用": "正确：“这笔钱不能转用”指这笔钱不能挪作别的用途，只能买书，符合语境。", "睡觉": "搭配：钱不能“睡觉”，搭配不通。", "唱歌": "搭配：钱不能“唱歌”，搭配不通。", "思考": "语义：钱不会思考，这里要的是“挪作别的用途”。"}, "sentence_index": 0, "correct_answer": "转用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把行李转用到了车上。", "explanation": "这里应该用〈转移〉。转用指把东西挪作别的用途，不是搬运位置。"}, {"text": "这位老师把学生转用了。", "explanation": "语义：转用只用于东西、钱或方法，不用于人。"}, {"text": "他把房子转用给了朋友。", "explanation": "这里应该用〈转让〉。转用不表示把所有权交给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88569, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转用", "is_correct": true, "explanation": "正确：“公司把广告的钱转用到新产品上”指把钱挪作别的用途，符合语境。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：钱不能“涂”在产品上，搭配不通。"}, {"text": "印", "is_correct": false, "explanation": "语义：“印”指印刷文字或图案，钱不能被印到产品上。"}, {"text": "刷", "is_correct": false, "explanation": "搭配：钱不能“刷”到产品上，搭配不通。"}], "explanations": {"转用": "正确：“公司把广告的钱转用到新产品上”指把钱挪作别的用途，符合语境。", "涂": "搭配：钱不能“涂”在产品上，搭配不通。", "印": "语义：“印”指印刷文字或图案，钱不能被印到产品上。", "刷": "搭配：钱不能“刷”到产品上，搭配不通。"}, "sentence_index": 6, "correct_answer": "转用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身份转用到了新工作上。", "explanation": "语义：身份不是可以挪作别用的东西，这里不能用〈转用〉；说人调到新岗位应用〈调动〉。"}, {"text": "他的感情一旦定了，就不能随便转用。", "explanation": "语义：感情不是可以挪作别用的东西，这里不能用“转用”。"}, {"text": "这份合同一旦签了，就不能随便转用。", "explanation": "语义：合同签订后是约定，不是可以挪作别的用途的东西，这里不能用“转用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把客厅转用了做书房。", "corrected_sentence": "他把客厅转用做了书房。", "error_description": "位置错误：“了”应放在“做”之后，不能放在“做”之前。错误形式是“转用了做”，正确形式是“转用做了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂把旧设备转用了到新车间。", "corrected_sentence": "工厂把旧设备转用到了新车间。", "error_description": "了的位置错误：“了”应接在“到”之后，不能插在“转用”和“到”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
