INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改用别的东西或方法。", "primary_collocate": null, "pronunciation": "zhuǎn yòng", "ipa": "ʈʂwan˨˩˦ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "天冷了，我们转用厚被子。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方法不行，我们转用新办法吧。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司转用电子邮件联系客户。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喝咖啡了，转用绿茶。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校转用新课本已经一年了。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都转用手机付钱了。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太贵，我们转用便宜的材料。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次我们转用微波炉热菜。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们转用新机器以后更快了。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他转用另一种药。", "target_word": "转用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转用了", "label": "体标（了）"}, {"form": "转用过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "不再用原来的，改用另一种东西或方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88570, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转用", "is_correct": true, "explanation": "正确：转用指不再用原来的，改用另一种东西或方法。"}, {"text": "专用", "is_correct": false, "explanation": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是“专门使用”，与“改用”不同。"}, {"text": "转运", "is_correct": false, "explanation": "zhuǎn yùn 与 zhuǎn yòng 第二个字韵母不同，意思是“转移运送”，与“改用”不同。"}, {"text": "占用", "is_correct": false, "explanation": "zhàn（第四声）与 zhuǎn（第三声）少了介音 u，声调也不同，意思是“占据使用”，与“改用”不同。"}], "explanations": {"转用": "正确：转用指不再用原来的，改用另一种东西或方法。", "专用": "zhuān（第一声）与 zhuǎn（第三声）声调不同，意思是“专门使用”，与“改用”不同。", "转运": "zhuǎn yùn 与 zhuǎn yòng 第二个字韵母不同，意思是“转移运送”，与“改用”不同。", "占用": "zhàn（第四声）与 zhuǎn（第三声）少了介音 u，声调也不同，意思是“占据使用”，与“改用”不同。"}, "sentence_index": null, "correct_answer": "转用"}, "level_3": {"options": [{"text": "转用", "is_correct": true, "explanation": "正确：“天冷了，我们转用厚被子”指改用厚被子，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：被子不能吃，这里说的是改用。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝厚被子”搭配不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能接“厚被子”。"}], "explanations": {"转用": "正确：“天冷了，我们转用厚被子”指改用厚被子，符合语境。", "吃": "语义：被子不能吃，这里说的是改用。", "喝": "搭配：“喝厚被子”搭配不通。", "唱": "搭配：“唱”不能接“厚被子”。"}, "sentence_index": 0, "correct_answer": "转用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把注意力转用到学习上。", "explanation": "这里应该用〈转移〉。注意力是转移，不是转用；转用指改用另一种东西或方法。"}, {"text": "他把孩子转用给了邻居。", "explanation": "语义：孩子不是可以改用的东西或方法，不能说“转用”。"}, {"text": "他的态度转用了很多。", "explanation": "这里应该用〈转变〉。转变指事物或人的状态改变；转用指改用别的东西或方法，不用于态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转用", "is_correct": true, "explanation": "正确：“因为太贵，我们转用便宜的材料”指改用便宜的材料，符合语境。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：材料不能“踢”，搭配不通。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：材料不能“戴”，搭配不通。"}, {"text": "亲吻", "is_correct": false, "explanation": "语义：材料没有感情，不能被“亲吻”。"}], "explanations": {"转用": "正确：“因为太贵，我们转用便宜的材料”指改用便宜的材料，符合语境。", "踢": "搭配：材料不能“踢”，搭配不通。", "戴": "搭配：材料不能“戴”，搭配不通。", "亲吻": "语义：材料没有感情，不能被“亲吻”。"}, "sentence_index": 6, "correct_answer": "转用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生让他转用了一天来治病。", "explanation": "语义：一天是时间，不是可以改用的治疗方法，这里不能用〈转用〉。"}, {"text": "医生让他转用了一个邻居来治病。", "explanation": "语义：邻居是人，不是药物或治疗方法，这里不能用“转用”。"}, {"text": "医生让他转用了一张报纸来治病。", "explanation": "语义：报纸不是药物或治疗方法，这里不能用〈转用〉把它当作治病的手段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店没转用了环保袋。", "corrected_sentence": "这家店没转用环保袋。", "error_description": "体标错误：“没”表示否定时不能与“了”同用，“转用”后不能加“了”。错误形式是“没转用了”，正确形式是“没转用”，表示没有改用环保袋。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们转用了过这个方法，效果不错。", "corrected_sentence": "我们转用过这个方法，效果不错。", "error_description": "体标错误：“了”和“过”不能同时用在动词“转用”后面。错误形式是“转用了过”，正确形式是“转用过”，表示有过这种经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
