INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88573, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "宽容是别人做错了，你不生气，原谅他。", "primary_collocate": null, "pronunciation": "kuān róng", "ipa": "kʰwan˥ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "朋友做错了事，我宽容地原谅了他。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈宽容地看着犯错的孩子。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到了，老板却很宽容。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你这么宽容，原谅了我。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请对我宽容一点吧。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很宽容，没有怪弟弟。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟打破了杯子，姐姐很宽容。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对犯错的同学，老师总是很宽容。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要宽容一点，别生他的气。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他宽容地笑了，说没关系。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宽容地", "label": "状语形式"}, {"form": "寬容", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人做错了不生气并原谅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宽容", "is_correct": true, "explanation": "正确：“宽容”表示不生气、原谅别人的过错，与句意相符。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：“害怕”表示恐惧，与“原谅”这一宽厚的行为相冲突。"}, {"text": "狠毒", "is_correct": false, "explanation": "语义：“狠毒”形容心肠恶毒，与“原谅”的语义完全相反。"}, {"text": "冷酷", "is_correct": false, "explanation": "搭配：“冷酷”形容态度无情，不能与“原谅”所要求的宽厚态度搭配。"}], "explanations": {"宽容": "正确：“宽容”表示不生气、原谅别人的过错，与句意相符。", "害怕": "语义：“害怕”表示恐惧，与“原谅”这一宽厚的行为相冲突。", "狠毒": "语义：“狠毒”形容心肠恶毒，与“原谅”的语义完全相反。", "冷酷": "搭配：“冷酷”形容态度无情，不能与“原谅”所要求的宽厚态度搭配。"}, "sentence_index": 0, "correct_answer": "宽容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做数学题做得很宽容，一道错都没有。", "explanation": "这里应该用〈仔细〉。宽容指对别人的过错不计较，不用于描述做题的认真程度。"}, {"text": "这双鞋很宽容。", "explanation": "这里应该用〈宽松〉。宽容形容人的态度，不用于形容鞋子。"}, {"text": "他宽容地拍下了这张照片。", "explanation": "这里应该用〈认真〉。宽容指对过错不计较，不用于描述拍照的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宽容", "is_correct": true, "explanation": "正确：“宽容”表示姐姐对弟弟的过失不计较，与句意相符。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”描写身材，与“打破杯子”的语境无关，不能说明姐姐的态度。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写身材，与“打破杯子”的语境无关，不能说明姐姐的态度。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”形容气氛或心情，与“打破了杯子”的情境相矛盾。"}], "explanations": {"宽容": "正确：“宽容”表示姐姐对弟弟的过失不计较，与句意相符。", "高": "体貌：“高”描写身材，与“打破杯子”的语境无关，不能说明姐姐的态度。", "矮": "体貌：“矮”描写身材，与“打破杯子”的语境无关，不能说明姐姐的态度。", "欢乐": "语义：“欢乐”形容气氛或心情，与“打破了杯子”的情境相矛盾。"}, "sentence_index": 6, "correct_answer": "宽容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很宽容你的帮助。", "explanation": "这里应该用〈感激〉。宽容指对过错不计较，不用于表达对帮助的谢意。"}, {"text": "她的书桌很宽容。", "explanation": "这里应该用〈整齐〉。宽容形容人的态度，不用于形容物品的摆放。"}, {"text": "他学习很宽容。", "explanation": "这里应该用〈勤奋〉。宽容形容人的态度，不用于描述学习的努力程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
