INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88574, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "宽厚大度，不计较或追究。", "primary_collocate": null, "pronunciation": "kuān róng", "ipa": "kʰwan˥ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师对学生很宽容。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个宽容的人。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你对我宽容一点儿。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该对别人宽容。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸对孩子的错误很宽容。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很宽容，从不计较小事。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宽容的人朋友多。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理对新同事比较宽容。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会对年轻人应该更宽容。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的宽容让大家都很感动。", "target_word": "宽容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宽容地", "label": "状语形式"}, {"form": "寬容", "label": "繁体"}], "register": "中性", "sense_fingerprint": "宽厚大度不计较", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宽容", "is_correct": true, "explanation": "正确：“宽容”形容老师对学生宽厚不计较，与句意相符。"}, {"text": "美丽", "is_correct": false, "explanation": "体貌：“美丽”描写外貌，与老师对学生的态度无关。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或眼神，不能用来形容对学生的态度。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，与“对学生很”的语境不符。"}], "explanations": {"宽容": "正确：“宽容”形容老师对学生宽厚不计较，与句意相符。", "美丽": "体貌：“美丽”描写外貌，与老师对学生的态度无关。", "明亮": "语义：“明亮”形容光线或眼神，不能用来形容对学生的态度。", "响亮": "语义：“响亮”形容声音，与“对学生很”的语境不符。"}, "sentence_index": 0, "correct_answer": "宽容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室很宽容。", "explanation": "这里应该用〈宽敞〉。宽容形容人的态度，不用于形容空间。"}, {"text": "这条裤子很宽容。", "explanation": "这里应该用〈宽松〉。宽容形容人的态度，不用于形容衣物。"}, {"text": "他很宽容，每天都坚持锻炼。", "explanation": "这里应该用〈自律〉。宽容指对人或事不计较，与“坚持锻炼”所表达的自我约束无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宽容", "is_correct": true, "explanation": "正确：“宽容”形容宽厚大度的人，与“朋友多”的语境相符。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”指对人淡漠，与“朋友多”的语境相矛盾。"}, {"text": "高傲", "is_correct": false, "explanation": "语义：“高傲”表示看不起别人，与“朋友多”不相符。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写外形，与人的品格和交友情况无关。"}], "explanations": {"宽容": "正确：“宽容”形容宽厚大度的人，与“朋友多”的语境相符。", "冷漠": "语义：“冷漠”指对人淡漠，与“朋友多”的语境相矛盾。", "高傲": "语义：“高傲”表示看不起别人，与“朋友多”不相符。", "瘦": "体貌：“瘦”描写外形，与人的品格和交友情况无关。"}, "sentence_index": 6, "correct_answer": "宽容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张床很宽容，能睡三个人。", "explanation": "这里应该用〈宽〉。宽容形容人的态度，不用于形容床的大小。"}, {"text": "这座城市的物产很宽容。", "explanation": "这里应该用〈丰富〉。宽容形容人的态度，不用于形容物产的多少。"}, {"text": "她打扮得很宽容。", "explanation": "这里应该用〈漂亮〉。宽容形容人的态度，不用于描写打扮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她宽容的看着我，没有生气。", "corrected_sentence": "她宽容地看着我，没有生气。", "error_description": "错误：“宽容”修饰动词“看”，应该用“地”，说“宽容地看着”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对弟弟很宽容地，没有责怪他。", "corrected_sentence": "她对弟弟很宽容，没有责怪他。", "error_description": "错误：“宽容地”后须接动词作状语，此处“地”后直接接逗号，成了悬空的成分，应删去“地”，说“很宽容，没有责怪他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
