INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88577, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "近前是走到离得很近的地方。", "primary_collocate": null, "pronunciation": "jìn qián", "ipa": "tɕin˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "老师招手说：“同学们，都近前来。”", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火很大，我们谁也不敢近前。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想近前看画，可是人太多了。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗一直叫，孩子不敢近前。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请您近前一点，我听不清。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上很亮，观众都想近前看看。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上有只小鸟，我刚想近前看它，它就飞走了。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶眼睛不好，近前才能看清我。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说：“你近前来，我小声告诉你。”", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让病人的家人近前说话。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "走到离得很近的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近前", "is_correct": true, "explanation": "近前指走到离得很近的地方，正合老师招手叫同学们靠近的语境。"}, {"text": "散开", "is_correct": false, "explanation": "语义：“散开”指向四周分散，与老师招手叫大家聚拢的意思相反。"}, {"text": "退出", "is_correct": false, "explanation": "语义：“退出”指向外离开某处，与招手叫人靠近的意思相反。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬称尊贵的人到来，老师不能用它招呼学生。"}], "explanations": {"近前": "近前指走到离得很近的地方，正合老师招手叫同学们靠近的语境。", "散开": "语义：“散开”指向四周分散，与老师招手叫大家聚拢的意思相反。", "退出": "语义：“退出”指向外离开某处，与招手叫人靠近的意思相反。", "驾临": "语域：“驾临”是敬称尊贵的人到来，老师不能用它招呼学生。"}, "sentence_index": 0, "correct_answer": "近前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "期末考试近前了，同学们都在复习。", "explanation": "这里应该用〈临近〉。近前只表示在空间上走到很近的地方，说时间快到要用“临近”，“期末考试临近了”才正确。"}, {"text": "冬天近前了，天气越来越冷。", "explanation": "这里应该用〈来临〉。近前不能表示季节或时间到来，说冬天到来要用“来临”。"}, {"text": "春节近前了，大家都在准备年货。", "explanation": "这里应该用〈到来〉。近前不能表示节日快到了，这里要说“春节到来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近前", "is_correct": true, "explanation": "近前指走近，符合“想靠近小鸟，小鸟却飞走了”的情节。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是对尊贵的人到场的敬辞，不能用来形容自己走近一只小鸟。"}, {"text": "叫醒", "is_correct": false, "explanation": "语义：“叫醒”指把睡着的人唤醒，与“近前看它”的动作不符，句子不通。"}, {"text": "逗", "is_correct": false, "explanation": "语义：“逗”指逗弄取乐，与“近前看它”想靠近观察的意思不符。"}], "explanations": {"近前": "近前指走近，符合“想靠近小鸟，小鸟却飞走了”的情节。", "驾临": "语域：“驾临”是对尊贵的人到场的敬辞，不能用来形容自己走近一只小鸟。", "叫醒": "语义：“叫醒”指把睡着的人唤醒，与“近前看它”的动作不符，句子不通。", "逗": "语义：“逗”指逗弄取乐，与“近前看它”想靠近观察的意思不符。"}, "sentence_index": 6, "correct_answer": "近前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他近前参加会议。", "explanation": "这里应该用〈赶来〉。近前只表示走到近处，不表示到达某地后再去做某事。"}, {"text": "他一路从北京近前到了上海。", "explanation": "这里应该用〈走到〉。近前只表示走到很近的地方，不能用于从北京到上海这样的长距离移动。"}, {"text": "我们一起近前到了山顶。", "explanation": "这里应该用〈爬到〉。近前只表示走到近处，不能用于爬山这样的长距离移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们都近前它看热闹。", "corrected_sentence": "孩子们都近前看热闹。", "error_description": "错误形式：“近前它看热闹”中多出了“它”；正确形式：“近前看热闹”。“它”不能插在动词“近前”与后面的动词之间，删去即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老奶奶说：“孩子，你近前一个，让我看看。”", "corrected_sentence": "老奶奶说：“孩子，你近前一点，让我看看。”", "error_description": "错误形式：“近前一个”；正确形式：“近前一点”。表示走近的程度要用“一点”，不能用“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88578, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88578, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走近；靠近面前。", "primary_collocate": null, "pronunciation": "jìn qián", "ipa": "tɕin˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "将军叫士兵近前，交给他一封信。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条河很深，小孩子不要近前。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有一只大狗，我不敢近前。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢近前，轻轻敲了敲门。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在桌边，让孙子近前坐下。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展品有护栏，参观的人不能近前触摸。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一近前，就闻到了花香。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想近前打招呼，又有点不好意思。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光太暗，我得近前才看得见字。", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲向女儿招手：“来，近前让妈看看。”", "target_word": "近前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "走近；靠近面前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近前", "is_correct": true, "explanation": "近前指走到近处，将军叫士兵走近，才能把信交到他手里。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”是走开，与下一句“交给他一封信”需要士兵在近旁相矛盾。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，用于尊贵的人到场，不能用来指将军召唤士兵。"}, {"text": "退下", "is_correct": false, "explanation": "语义：“退下”是退到后面去，与“交给他一封信”需要靠近的动作相反。"}], "explanations": {"近前": "近前指走到近处，将军叫士兵走近，才能把信交到他手里。", "离开": "语义：“离开”是走开，与下一句“交给他一封信”需要士兵在近旁相矛盾。", "驾临": "语域：“驾临”是敬辞，用于尊贵的人到场，不能用来指将军召唤士兵。", "退下": "语义：“退下”是退到后面去，与“交给他一封信”需要靠近的动作相反。"}, "sentence_index": 0, "correct_answer": "近前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛近前了，选手们都很紧张。", "explanation": "这里应该用〈临近〉。近前只表示空间上走到近处，说比赛时间快到要用“临近”。"}, {"text": "寒假近前了，同学们都很兴奋。", "explanation": "这里应该用〈到来〉。近前不表示时间快到，说寒假快到要用“到来”。"}, {"text": "新年近前了，家家户户都在贴春联。", "explanation": "这里应该用〈来临〉。近前不能用于表示新年快到，要说“新年来临”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近前", "is_correct": true, "explanation": "近前指走到花的近处，正好解释“一……就闻到花香”。"}, {"text": "远去", "is_correct": false, "explanation": "语义：“远去”是走远，与“闻到花香”需要靠近花的语境矛盾。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是书面敬辞，用于尊贵人士到场，不适合这段口语叙述。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的反应，与“一走近就闻到花香”的因果不符，不合情理。"}], "explanations": {"近前": "近前指走到花的近处，正好解释“一……就闻到花香”。", "远去": "语义：“远去”是走远，与“闻到花香”需要靠近花的语境矛盾。", "莅临": "语域：“莅临”是书面敬辞，用于尊贵人士到场，不适合这段口语叙述。", "咳嗽": "语义：“咳嗽”是身体的反应，与“一走近就闻到花香”的因果不符，不合情理。"}, "sentence_index": 6, "correct_answer": "近前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他近前参观展览。", "explanation": "这里应该用〈前去〉。近前只表示走到眼前近处，不表示前往某地去做某事，要说“他前去参观展览”。"}, {"text": "她一路从广州近前到了深圳。", "explanation": "这里应该用〈走到〉。近前只表示走到很近的地方，不能用于长距离的移动。"}, {"text": "他们一起近前到了山顶。", "explanation": "这里应该用〈爬到〉。近前不能用于爬山这样的长距离移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们近前它听令。", "corrected_sentence": "士兵们近前听令。", "error_description": "错误形式：“近前它听令”中多出了“它”；正确形式：“近前听令”。“它”不能插在动词“近前”与“听令”之间，删去即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说：“同学，你近前一个，把题读出来。”", "corrected_sentence": "老师说：“同学，你近前一点，把题读出来。”", "error_description": "错误形式：“近前一个”；正确形式：“近前一点”。表示走近的程度要用“一点”，不能用“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
