INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88581, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88581, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "腿是身体下面用来走路的两根长长的部分。", "primary_collocate": null, "pronunciation": "tuǐ", "ipa": "tʰweɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我今天走了很多路，腿很累。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿很长，跑得很快。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的腿受伤了，不能上学。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐了一下午，我的腿都麻了。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天跑步，腿上有力气。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩把腿放在椅子上。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的两条腿都很疼。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站着不动，腿一直在发抖。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山以后，我的腿很酸。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的腿一个月就能好。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "大腿", "label": "复合"}, {"form": "小腿", "label": "复合"}], "register": "中性", "sense_fingerprint": "人身体下部用来走路、跑步的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腿", "is_correct": true, "explanation": "走路要靠腿，走了很多路之后腿会累，符合语境。"}, {"text": "手", "is_correct": false, "explanation": "语义：走路靠腿，不靠手，手不会因为走了很多路而累。"}, {"text": "嘴", "is_correct": false, "explanation": "语义：嘴多因说话而累，与“走了很多路”的语境冲突。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：“累”多用于人或身体机能，头发不会累，不能与“很累”搭配。"}], "explanations": {"腿": "走路要靠腿，走了很多路之后腿会累，符合语境。", "手": "语义：走路靠腿，不靠手，手不会因为走了很多路而累。", "嘴": "语义：嘴多因说话而累，与“走了很多路”的语境冲突。", "头发": "搭配：“累”多用于人或身体机能，头发不会累，不能与“很累”搭配。"}, "sentence_index": 0, "correct_answer": "腿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的腿穿了一双新鞋，走路很舒服。", "explanation": "这里应该用〈脚〉。鞋是穿在脚上的，腿不能穿鞋。"}, {"text": "我用腿拿着杯子，喝了一口水。", "explanation": "这里应该用〈手〉。拿杯子要用手，腿不能用来拿东西。"}, {"text": "我的腿看不清字了，明天去配一副眼镜。", "explanation": "这里应该用〈眼睛〉。看字要用眼睛，腿不能用来看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腿", "is_correct": true, "explanation": "“两条腿”是人的身体部位，会疼，符合语境。"}, {"text": "裤子", "is_correct": false, "explanation": "语义：裤子不会疼，与“都很疼”冲突。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是“我的”身体部位，“我的两条鱼都很疼”不符合常识。"}, {"text": "围巾", "is_correct": false, "explanation": "搭配：“疼”只用于身体部位，围巾不能说疼。"}], "explanations": {"腿": "“两条腿”是人的身体部位，会疼，符合语境。", "裤子": "语义：裤子不会疼，与“都很疼”冲突。", "鱼": "语义：鱼不是“我的”身体部位，“我的两条鱼都很疼”不符合常识。", "围巾": "搭配：“疼”只用于身体部位，围巾不能说疼。"}, "sentence_index": 6, "correct_answer": "腿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的腿很灵，听见了远处的声音。", "explanation": "这里应该用〈耳朵〉。听声音要用耳朵，腿不能听。"}, {"text": "老师叫他的名字，他马上抬起腿来回答问题。", "explanation": "这里应该用〈头〉。回答问题时抬起来的是头，不是腿。"}, {"text": "他唱了一晚上，腿哑了。", "explanation": "这里应该用〈嗓子〉。唱歌累了会哑的是嗓子，腿不会哑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑完步，两个腿都很累。", "corrected_sentence": "他跑完步，两条腿都很累。", "error_description": "量词错误：“腿”应用“条”计量，“两个”应改为“两条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他累了，把腿放在椅子。", "corrected_sentence": "他累了，把腿放在椅子上。", "error_description": "缺少方位词：“放在”后面表示地点时，“椅子”要加方位词“上”，说“把腿放在椅子上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
