INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和动物用来支撑身体和行走的部分。", "primary_collocate": null, "pronunciation": "tuǐ", "ipa": "tʰweɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这只小狗有四条腿。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟的腿又细又短。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫抬起一条腿，想抓蝴蝶。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长颈鹿的腿特别长。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛有八条腿。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马的腿很有力气，跑得很快。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡用两条腿走路。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只兔子的腿受伤了。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙的腿很长，跳得很高。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人和狗都用腿走路，鱼没有腿。", "target_word": "腿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "大腿", "label": "复合"}, {"form": "小腿", "label": "复合"}], "register": "中性", "sense_fingerprint": "人和动物支撑身体、行走的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腿", "is_correct": true, "explanation": "“四条腿”是狗的身体部位，符合语境。"}, {"text": "裤子", "is_correct": false, "explanation": "语义：小狗不穿裤子，“有四条裤子”与语境不符。"}, {"text": "领带", "is_correct": false, "explanation": "语义：小狗不系领带，“有四条领带”不合常理。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：“四条鱼”说法本身没错，但句子讲的是小狗身体的部位，鱼不是小狗身上的部分。"}], "explanations": {"腿": "“四条腿”是狗的身体部位，符合语境。", "裤子": "语义：小狗不穿裤子，“有四条裤子”与语境不符。", "领带": "语义：小狗不系领带，“有四条领带”不合常理。", "鱼": "语义：“四条鱼”说法本身没错，但句子讲的是小狗身体的部位，鱼不是小狗身上的部分。"}, "sentence_index": 0, "correct_answer": "腿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蝴蝶用腿飞到花上，飞得很慢。", "explanation": "这里应该用〈翅膀〉。蝴蝶飞要靠翅膀，腿不能用来飞。"}, {"text": "这只狗高兴地摇着腿，跑来跑去。", "explanation": "这里应该用〈尾巴〉。狗高兴时摇的是尾巴，腿不能用来摇。"}, {"text": "猫在夜里用腿看东西，看得很清楚。", "explanation": "这里应该用〈眼睛〉。在夜里看东西要用眼睛，腿不能用来看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腿", "is_correct": true, "explanation": "鸡用两条腿走路，符合常识和语境。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：“两条绳子”说法没错，但绳子不能用来走路，与“鸡”的行为不符。"}, {"text": "带子", "is_correct": false, "explanation": "语义：带子不能用来走路，与“鸡”的行为不符。"}, {"text": "蛇", "is_correct": false, "explanation": "语义：蛇没有腿，不能用蛇走路，与常识冲突。"}], "explanations": {"腿": "鸡用两条腿走路，符合常识和语境。", "绳子": "语义：“两条绳子”说法没错，但绳子不能用来走路，与“鸡”的行为不符。", "带子": "语义：带子不能用来走路，与“鸡”的行为不符。", "蛇": "语义：蛇没有腿，不能用蛇走路，与常识冲突。"}, "sentence_index": 6, "correct_answer": "腿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鸟用腿啄虫子，吃得很快。", "explanation": "这里应该用〈嘴〉。啄虫子要用嘴，鸟的腿不能啄东西。"}, {"text": "猫的腿很灵，能听到老鼠的声音。", "explanation": "这里应该用〈耳朵〉。听声音要用耳朵，腿不能听。"}, {"text": "公鸡每天早上用腿打鸣，叫得很响。", "explanation": "这里应该用〈嗓子〉。打鸣要用嗓子，腿不能发声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小猫用两个后腿站了起来。", "corrected_sentence": "这只小猫用两条后腿站了起来。", "error_description": "量词错误：“腿”应用“条”计量，“两个”应改为“两条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只母鸡的两个腿很细。", "corrected_sentence": "这只母鸡的两条腿很细。", "error_description": "量词错误：“腿”应用“条”计量，“两个”应改为“两条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
