INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88583, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回避是有意躲开某人、不去见面，或刻意不去说某件事。", "primary_collocate": null, "pronunciation": "huí bì", "ipa": "xweɪ˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "他看见老板，赶紧回避了。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直回避我的目光。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问到年龄时，他回避了这个问题。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别回避我，我们谈谈吧。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回避记者，不接受采访。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有矛盾就要说，不能总是回避。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回避着我，好像不想见面。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一见到前女友就想回避。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问他为什么迟到，他回避不答。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不应该回避这个话题。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回避了", "label": "体标"}, {"form": "回避过", "label": "体标"}, {"form": "回避着", "label": "体标"}], "register": "中性", "sense_fingerprint": "躲开某人或不谈某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回避", "is_correct": true, "explanation": "“回避”指躲开，与“看见老板，赶紧”的情境相符，符合句意。"}, {"text": "报销", "is_correct": false, "explanation": "语义：“报销”指费用报给单位核销，与“看见老板”的情境无关。"}, {"text": "注视", "is_correct": false, "explanation": "语义：“注视”是长时间地看，与“赶紧”的急促动作矛盾。"}, {"text": "面对", "is_correct": false, "explanation": "配价：“面对”后要带宾语（如“面对老板”），这里缺少宾语，句意不完整。"}], "explanations": {"回避": "“回避”指躲开，与“看见老板，赶紧”的情境相符，符合句意。", "报销": "语义：“报销”指费用报给单位核销，与“看见老板”的情境无关。", "注视": "语义：“注视”是长时间地看，与“赶紧”的急促动作矛盾。", "面对": "配价：“面对”后要带宾语（如“面对老板”），这里缺少宾语，句意不完整。"}, "sentence_index": 0, "correct_answer": "回避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他回避了对手的拳头。", "explanation": "这里应该用〈闪避〉。回避指躲开人或刻意不谈的事，不用于躲开迎面打来的拳头。"}, {"text": "为了安全，司机尽量回避急刹车。", "explanation": "这里应该用〈避免〉。回避多指躲开人或刻意不谈的事，要表示防止某种动作或情况出现时用“避免”。"}, {"text": "他回避了路上的水坑。", "explanation": "这里应该用〈绕开〉。回避不用于躲开路上的水坑等实物，此处应说“绕开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回避", "is_correct": true, "explanation": "“回避”指躲开，与“好像不想见面”的态度相符，符合句意。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”表示欢迎，与“好像不想见面”矛盾。"}, {"text": "陪伴", "is_correct": false, "explanation": "语义：“陪伴”表示待在一起，与“好像不想见面”矛盾。"}, {"text": "接见", "is_correct": false, "explanation": "语域：“接见”多用于领导或外宾，是正式用语，不用于私人之间的相处。"}], "explanations": {"回避": "“回避”指躲开，与“好像不想见面”的态度相符，符合句意。", "迎接": "语义：“迎接”表示欢迎，与“好像不想见面”矛盾。", "陪伴": "语义：“陪伴”表示待在一起，与“好像不想见面”矛盾。", "接见": "语域：“接见”多用于领导或外宾，是正式用语，不用于私人之间的相处。"}, "sentence_index": 6, "correct_answer": "回避"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他回避大雨，跑进了商店。", "explanation": "这里应该用〈躲避〉。回避多指避开人或刻意不谈的事，不用于躲避大雨等自然现象。"}, {"text": "他回避了迎面而来的汽车。", "explanation": "这里应该用〈躲开〉。回避不用于躲开迎面驶来的车辆。"}, {"text": "他回避了咬人的狗。", "explanation": "这里应该用〈避开〉。回避指躲开人或刻意不谈的事，不用于躲开狗等动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从来没回避了这个问题。", "corrected_sentence": "我从来没回避过这个问题。", "error_description": "“从来没……了”的说法错误。否定曾经有过的经历要用“过”，应说“从来没回避过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事他回避很巧妙，没人发现。", "corrected_sentence": "这件事他回避得很巧妙，没人发现。", "error_description": "“回避很巧妙”漏了“得”，错误。应说“回避得很巧妙”，用“得”连接动词和程度补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88584, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
