INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88584, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不愿正视或面对问题、责任、现实等事情。", "primary_collocate": null, "pronunciation": "huí bì", "ipa": "xweɪ˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "面对困难，不要回避，要想办法解决。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是回避责任。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回避现实解决不了问题。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回避自己的错误很多年了。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成绩不好，但他没有回避问题。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你越回避压力，压力越大。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人遇到问题就回避。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回避了自己真实的感受。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回避问题不是好办法。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子犯了错，家长不应该回避，要认真教育。", "target_word": "回避", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回避了", "label": "体标"}, {"form": "回避过", "label": "体标"}, {"form": "回避着", "label": "体标"}], "register": "中性", "sense_fingerprint": "不愿面对问题、责任或现实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回避", "is_correct": true, "explanation": "“回避”指躲开、不愿面对，与“不要……要想办法解决”的语境相符，符合句意。"}, {"text": "享受", "is_correct": false, "explanation": "语义：困难不能用来“享受”，与后句“要想办法解决”的语境矛盾。"}, {"text": "解决", "is_correct": false, "explanation": "语义：“不要解决”与后句“要想办法解决”意思矛盾，句意不通。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：困难不值得“庆祝”，与“要想办法解决”的语境不合，句意不通。"}], "explanations": {"回避": "“回避”指躲开、不愿面对，与“不要……要想办法解决”的语境相符，符合句意。", "享受": "语义：困难不能用来“享受”，与后句“要想办法解决”的语境矛盾。", "解决": "语义：“不要解决”与后句“要想办法解决”意思矛盾，句意不通。", "庆祝": "语义：困难不值得“庆祝”，与“要想办法解决”的语境不合，句意不通。"}, "sentence_index": 0, "correct_answer": "回避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他回避了迎面砸来的石头。", "explanation": "这里应该用〈闪避〉。此处的“回避”不是不愿面对问题，而是躲开实物；躲开迎面砸来的石头应说“闪避”。"}, {"text": "天冷的时候，他总是回避吹冷风。", "explanation": "这里应该用〈避免〉。回避多指躲开人或不愿面对的事，表示防止某种情况出现时要说“避免”。"}, {"text": "他回避了路上的积水。", "explanation": "这里应该用〈绕开〉。回避不用于躲开积水等实物，此处应说“绕开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回避", "is_correct": true, "explanation": "“回避”指躲开、不愿面对，与“遇到问题就”的态度相符，符合句意。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”指重视对方，与“遇到问题就”的消极态度不合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示接纳、喜爱，与“遇到问题”的态度矛盾，不能说“欢迎问题”。"}, {"text": "制造", "is_correct": false, "explanation": "配价：“制造”后要带宾语（如“制造麻烦”），单用“遇到问题就制造”句意不完整。"}], "explanations": {"回避": "“回避”指躲开、不愿面对，与“遇到问题就”的态度相符，符合句意。", "尊重": "语义：“尊重”指重视对方，与“遇到问题就”的消极态度不合。", "欢迎": "语义：“欢迎”表示接纳、喜爱，与“遇到问题”的态度矛盾，不能说“欢迎问题”。", "制造": "配价：“制造”后要带宾语（如“制造麻烦”），单用“遇到问题就制造”句意不完整。"}, "sentence_index": 6, "correct_answer": "回避"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手回避了飞来的球。", "explanation": "这里应该用〈挡住〉。“回避”表示躲开或不愿面对，不用于用手挡住飞来的球。"}, {"text": "他闪身回避了飞来的木棍。", "explanation": "这里应该用〈躲过〉。回避不用于躲过飞来的木棍等实物。"}, {"text": "司机主动回避了行人。", "explanation": "这里应该用〈避让〉。此句说的是汽车让路，不是不愿面对问题或责任，让行人应说“避让”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从没回避了自己的错误。", "corrected_sentence": "他从没回避过自己的错误。", "error_description": "“从没……了”的说法错误。否定曾经有过的经历要用“过”，应说“从没回避过”，不说“回避了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事他回避过一个。", "corrected_sentence": "这件事他回避过一次。", "error_description": "“回避过一个”的量词错误。“一个”是用来数人或物的，表示动作次数要用“一次”，应说“回避过一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
