INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88585, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小管是又细又小的管子。", "primary_collocate": null, "pronunciation": "xiǎo guǎn", "ipa": "ɕjɑʊ˨˩˦ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "花园里的水是从小管流出来的。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根小管又细又长。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用小管给花浇水。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小管里塞了一点儿纸。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着一根小管吹泡泡。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小管是铜做的。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根小管太细，水流不过去。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把小管接在大管上。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在商店买了几根小管。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小管里有空气，所以会响。", "target_word": "小管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根小管", "label": "量词"}], "register": "中性", "sense_fingerprint": "又细又小的管子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc8d081-6bea-4594-9ad4-67f2274bb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88585, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小管", "is_correct": true, "explanation": "小管：细小的管子，水可以从里面流出来，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包里装书本，园里的水不会从书包里流出来。"}, {"text": "信封", "is_correct": false, "explanation": "搭配：信封是装信的纸袋，不说水从信封里流出来。"}, {"text": "柜台", "is_correct": false, "explanation": "语义：柜台是售货的台子，不是水的来源。"}], "explanations": {"小管": "小管：细小的管子，水可以从里面流出来，符合句意。", "书包": "语义：书包里装书本，园里的水不会从书包里流出来。", "信封": "搭配：信封是装信的纸袋，不说水从信封里流出来。", "柜台": "语义：柜台是售货的台子，不是水的来源。"}, "sentence_index": 0, "correct_answer": "小管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工地上堆着十几根小管，每根都粗得要两个人抬。", "explanation": "这里应该用〈钢管〉。“小管”指又细又小的管子，粗得要两个人抬的钢管不能说“小管”。"}, {"text": "这根小管又粗又短。", "explanation": "这里应该用〈管子〉。“小管”指又细又小的管子，形容又粗又短的管子不能用“小管”。"}, {"text": "这根小管重达五百斤，只能靠起重机吊起来。", "explanation": "这里应该用〈管子〉。“小管”指又细又小的管子，重达五百斤的管子不能说“小管”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88585, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小管", "is_correct": true, "explanation": "小管：细小的管子，正符合“太细”和“水流不过去”的语境。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子用来捆扎，不是让水流过的器物。"}, {"text": "木棍", "is_correct": false, "explanation": "语义：木棍是实心的，不是能通水的管状物，与句意不合。"}, {"text": "头发", "is_correct": false, "explanation": "语义：头发不是通水的管子，“这根头发太细，水流不过去”不合常理。"}], "explanations": {"小管": "小管：细小的管子，正符合“太细”和“水流不过去”的语境。", "绳子": "语义：绳子用来捆扎，不是让水流过的器物。", "木棍": "语义：木棍是实心的，不是能通水的管状物，与句意不合。", "头发": "语义：头发不是通水的管子，“这根头发太细，水流不过去”不合常理。"}, "sentence_index": 6, "correct_answer": "小管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的小管又粗又硬。", "explanation": "这里应该用〈水管〉。“小管”指又细又小的管子，形容粗硬的水管不能说“小管”。"}, {"text": "这条小管埋在地下排污，直径有两尺。", "explanation": "这里应该用〈排污管〉。“小管”指细小的管子，直径两尺的地下排污管要说“排污管”。"}, {"text": "工人用两根小管焊接，做成了大桥的钢梁。", "explanation": "这里应该用〈钢梁〉。“小管”指细小的管子，大桥的承重钢梁不能说“小管”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一张小管又细又长，可以用来穿线。", "corrected_sentence": "一根小管又细又长，可以用来穿线。", "error_description": "量词错误：“小管”应用量词“根”，不用“张”。错误形式是「一张小管」，正确形式是「一根小管」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把一张小管接在大管上。", "corrected_sentence": "工人把一根小管接在大管上。", "error_description": "量词错误：“小管”应用量词“根”，“张”用于平面的东西。错误形式是「一张小管」，正确形式是「一根小管」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
