INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88587, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "自从是说从一个时间起，一直到现在。", "primary_collocate": null, "pronunciation": "zì cóng", "ipa": "tsɨ˥˩ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "自从来中国，我天天吃米饭。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从上了大学，他很少回家。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从生病以后，奶奶不再出门了。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从星期一以来，天气一直很冷。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从开学以来，我们每天都有作业。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从换了工作，哥哥一直很忙。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从十岁起，她就喜欢画画。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从弟弟出生，家里热闹多了。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从那次考试以后，他学习更努力了。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从昨天下雨以来，路上人很少。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从某个时间起一直持续到现在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自从", "is_correct": true, "explanation": "正确：“自从”表示从“来中国”这个时间起一直持续到现在，符合句意。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据，“来中国”不能作为依据，句意不通。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人做事，“来中国”不能代替人做事，句意不通。"}, {"text": "朝", "is_correct": false, "explanation": "配价：“朝”引出方向，“来中国”不能作为方向，句意不通。"}], "explanations": {"自从": "正确：“自从”表示从“来中国”这个时间起一直持续到现在，符合句意。", "按照": "语义：“按照”表示依据，“来中国”不能作为依据，句意不通。", "替": "语义：“替”表示代替某人做事，“来中国”不能代替人做事，句意不通。", "朝": "配价：“朝”引出方向，“来中国”不能作为方向，句意不通。"}, "sentence_index": 0, "correct_answer": "自从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自从下个月起，我们开始学习。", "explanation": "这里应该用〈从〉。“自从”强调已经开始并持续到现在，“下个月”还没到，应该用〈从〉。"}, {"text": "自从他很聪明，我很佩服他。", "explanation": "这里应该用〈因为〉。“自从”引出的是时间起点，“他很聪明”是原因，应该用〈因为〉。"}, {"text": "自从现在为止，他已经来了三次。", "explanation": "这里应该用〈到〉。“自从”表示从某时开始，“到……为止”表示持续到某时，应该用〈到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自从", "is_correct": true, "explanation": "正确：“自从”表示从“十岁起”一直持续到现在，符合句意。"}, {"text": "沿着", "is_correct": false, "explanation": "配价：“沿着”需要路线作宾语，“十岁起”不是路线，句意不通。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“十岁起”不是目的，句意不通。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”引出对象，“十岁起”不能作为对象，句意不通。"}], "explanations": {"自从": "正确：“自从”表示从“十岁起”一直持续到现在，符合句意。", "沿着": "配价：“沿着”需要路线作宾语，“十岁起”不是路线，句意不通。", "为了": "语义：“为了”表示目的，“十岁起”不是目的，句意不通。", "向": "配价：“向”引出对象，“十岁起”不能作为对象，句意不通。"}, "sentence_index": 6, "correct_answer": "自从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "自从房间里，他一直在看书。", "explanation": "这里应该用〈在〉。“自从”只能引出时间起点，“房间里”是处所，表示地点应该用〈在〉。"}, {"text": "自从这个问题，大家的看法不一样。", "explanation": "这里应该用〈对于〉。“自从”只能引出时间起点，不能引出谈论的对象，应该用〈对于〉。"}, {"text": "自从实力，他赢了比赛。", "explanation": "这里应该用〈凭〉。“自从”只能引出时间起点，“实力”不是时间，表示凭借应该用〈凭〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自从的来中国，我一直很想家。", "corrected_sentence": "自从来中国，我一直很想家。", "error_description": "错误：“自从”后面不能加“的”。正确：应删去“的”，即“自从来中国，我一直很想家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自从了搬到这里起，他就喜欢跑步。", "corrected_sentence": "自从搬到这里起，他就喜欢跑步。", "error_description": "错误：“自从”后面不能加“了”。正确：应删去“了”，即“自从搬到这里起，他就喜欢跑步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
