INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88588, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示从过去某个时间开始。", "primary_collocate": null, "pronunciation": "zì cóng", "ipa": "tsɨ˥˩ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "自从去年起，他就住在北京。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从上个月起，我每天都跑步。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从搬家以后，我上班很方便。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从毕业，她一直在银行工作。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从春天来了，花园里很漂亮。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从认识你，我的生活不一样了。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从那天起，他再也没喝过酒。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从前年夏天，我就没见过他。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从听了这个故事，孩子爱上了读书。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从买了手机，爸爸每天都看新闻。", "target_word": "自从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示从过去某个时间点开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自从", "is_correct": true, "explanation": "正确：“自从”引出“去年”这个时间起点，符合句意。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据某种标准或办法，“去年”不能作为依据，句意不通。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“去年”不是目的，句意不通。"}, {"text": "沿着", "is_correct": false, "explanation": "配价：“沿着”需要路线作宾语，“去年”不是路线，句意不通。"}], "explanations": {"自从": "正确：“自从”引出“去年”这个时间起点，符合句意。", "按照": "语义：“按照”表示依据某种标准或办法，“去年”不能作为依据，句意不通。", "为了": "语义：“为了”表示目的，“去年”不是目的，句意不通。", "沿着": "配价：“沿着”需要路线作宾语，“去年”不是路线，句意不通。"}, "sentence_index": 0, "correct_answer": "自从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自从明天起，我们开始复习。", "explanation": "这里应该用〈从〉。“自从”只能引出已经开始的过去时间，“明天”还没到，应该用〈从〉。"}, {"text": "自从经验，他很会做饭。", "explanation": "这里应该用〈凭〉。“自从”只能引出时间起点，“经验”不是时间，表示凭借应该用〈凭〉。"}, {"text": "自从现在，他还没回来。", "explanation": "这里应该用〈直到〉。“自从”表示从某时开始，“还没回来”表示持续到某时，应该用〈直到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自从", "is_correct": true, "explanation": "正确：“自从”引出“那天起”这个时间起点，符合句意。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替，“那天起”不能代替人做事，句意不通。"}, {"text": "朝", "is_correct": false, "explanation": "配价：“朝”引出方向，“那天起”不能作为方向，句意不通。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”引出对象，“那天起”不能作为对象，句意不通。"}], "explanations": {"自从": "正确：“自从”引出“那天起”这个时间起点，符合句意。", "替": "语义：“替”表示代替，“那天起”不能代替人做事，句意不通。", "朝": "配价：“朝”引出方向，“那天起”不能作为方向，句意不通。", "向": "配价：“向”引出对象，“那天起”不能作为对象，句意不通。"}, "sentence_index": 6, "correct_answer": "自从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "自从健康，她每天早起。", "explanation": "这里应该用〈为了〉。“自从”只能引出时间起点，“健康”不是时间，表示目的应该用〈为了〉。"}, {"text": "自从规则，比赛要公平进行。", "explanation": "这里应该用〈按照〉。“自从”只能引出时间起点，“规则”不是时间；表示依据应该用〈按照〉。"}, {"text": "自从我，这是一个好机会。", "explanation": "这里应该用〈对于〉。“自从”只能引出时间，不能引出谈论的对象，应该用〈对于〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自从的去年，他就没再回家。", "corrected_sentence": "自从去年，他就没再回家。", "error_description": "错误：“自从”后面不能加“的”。正确：应删去“的”，即“自从去年，他就没再回家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自从了春节起，他们每天都练习。", "corrected_sentence": "自从春节起，他们每天都练习。", "error_description": "错误：“自从”后面不能加“了”。正确：“自从”是介词，应直接接时间词语，写成“自从春节起，他们每天都练习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
