INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88589, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "进士是古时候考中最高一级考试的人，可以当官。", "primary_collocate": null, "pronunciation": "jìn shì", "ipa": "tɕin˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他考上了进士，后来当了官。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，进士是最高一级考试考中的人。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位进士在县里当官。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷家的老房子里，住过一位进士。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想当进士，要先读很多年书。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里出了一位进士，大家都很高兴。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲希望儿子考中进士。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位进士后来当上了大官。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进士可以当官，所以人人都想考。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写着一位进士的故事。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "進士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "古时候考中最高一级考试、可以当官的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88589, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进士", "is_correct": true, "explanation": "进士：古代考试考得最好、可以当官的人，即本题的目标词。"}, {"text": "进食", "is_correct": false, "explanation": "进食（shí，第二声）与 shì（第四声）声调不同，意思是吃东西。"}, {"text": "禁食", "is_correct": false, "explanation": "禁食（shí，第二声）与 shì（第四声）声调不同，意思是不吃东西。"}, {"text": "近似", "is_correct": false, "explanation": "近似（sì，第四声）与 shì（第四声）声母不同，sh 与 s 相混，意思是相近。"}, {"text": "金饰", "is_correct": false, "explanation": "金饰（jīn，第一声）与 jìn（第四声）声调不同，意思是金子做的首饰。"}], "explanations": {"进士": "进士：古代考试考得最好、可以当官的人，即本题的目标词。", "进食": "进食（shí，第二声）与 shì（第四声）声调不同，意思是吃东西。", "禁食": "禁食（shí，第二声）与 shì（第四声）声调不同，意思是不吃东西。", "近似": "近似（sì，第四声）与 shì（第四声）声母不同，sh 与 s 相混，意思是相近。", "金饰": "金饰（jīn，第一声）与 jìn（第四声）声调不同，意思是金子做的首饰。"}, "sentence_index": null, "correct_answer": "进士"}, "level_3": {"options": [{"text": "进士", "is_correct": true, "explanation": "进士：古代科举中考中的人，可以与“考上”“当官”搭配。"}, {"text": "农民", "is_correct": false, "explanation": "搭配：“考上”用于学校、资格或职位，不能说考上农民。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能参加考试，“考上了石头”没有意义。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“考上”的对象是学校或职位，不能说考上公园。"}], "explanations": {"进士": "进士：古代科举中考中的人，可以与“考上”“当官”搭配。", "农民": "搭配：“考上”用于学校、资格或职位，不能说考上农民。", "石头": "语义：石头不能参加考试，“考上了石头”没有意义。", "公园": "搭配：“考上”的对象是学校或职位，不能说考上公园。"}, "sentence_index": 0, "correct_answer": "进士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他通过了乡试，成了进士。", "explanation": "这里应该用〈举人〉。乡试及格的是举人，进士要通过殿试。"}, {"text": "他是一名进士，明年要参加会试。", "explanation": "这里应该用〈考生〉。进士已经通过会试和殿试，不会再去参加会试。"}, {"text": "他还是个进士，没有考上举人。", "explanation": "这里应该用〈秀才〉。进士的功名高于举人，不可能还没考上举人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进士", "is_correct": true, "explanation": "进士：科举考试中考中的人，与“考中”搭配自然。"}, {"text": "冠军", "is_correct": false, "explanation": "搭配：“考中”用于考试和资格，冠军要靠比赛获得，不能说考中冠军。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以考中的对象，句意不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不能被考中，这里句意不通。"}], "explanations": {"进士": "进士：科举考试中考中的人，与“考中”搭配自然。", "冠军": "搭配：“考中”用于考试和资格，冠军要靠比赛获得，不能说考中冠军。", "冰箱": "语义：冰箱不是可以考中的对象，句意不通。", "教室": "语义：教室不能被考中，这里句意不通。"}, "sentence_index": 6, "correct_answer": "进士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的父亲是一名进士，每天在田里种菜。", "explanation": "这里应该用〈农民〉。进士是科举考中的功名，每天在田里种菜的是农民。"}, {"text": "他的母亲是一名进士，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。进士是科举功名，在医院给病人看病的是医生。"}, {"text": "他的哥哥是一位进士，每天开出租车。", "explanation": "这里应该用〈司机〉。进士是科举功名，开出租车的是司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他二十岁就考中着进士。", "corrected_sentence": "他二十岁就考中了进士。", "error_description": "“考中”后应用时态助词“了”表示动作已完成，此处误用“着”（表示持续状态）；应说“考中了进士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人年轻时是一只进士，村里人都很敬重他。", "corrected_sentence": "这位老人年轻时是一位进士，村里人都很敬重他。", "error_description": "“只”是动物的量词，指人应该用“位”；此处量词“只”应改为“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
