INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中国科举考试中殿试及格的人。", "primary_collocate": null, "pronunciation": "jìn shì", "ipa": "tɕin˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "古代考完殿试，及格的人就是进士。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他通过了殿试，成了进士。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子一共出过三位进士。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殿试以后，皇帝公布了新进士的名单。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朝时，他是全国有名的进士。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三十岁才中进士。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上贴着新进士的名单。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位进士的字写得很漂亮。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有通过殿试的人，才能叫进士。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一位进士的故事。", "target_word": "进士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "進士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "科举殿试及格的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings 