sed = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进士", "is_correct": true, "explanation": "进士：殿试及格、列入名单的人，与“新”“名单”搭配自然。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能列入名单，“新冰箱的名单”句意不通。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不是考试及格的人，不能列入这种名单。"}, {"text": "娃", "is_correct": false, "explanation": "语义：“娃”指小孩，不能列入进士的名单，“新娃的名单”句意不通。"}], "explanations": {"进士": "进士：殿试及格、列入名单的人，与“新”“名单”搭配自然。", "冰箱": "语义：冰箱不能列入名单，“新冰箱的名单”句意不通。", "老虎": "语义：老虎不是考试及格的人，不能列入这种名单。", "娃": "语义：“娃”指小孩，不能列入进士的名单，“新娃的名单”句意不通。"}, "sentence_index": 6, "correct_answer": "进士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈是一名进士，每天在饭店做菜。", "explanation": "这里应该用〈厨师〉。进士是科举功名，在饭店做菜的是厨师。"}, {"text": "姐姐是一名进士，每天在医院打针。", "explanation": "这里应该用〈护士〉。进士是科举功名，在医院打针的是护士。"}, {"text": "叔叔是一名进士，每天在街上指挥交通。", "explanation": "这里应该用〈警察〉。进士是科举功名，在街上指挥交通的是警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他三十岁那年考中着进士。", "corrected_sentence": "他三十岁那年考中了进士。", "error_description": "“考中”后应用时态助词“了”表示动作已完成，此处误用“着”（表示持续状态）；应说“考中了进士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "县里的人都认识那只进士。", "corrected_sentence": "县里的人都认识那位进士。", "error_description": "“只”是动物的量词，指人应该用“位”；此处量词“只”应改为“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
