INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88591, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "屋子是人住的房间。", "primary_collocate": null, "pronunciation": "wū zi", "ipa": "u˥˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "我的屋子在二楼。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一回到屋子就睡觉了。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹把屋子布置得很漂亮。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子里很暖和，我不想出去。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先把你的屋子收拾一下。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子住着两个学生。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都打扫自己的屋子。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上屋子里的灯亮着。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想租一间便宜的屋子。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进屋子，关上了门。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}], "register": "口语", "sense_fingerprint": "人居住的房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88591, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋子", "is_correct": true, "explanation": "“屋子”指人住的房间，“我的屋子”可以在二楼。"}, {"text": "地窖", "is_correct": false, "explanation": "语义：地窖在地下，不会在二楼。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是可以居住的房间，不能说“在二楼”。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不作居住的地方，不与“我的……在二楼”搭配。"}], "explanations": {"屋子": "“屋子”指人住的房间，“我的屋子”可以在二楼。", "地窖": "语义：地窖在地下，不会在二楼。", "海洋": "语义：海洋不是可以居住的房间，不能说“在二楼”。", "天空": "搭配：“天空”不作居住的地方，不与“我的……在二楼”搭配。"}, "sentence_index": 0, "correct_answer": "屋子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在超市买了一只屋子。", "explanation": "量词错误：〈只〉用于动物，屋子应该用〈间〉。"}, {"text": "这座屋子有五层，每层都很暖和。", "explanation": "这里应该用〈房子〉。屋子指房间或小屋，不用来说五层的楼房。"}, {"text": "我们家有一张屋子。", "explanation": "量词错误：〈张〉用于平面的东西，屋子应该用〈间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88591, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屋子", "is_correct": true, "explanation": "“打扫”的对象可以是房间，“屋子”正合适。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“打扫”不与“作业”搭配，作业应说“完成”或“做”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被“打扫”，应说“净化”或“清新”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是一种活动，不能被“打扫”。"}], "explanations": {"屋子": "“打扫”的对象可以是房间，“屋子”正合适。", "作业": "搭配：“打扫”不与“作业”搭配，作业应说“完成”或“做”。", "空气": "语义：空气不能被“打扫”，应说“净化”或“清新”。", "考试": "语义：考试是一种活动，不能被“打扫”。"}, "sentence_index": 6, "correct_answer": "屋子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校的屋子能坐下一千多名学生，很热闹。", "explanation": "这里应该用〈礼堂〉。屋子是小房间，装不下一千多人。"}, {"text": "他走进一张屋子，关上了门。", "explanation": "量词错误：〈张〉用于平面的东西，屋子应该用〈间〉。"}, {"text": "我们一家人坐着屋子去旅行。", "explanation": "这里应该用〈车〉。屋子是住人的房间，不能坐着去旅行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校在附近租了一只屋子给学生住。", "corrected_sentence": "学校在附近租了一间屋子给学生住。", "error_description": "量词错误：“屋子”应该用量词“间”，不能用“只”（“只”用于动物）。应改为“一间屋子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚走进一条屋子，就把门关上了。", "corrected_sentence": "他刚走进一间屋子，就把门关上了。", "error_description": "量词错误：“屋子”应该用量词“间”，不能用“条”（“条”用于细长的东西）。应改为“一间屋子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
