INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房间；房屋。", "primary_collocate": null, "pronunciation": "wū zi", "ipa": "u˥˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "这间屋子很大，也很亮。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的屋子在山脚下。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子里有一张床和一个桌子。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起把屋子打扫干净了。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人住在一间小屋子里。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子外面下着大雨。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所老屋子已经很旧了。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在河边盖了一间屋子。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子的门开着，里面没有人。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里有三间屋子。", "target_word": "屋子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}], "register": "口语", "sense_fingerprint": "房间或小房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋子", "is_correct": true, "explanation": "“间”是房间的量词，“屋子”指房间，可以很大、很亮。"}, {"text": "窗户", "is_correct": false, "explanation": "量词：“间”不用于窗户，窗户应说“扇”。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：量词“间”不用于椅子，椅子应说“把”。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：书桌的量词是“张”，不能说“这间书桌”。"}], "explanations": {"屋子": "“间”是房间的量词，“屋子”指房间，可以很大、很亮。", "窗户": "量词：“间”不用于窗户，窗户应说“扇”。", "椅子": "搭配：量词“间”不用于椅子，椅子应说“把”。", "书桌": "搭配：书桌的量词是“张”，不能说“这间书桌”。"}, "sentence_index": 0, "correct_answer": "屋子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家买了一台屋子。", "explanation": "量词错误：〈台〉用于机器，屋子应该用〈间〉。"}, {"text": "我家门口有一条屋子。", "explanation": "量词错误：〈条〉用于细长的东西，屋子应该用〈间〉。"}, {"text": "我们班一共有四把屋子。", "explanation": "量词错误：〈把〉用于有柄的器具，屋子应该用〈间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屋子", "is_correct": true, "explanation": "“所”可以修饰房屋，“老屋子”指旧房子，句中的“已经很旧了”正合适。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：量词“所”不用于地图，地图应说“张”。"}, {"text": "船", "is_correct": false, "explanation": "搭配：船用量词“艘”或“条”，不用“所”。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“旧”不能用来形容人，“已经很旧了”说的是房屋。"}], "explanations": {"屋子": "“所”可以修饰房屋，“老屋子”指旧房子，句中的“已经很旧了”正合适。", "地图": "搭配：量词“所”不用于地图，地图应说“张”。", "船": "搭配：船用量词“艘”或“条”，不用“所”。", "学生": "语义：“旧”不能用来形容人，“已经很旧了”说的是房屋。"}, "sentence_index": 6, "correct_answer": "屋子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校新建的屋子能同时坐下一千多名学生。", "explanation": "这里应该用〈礼堂〉。屋子是小房间，坐不下一千多人，大场所要用礼堂。"}, {"text": "我们在路上遇到了一辆屋子。", "explanation": "量词错误：〈辆〉用于车辆，屋子应该用〈间〉。"}, {"text": "院子里种了一棵屋子。", "explanation": "量词错误：〈棵〉用于植物，屋子应该用〈间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有三只屋子。", "corrected_sentence": "我家有三间屋子。", "error_description": "量词错误：“屋子”应该用量词“间”，不能用“只”（“只”用于动物）。应改为“三间屋子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚走进一只屋子，就听见有人说话。", "corrected_sentence": "他刚走进一间屋子，就听见有人说话。", "error_description": "量词错误：“屋子”应该用量词“间”，不能用“只”（“只”用于动物）。应改为“一间屋子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
