INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88593, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "药是生病的时候吃的东西，吃了病就会好。", "primary_collocate": null, "pronunciation": "yào", "ipa": "jau˥˩", "syllable_count": 1, "sentences": [{"text": "我头疼，吃了一片药。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个药很苦，孩子不想吃。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给我开了三种药。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药要在饭后吃。", "target_word": "药", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈把药放在桌子上。", "target_word": "药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你发烧了，快吃药吧。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天早上吃一次药。", "target_word": "药", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这药吃了两天，我就好多了。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药太苦了，我要喝点水。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶忘了吃药，爷爷提醒她。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "中药", "label": "复合"}, {"form": "西药", "label": "复合"}, {"form": "藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生病时吃的、吃了病会好的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adf9579b-4126-4d8c-b7a3-be431450724f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "药", "is_correct": true, "explanation": "药（yào）是生病时吃的东西，是正确答案。"}, {"text": "腰", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是腰。"}, {"text": "摇", "is_correct": false, "explanation": "yáo（第二声）与 yào（第四声）声调不同，意思是摇动。"}, {"text": "咬", "is_correct": false, "explanation": "yǎo（第三声）与 yào（第四声）声调不同，意思是咬。"}], "explanations": {"药": "药（yào）是生病时吃的东西，是正确答案。", "腰": "yāo（第一声）与 yào（第四声）声调不同，意思是腰。", "摇": "yáo（第二声）与 yào（第四声）声调不同，意思是摇动。", "咬": "yǎo（第三声）与 yào（第四声）声调不同，意思是咬。"}, "sentence_index": null, "correct_answer": "药"}, "level_3": {"options": [{"text": "药", "is_correct": true, "explanation": "正确：生病时吃的东西，量词“片”也搭配“药”。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：“吃”的对象应是可以食用的东西，且量词“片”不用于镜子（应说“面”）。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能吃，也治不了头疼。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，也不能治头疼。"}], "explanations": {"药": "正确：生病时吃的东西，量词“片”也搭配“药”。", "镜子": "搭配：“吃”的对象应是可以食用的东西，且量词“片”不用于镜子（应说“面”）。", "手机": "语义：手机不能吃，也治不了头疼。", "石头": "语义：石头不能吃，也不能治头疼。"}, "sentence_index": 0, "correct_answer": "药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去药买了一瓶水，顺便看看新上市的饮料。", "explanation": "这里应该用〈超市〉。药是治病用的东西，不是买东西的地方。"}, {"text": "妈妈穿着药去公园散步。", "explanation": "这里应该用〈衣服〉。药是治病用的，不能穿在身上。"}, {"text": "老师在黑板上写了药，同学们都在认真抄。", "explanation": "这里应该用〈字〉。黑板上写的是字，药是治病用的，不能用来写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88593, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "药", "is_correct": true, "explanation": "药（yào）是生病时吃的东西，是正确答案。"}, {"text": "邀", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是邀请。"}, {"text": "遥", "is_correct": false, "explanation": "yáo（第二声）与 yào（第四声）声调不同，意思是遥远。"}, {"text": "舀", "is_correct": false, "explanation": "yǎo（第三声）与 yào（第四声）声调不同，意思是用勺子取。"}], "explanations": {"药": "药（yào）是生病时吃的东西，是正确答案。", "邀": "yāo（第一声）与 yào（第四声）声调不同，意思是邀请。", "遥": "yáo（第二声）与 yào（第四声）声调不同，意思是遥远。", "舀": "yǎo（第三声）与 yào（第四声）声调不同，意思是用勺子取。"}, "sentence_index": null, "correct_answer": "药"}, "level_3": {"options": [{"text": "药", "is_correct": true, "explanation": "正确：每天早上吃的是药，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能吃。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“吃”一般用于固体食物，咖啡应说“喝”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能吃。"}], "explanations": {"药": "正确：每天早上吃的是药，符合句意。", "空气": "语义：空气不能吃。", "咖啡": "搭配：“吃”一般用于固体食物，咖啡应说“喝”。", "窗户": "语义：窗户不能吃。"}, "sentence_index": 6, "correct_answer": "药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟考了满分，妈妈奖励他一颗药。", "explanation": "这里应该用〈糖果〉。药是治病用的，不能当作奖励的零食。"}, {"text": "我放学后在操场上踢药。", "explanation": "这里应该用〈足球〉。足球可以踢，药是治病用的，不能踢。"}, {"text": "我夏天最爱吃药，比冰激凌还好吃。", "explanation": "这里应该用〈冰激凌〉。冰激凌是可以吃的甜食，药是治病用的，不能当甜食吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只药，头疼时吃一片。", "corrected_sentence": "我买了一瓶药，头疼时吃一片。", "error_description": "量词错误：药应用“瓶”“盒”等，不用“只”（“只”多用于动物）。应改为“我买了一瓶药，头疼时吃一片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天晚上吃一台药，然后就睡觉了。", "corrected_sentence": "他每天晚上吃一粒药，然后就睡觉了。", "error_description": "量词错误：药不用“台”（“台”用于机器、设备）。应改为“他每天晚上吃一粒药，然后就睡觉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
