INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来治疗疾病、预防疾病的物质。", "primary_collocate": null, "pronunciation": "yào", "ipa": "jau˥˩", "syllable_count": 1, "sentences": [{"text": "这种药可以治疗感冒。", "target_word": "药", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家正在研究一种新的药。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药能预防很多疾病。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药作用很强，不能乱用。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里有很多种药。", "target_word": "药", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种药是用草做成的。", "target_word": "药", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说这种药对心脏病有用。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们生产的药卖到了很多国家。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药对身体有一点伤害。", "target_word": "药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买药时要看清楚说明。", "target_word": "药", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "中药", "label": "复合"}, {"form": "西药", "label": "复合"}, {"form": "藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来治疗或预防疾病的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adf9579b-4126-4d8c-b7a3-be431450724f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "药", "is_correct": true, "explanation": "药（yào）是用来治疗或预防疾病的物质，是正确答案。"}, {"text": "腰", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是腰。"}, {"text": "遥", "is_correct": false, "explanation": "yáo（第二声）与 yào（第四声）声调不同，意思是遥远。"}, {"text": "咬", "is_correct": false, "explanation": "yǎo（第三声）与 yào（第四声）声调不同，意思是咬。"}], "explanations": {"药": "药（yào）是用来治疗或预防疾病的物质，是正确答案。", "腰": "yāo（第一声）与 yào（第四声）声调不同，意思是腰。", "遥": "yáo（第二声）与 yào（第四声）声调不同，意思是遥远。", "咬": "yǎo（第三声）与 yào（第四声）声调不同，意思是咬。"}, "sentence_index": null, "correct_answer": "药"}, "level_3": {"options": [{"text": "药", "is_correct": true, "explanation": "正确：用来治疗感冒的物质，只有“药”符合。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏不能治疗感冒。"}, {"text": "糖果", "is_correct": false, "explanation": "语义：糖果不能治疗感冒。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不能治疗感冒。"}], "explanations": {"药": "正确：用来治疗感冒的物质，只有“药”符合。", "游戏": "语义：游戏不能治疗感冒。", "糖果": "语义：糖果不能治疗感冒。", "手套": "语义：手套不能治疗感冒。"}, "sentence_index": 0, "correct_answer": "药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子下周要去接种药。", "explanation": "这里应该用〈疫苗〉。“接种”的对象是疫苗，不说“接种药”。"}, {"text": "画家用这种药画了一幅画。", "explanation": "这里应该用〈颜料〉。药是用来治病的，不能拿来画画。"}, {"text": "妈妈用这种药洗衣服，很干净。", "explanation": "这里应该用〈洗衣粉〉。药是用来治病的，不能用来洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "药", "is_correct": true, "explanation": "药（yào）是用来治疗或预防疾病的物质，是正确答案。"}, {"text": "邀", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是邀请。"}, {"text": "摇", "is_correct": false, "explanation": "yáo（第二声）与 yào（第四声）声调不同，意思是摇动。"}, {"text": "舀", "is_correct": false, "explanation": "yǎo（第三声）与 yào（第四声）声调不同，意思是用勺子取。"}], "explanations": {"药": "药（yào）是用来治疗或预防疾病的物质，是正确答案。", "邀": "yāo（第一声）与 yào（第四声）声调不同，意思是邀请。", "摇": "yáo（第二声）与 yào（第四声）声调不同，意思是摇动。", "舀": "yǎo（第三声）与 yào（第四声）声调不同，意思是用勺子取。"}, "sentence_index": null, "correct_answer": "药"}, "level_3": {"options": [{"text": "药", "is_correct": true, "explanation": "正确：能对心脏病起作用的是药，只有“药”符合。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料不能治疗心脏病。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "搭配：“对……有用”指对疾病有作用，“洗衣粉”不搭配这种说法。"}, {"text": "文具", "is_correct": false, "explanation": "语义：文具不能治疗心脏病。"}], "explanations": {"药": "正确：能对心脏病起作用的是药，只有“药”符合。", "颜料": "语义：颜料不能治疗心脏病。", "洗衣粉": "搭配：“对……有用”指对疾病有作用，“洗衣粉”不搭配这种说法。", "文具": "语义：文具不能治疗心脏病。"}, "sentence_index": 6, "correct_answer": "药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子最喜欢这种药，每天都要玩一会儿。", "explanation": "这里应该用〈玩具〉。玩具可以玩，药是治病用的，不能拿来玩。"}, {"text": "弟弟每天都在家里听药。", "explanation": "这里应该用〈音乐〉。音乐可以听，药是治病用的，不能听。"}, {"text": "我每天晚上都唱药。", "explanation": "这里应该用〈歌〉。歌可以唱，药是治病用的，不能唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只药对孩子很安全，可以放心吃。", "corrected_sentence": "这种药对孩子很安全，可以放心吃。", "error_description": "量词错误：“药”指物质，不用“只”（“只”多用于动物）。应改为“这种药对孩子很安全，可以放心吃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说这种药对心脏病有用，你要一次吃一台药。", "corrected_sentence": "医生说这种药对心脏病有用，你要一次吃一片药。", "error_description": "量词错误：药应用“片”“粒”等，不用“台”（“台”用于机器、设备）。应改为“你要一次吃一片药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
