INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88595, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "进度是事情做到了哪一步。", "primary_collocate": null, "pronunciation": "jìn dù", "ipa": "tɕin˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "请告诉我工作进度。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的作业进度怎么样了？", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的进度已经到第三层了。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想看看大家的论文进度。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把今天的进度写在本子上。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的进度已经到了最后一步。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理每周都会检查项目进度。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路的进度已经到一半了。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把最新的进度发给我。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的进度是完成了三个部分。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进度表", "label": "复合"}, {"form": "进度条", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情已经做到的阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88595, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进度", "is_correct": true, "explanation": "正确答案。进度指事情做到的步骤或程度。"}, {"text": "进步", "is_correct": false, "explanation": "bù 与 dù 声母不同（b / d），意思是进步。"}, {"text": "进入", "is_correct": false, "explanation": "rù 与 dù 声母不同（r / d），意思是进入。"}, {"text": "印度", "is_correct": false, "explanation": "yìn 与 jìn 声母不同（y / j），意思是印度（国家名）。"}, {"text": "信度", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x / j），意思是信度，指测量结果的可靠程度。"}], "explanations": {"进度": "正确答案。进度指事情做到的步骤或程度。", "进步": "bù 与 dù 声母不同（b / d），意思是进步。", "进入": "rù 与 dù 声母不同（r / d），意思是进入。", "印度": "yìn 与 jìn 声母不同（y / j），意思是印度（国家名）。", "信度": "xìn 与 jìn 声母不同（x / j），意思是信度，指测量结果的可靠程度。"}, "sentence_index": null, "correct_answer": "进度"}, "level_3": {"options": [{"text": "进度", "is_correct": true, "explanation": "正确答案。“工作进度”指工作做到的步骤或程度，正符合“请告诉我”的内容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与工作的情况无关，“请告诉我工作颜色”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描写人的体态，不是工作的情况，不能用来回答“请告诉我”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”指东西，“工作玩意儿”说不通，不能用来回答“请告诉我”。"}], "explanations": {"进度": "正确答案。“工作进度”指工作做到的步骤或程度，正符合“请告诉我”的内容。", "颜色": "语义：“颜色”与工作的情况无关，“请告诉我工作颜色”说不通。", "身高": "体貌：“身高”描写人的体态，不是工作的情况，不能用来回答“请告诉我”。", "玩意儿": "语义：“玩意儿”指东西，“工作玩意儿”说不通，不能用来回答“请告诉我”。"}, "sentence_index": 0, "correct_answer": "进度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的进度每小时一百公里。", "explanation": "这里应该用〈速度〉。进度指事情做到的程度，不指快慢的速率，所以不能说每小时多少公里。"}, {"text": "他的身高这一年有很大的进度。", "explanation": "这里应该用〈增长〉。进度指事情做到哪一步，身高的增加要说〈增长〉或〈长高〉。"}, {"text": "今天的进度是三十度。", "explanation": "这里应该用〈温度〉。进度指事情做到的程度，不指冷热的程度，说天气冷热要用〈温度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进度", "is_correct": true, "explanation": "正确答案。“检查项目进度”指查看项目做到哪一步，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“检查”一般不说“检查项目味道”，“项目味道”也不通。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“检查”不带“感情”作宾语，“项目感情”不成立。"}, {"text": "性格", "is_correct": false, "explanation": "配价：“检查”的对象需是可核查的工作或事物，“性格”不能作为“项目”的检查对象。"}], "explanations": {"进度": "正确答案。“检查项目进度”指查看项目做到哪一步，符合句意。", "味道": "搭配：“检查”一般不说“检查项目味道”，“项目味道”也不通。", "感情": "搭配：“检查”不带“感情”作宾语，“项目感情”不成立。", "性格": "配价：“检查”的对象需是可核查的工作或事物，“性格”不能作为“项目”的检查对象。"}, "sentence_index": 6, "correct_answer": "进度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语进度很聪明。", "explanation": "这里应该用〈水平〉。进度指事情做到哪一步，不能用来形容人的聪明；说汉语能力要用〈水平〉。"}, {"text": "这家店的进度很多。", "explanation": "这里应该用〈数量〉。进度不能计数，说“多”要用于数量或人数。"}, {"text": "他的进度很强。", "explanation": "这里应该用〈能力〉。进度不能用来形容人的能力强弱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月项目的进度推进地很顺利。", "corrected_sentence": "这个月项目的进度推进得很顺利。", "error_description": "补语标记错误：“推进得很顺利”中的“得”引出补语，不能用“地”。“地”用于动词前作状语，此处应说“推进得很顺利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
