INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作或学习进行的快慢程度。", "primary_collocate": null, "pronunciation": "jìn dù", "ipa": "tɕin˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "他学习的进度很快。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，修路的进度慢了。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要加快工作进度。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的进度比别的班慢。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师按照学生的进度上课。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学习进度跟不上大家。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进度太快，我有点听不懂。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家要保持一样的进度。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好，工作进度就快一些。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课的进度不太快，很适合新手。", "target_word": "进度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进度表", "label": "复合"}, {"form": "进度条", "label": "复合"}], "register": "中性", "sense_fingerprint": "工作或学习推进的快慢程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88596, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进度", "is_correct": true, "explanation": "正确答案。进度指工作或学习推进的快慢程度。"}, {"text": "进步", "is_correct": false, "explanation": "bù 与 dù 声母不同（b / d），意思是进步。"}, {"text": "进入", "is_correct": false, "explanation": "rù 与 dù 声母不同（r / d），意思是进入。"}, {"text": "印度", "is_correct": false, "explanation": "yìn 与 jìn 声母不同（y / j），意思是印度（国家名）。"}, {"text": "信度", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x / j），意思是信度，指测量结果的可靠程度。"}], "explanations": {"进度": "正确答案。进度指工作或学习推进的快慢程度。", "进步": "bù 与 dù 声母不同（b / d），意思是进步。", "进入": "rù 与 dù 声母不同（r / d），意思是进入。", "印度": "yìn 与 jìn 声母不同（y / j），意思是印度（国家名）。", "信度": "xìn 与 jìn 声母不同（x / j），意思是信度，指测量结果的可靠程度。"}, "sentence_index": null, "correct_answer": "进度"}, "level_3": {"options": [{"text": "进度", "is_correct": true, "explanation": "正确答案。“学习进度”指学习推进的快慢，与“很快”搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能学习，“他学习的颜色很快”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描写人的身材，不是学习的状况。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”指东西，“学习的玩意儿”说不通，句意不成立。"}], "explanations": {"进度": "正确答案。“学习进度”指学习推进的快慢，与“很快”搭配。", "颜色": "语义：“颜色”不能学习，“他学习的颜色很快”不成立。", "身高": "体貌：“身高”描写人的身材，不是学习的状况。", "玩意儿": "语义：“玩意儿”指东西，“学习的玩意儿”说不通，句意不成立。"}, "sentence_index": 0, "correct_answer": "进度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的汉语进度比别人高。", "explanation": "这里应该用〈水平〉。进度只说事情推进的快慢或程度，不用来比较人的水平高低。"}, {"text": "这个学校的进度比别的学校贵。", "explanation": "这里应该用〈学费〉。进度指学习推进的快慢，不能说贵贱；说学费高低要用〈学费〉。"}, {"text": "他的进度比我重。", "explanation": "这里应该用〈体重〉。进度指工作或学习进行的快慢，不用来比较人的轻重，说体重要用〈体重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进度", "is_correct": true, "explanation": "正确答案。“进度太快”指推进的速度太快，符合“我有点听不懂”的语境。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“太快”一般说速度或节奏，不说“味道太快”。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“太快”不修饰“力气”，“力气太快”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "配价：“太快”描述变化的速度，“体重”是静态数值，不能说“体重太快”。"}], "explanations": {"进度": "正确答案。“进度太快”指推进的速度太快，符合“我有点听不懂”的语境。", "味道": "搭配：“太快”一般说速度或节奏，不说“味道太快”。", "力气": "搭配：“太快”不修饰“力气”，“力气太快”不成立。", "体重": "配价：“太快”描述变化的速度，“体重”是静态数值，不能说“体重太快”。"}, "sentence_index": 6, "correct_answer": "进度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的进度比别的贵。", "explanation": "这里应该用〈价格〉。进度不能用来说贵贱，价格高低要用〈价格〉。"}, {"text": "这条路的进度比那条长。", "explanation": "这里应该用〈长度〉。进度是事情推进的程度，不能说长短，要用〈长度〉。"}, {"text": "这台机器的进度比那台重。", "explanation": "这里应该用〈重量〉。进度指工作或学习推进的快慢，不能用来比较轻重，说重量要用〈重量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们的进度跟计划快。", "corrected_sentence": "他们的进度比计划快。", "error_description": "比较结构错误：比较对象要用“比”引出，“跟”不能直接引出比较对象。应说“进度比计划快”，不能说“进度跟计划快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
