INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88597, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "崭新是特别新，一点也没有旧。", "primary_collocate": null, "pronunciation": "zhǎn xīn", "ipa": "ʈʂan˨˩ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "他穿着一件崭新的白衬衫。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋是崭新的，我今天才买。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子里的家具都是崭新的。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子背着崭新的书包去上学。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车看起来是崭新的。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一本崭新的书。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一部崭新的手机。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把崭新的衣服放进了箱子。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裙子还带着标签，是崭新的。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换上了崭新的校服。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嶄新", "label": "繁体"}], "register": "中性", "sense_fingerprint": "特别新、完全没有旧的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崭新", "is_correct": true, "explanation": "崭新：形容衬衫完全是新的，符合句意。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容情绪，不能修饰衬衫。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容人或建筑的体积，不能修饰衬衫。"}, {"text": "年迈", "is_correct": false, "explanation": "搭配：“年迈”只用于人，不能修饰衣物。"}], "explanations": {"崭新": "崭新：形容衬衫完全是新的，符合句意。", "悲伤": "语义：“悲伤”形容情绪，不能修饰衬衫。", "高大": "语义：“高大”形容人或建筑的体积，不能修饰衬衫。", "年迈": "搭配：“年迈”只用于人，不能修饰衣物。"}, "sentence_index": 0, "correct_answer": "崭新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些鱼刚捞上来，很崭新。", "explanation": "这里应该用〈新鲜〉。新鲜可形容食物刚采摘或捕捞不久，崭新只指物品从未用过，不能用来形容鱼。"}, {"text": "雨后的空气格外崭新。", "explanation": "这里应该用〈清新〉。清新形容空气清爽，崭新指物品从未用过，不能形容空气。"}, {"text": "院子里有一只崭新的小猫。", "explanation": "这里应该用〈新生〉。新生指刚出生的生命，崭新只能形容未用过的物品，不能形容小猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崭新", "is_correct": true, "explanation": "崭新：形容手机是全新的，符合句意。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”形容人的品质，不能修饰手机。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿”形容人或动物的感受，不能修饰手机。"}, {"text": "辛勤", "is_correct": false, "explanation": "搭配：“辛勤”多用于人的劳动，不能修饰手机。"}], "explanations": {"崭新": "崭新：形容手机是全新的，符合句意。", "勇敢": "语义：“勇敢”形容人的品质，不能修饰手机。", "饥饿": "语义：“饥饿”形容人或动物的感受，不能修饰手机。", "辛勤": "搭配：“辛勤”多用于人的劳动，不能修饰手机。"}, "sentence_index": 6, "correct_answer": "崭新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对崭新的夫妇很幸福。", "explanation": "这里应该用〈新婚〉。新婚指刚结婚，崭新只形容未用过的物品，不能形容人。"}, {"text": "他是崭新的老师，大家都很欢迎他。", "explanation": "这里应该用〈新〉。新来的表示刚到任，崭新强调没有使用过，不能用来说人的身份。"}, {"text": "这朵花的花瓣很崭新。", "explanation": "这里应该用〈鲜艳〉。鲜艳形容颜色明亮，崭新指没有使用过，不能形容花瓣的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天穿着一件崭新地白衬衫。", "corrected_sentence": "他今天穿着一件崭新的白衬衫。", "error_description": "“崭新”作定语修饰名词“白衬衫”，应该用“的”，不能用“地”，应为“崭新的白衬衫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她穿上了崭新了的外套。", "corrected_sentence": "她穿上了崭新的外套。", "error_description": "“崭新了的外套”多了“了”。作定语修饰名词时，“崭新”后直接接“的”，不能带“了”，应为“崭新的外套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
