INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88598, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常新；全新的。", "primary_collocate": null, "pronunciation": "zhǎn xīn", "ipa": "ʈʂan˨˩ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "他开始了崭新的生活。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走进了崭新的教室。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有崭新的面貌。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，大家都穿上崭新的衣服。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送给我一支崭新的钢笔。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚修好的马路是崭新的。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司买来了一批崭新的电脑。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个崭新的开始。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着崭新的自行车回家。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一条崭新的围巾。", "target_word": "崭新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嶄新", "label": "繁体"}], "register": "中性", "sense_fingerprint": "非常新、全新的事物或局面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崭新", "is_correct": true, "explanation": "崭新：形容全新的生活，符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能修饰生活。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容外形，不能修饰生活。"}, {"text": "健壮", "is_correct": false, "explanation": "搭配：“健壮”多用于人的体格，与“生活”搭配不当。"}], "explanations": {"崭新": "崭新：形容全新的生活，符合句意。", "清脆": "语义：“清脆”形容声音，不能修饰生活。", "高大": "语义：“高大”形容外形，不能修饰生活。", "健壮": "搭配：“健壮”多用于人的体格，与“生活”搭配不当。"}, "sentence_index": 0, "correct_answer": "崭新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的空气很崭新。", "explanation": "这里应该用〈新鲜〉。新鲜形容空气清新、没有污染，崭新不能用来形容空气。"}, {"text": "夏日的微风格外崭新。", "explanation": "这里应该用〈清新〉。清新形容微风清爽，崭新不能形容微风。"}, {"text": "这对崭新的小两口很幸福。", "explanation": "这里应该用〈新婚〉。新婚指刚结婚，崭新只形容未用过的事物，不能形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崭新", "is_correct": true, "explanation": "崭新：形容电脑是全新的，符合句意。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容情绪，不能修饰电脑。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿”形容人或动物的感受，不能修饰电脑。"}, {"text": "辛勤", "is_correct": false, "explanation": "搭配：“辛勤”多用于人的劳动，不能修饰电脑。"}], "explanations": {"崭新": "崭新：形容电脑是全新的，符合句意。", "悲伤": "语义：“悲伤”形容情绪，不能修饰电脑。", "饥饿": "语义：“饥饿”形容人或动物的感受，不能修饰电脑。", "辛勤": "搭配：“辛勤”多用于人的劳动，不能修饰电脑。"}, "sentence_index": 6, "correct_answer": "崭新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里出生了一个崭新的男孩。", "explanation": "这里应该用〈新生〉。新生指刚出生的婴儿，崭新只能形容未用过的物品，不能形容男孩。"}, {"text": "这片枫叶很崭新。", "explanation": "这里应该用〈鲜艳〉。鲜艳形容颜色明亮，崭新强调没有使用过，不能形容枫叶的颜色。"}, {"text": "她是崭新的护士，大家都很照顾她。", "explanation": "这里应该用〈新〉。新来的表示刚到岗位，崭新只形容未用过的事物，不能用来形容人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在城市里过上了崭新地生活。", "corrected_sentence": "他们在城市里过上了崭新的生活。", "error_description": "“崭新”作定语修饰名词“生活”，应该用“的”，不能用“地”，应为“崭新的生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们搬进了崭新了的房子。", "corrected_sentence": "我们搬进了崭新的房子。", "error_description": "“崭新了的房子”多了“了”。作定语时，“崭新”后直接接“的”，不能带“了”，应为“崭新的房子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
