INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88599, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88599, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过年是大家一起庆祝新的一年的开始。", "primary_collocate": null, "pronunciation": "guò nián", "ipa": "kwo˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "过年的时候，大家都回家了。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家人一起过年，非常热闹。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今年在奶奶家过年。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，孩子们穿上新衣服。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起过年，高高兴兴地迎接新的一年。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家过年要包饺子。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年那天，街上到处是红灯笼。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我最喜欢过年。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们打电话说，要一起过年。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我想和家人过年，不去旅游了。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过了年", "label": "体标"}, {"form": "过完年", "label": "结果补语"}, {"form": "過年", "label": "繁体"}], "register": "口语", "sense_fingerprint": "大家一起庆祝新一年开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88599, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：考试时大家都在学校或考场，不会都回家。"}, {"text": "过年", "is_correct": true, "explanation": "过年：春节前后全家团聚，与“大家都回家了”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉的时候”指休息的时间，与“大家都回家了”的情境不符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课的时候”指在学校学习的时段，大家不会在那时都回家，与句意不符。"}], "explanations": {"考试": "语义：考试时大家都在学校或考场，不会都回家。", "过年": "过年：春节前后全家团聚，与“大家都回家了”相符。", "睡觉": "语义：“睡觉的时候”指休息的时间，与“大家都回家了”的情境不符。", "上课": "语义：“上课的时候”指在学校学习的时段，大家不会在那时都回家，与句意不符。"}, "sentence_index": 0, "correct_answer": "过年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们中秋节在公园过年，吃了很多月饼。", "explanation": "这里应该用〈过节〉。过年专指春节前后庆祝新年，中秋节等其他节日要用“过节”。"}, {"text": "我妹妹明天过年，我们一起吃蛋糕。", "explanation": "这里应该用〈过生日〉。过年只指春节，庆祝个人生日要用“过生日”。"}, {"text": "这个周末我们去海边过年，春节还没到呢。", "explanation": "这里应该用〈度假〉。过年专指春节前后的庆祝，春节还没到时不能说“过年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开学", "is_correct": false, "explanation": "语义：开学是学校的日子，与街上挂满红灯笼的节日场景不符。"}, {"text": "过年", "is_correct": true, "explanation": "过年：指春节，与“那天街上到处是红灯笼”的节日氛围相符。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班是平常的工作日，不会出现满街红灯笼的节日氛围。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与街上挂满红灯笼的节日场景没有关系。"}], "explanations": {"开学": "语义：开学是学校的日子，与街上挂满红灯笼的节日场景不符。", "过年": "过年：指春节，与“那天街上到处是红灯笼”的节日氛围相符。", "上班": "语义：上班是平常的工作日，不会出现满街红灯笼的节日氛围。", "游泳": "语义：游泳与街上挂满红灯笼的节日场景没有关系。"}, "sentence_index": 6, "correct_answer": "过年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛我们团队拿了金牌，大家一起过年。", "explanation": "这里应该用〈庆祝〉。过年专指春节或新年的庆祝，比赛获胜要说“庆祝”。"}, {"text": "我们给爷爷过年，祝他身体健康。", "explanation": "这里应该用〈庆生〉。过年指春节，给长辈庆祝生日要用“庆生”。"}, {"text": "今天是星期三，我们在办公室过年，一直工作到晚上。", "explanation": "这里应该用〈上班〉。过年专指春节或新年的庆祝，平常的工作日要说“上班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年我们过年得很开心。", "corrected_sentence": "去年我们过年过得很开心。", "error_description": "错误：“过年得很开心”；正确：“过年过得很开心”。动宾式“过年”后接“得”补语时，要重复动词“过”，不能直接说“过年得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春节那天我们在家过年过。", "corrected_sentence": "春节那天我们在家过年。", "error_description": "多了“过”。“在家过年”已经完整，动词“过年”后面不能再加“过”，应去掉句末的“过”，说“春节那天我们在家过年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
