INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "度过新年；庆祝春节。", "primary_collocate": null, "pronunciation": "guò nián", "ipa": "kwo˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "你今年打算在哪儿过年？", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在国外过年，想家想得很厉害。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了过年，妈妈买了很多好吃的。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作太忙，没有回家过年。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在南方过年，天气不太冷。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次在中国过年，什么都新鲜。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们那儿过年放鞭炮吗？", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家人在海边过年。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不回家的人，只能在外面过年。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前，大家都要把家里打扫干净。", "target_word": "过年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过了年", "label": "体标"}, {"form": "过完年", "label": "结果补语"}, {"form": "過年", "label": "繁体"}], "register": "口语", "sense_fingerprint": "度过新年、庆祝春节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：“打算在哪儿出生”不合常理，出生不能由自己计划。"}, {"text": "过年", "is_correct": true, "explanation": "过年：指度过新年，与“你今年打算在哪儿”的问话相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“打算在哪儿哭”不合逻辑，与问话的计划语境冲突。"}, {"text": "就寝", "is_correct": false, "explanation": "语域：“就寝”是书面语，与口语问句“你今年打算在哪儿……”不协调。"}], "explanations": {"出生": "语义：“打算在哪儿出生”不合常理，出生不能由自己计划。", "过年": "过年：指度过新年，与“你今年打算在哪儿”的问话相符。", "哭": "语义：“打算在哪儿哭”不合逻辑，与问话的计划语境冲突。", "就寝": "语域：“就寝”是书面语，与口语问句“你今年打算在哪儿……”不协调。"}, "sentence_index": 0, "correct_answer": "过年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年国庆我们在家过年，玩得很开心。", "explanation": "这里应该用〈过节〉。过年专指春节，国庆等其他节日要用“过节”。"}, {"text": "明天是我的生日，我们要一起过年。", "explanation": "这里应该用〈过生日〉。过年指春节，个人生日要说“过生日”。"}, {"text": "周末我们在家过年，什么也不做。", "explanation": "这里应该用〈休息〉。过年指春节，普通周末不能说“过年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上课", "is_correct": false, "explanation": "语义：在学校上课时不会放鞭炮，与问句的节日情境不符。"}, {"text": "过年", "is_correct": true, "explanation": "过年：春节放鞭炮是常见习俗，与“你们那儿……放鞭炮吗”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时放鞭炮不合常理，与句意不符。"}, {"text": "就寝", "is_correct": false, "explanation": "语域：“就寝”是书面语，与口语问句不协调，而且也不符合放鞭炮的情境。"}], "explanations": {"上课": "语义：在学校上课时不会放鞭炮，与问句的节日情境不符。", "过年": "过年：春节放鞭炮是常见习俗，与“你们那儿……放鞭炮吗”相符。", "睡觉": "语义：睡觉时放鞭炮不合常理，与句意不符。", "就寝": "语域：“就寝”是书面语，与口语问句不协调，而且也不符合放鞭炮的情境。"}, "sentence_index": 6, "correct_answer": "过年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天下班后都在健身房过年，累得不行。", "explanation": "这里应该用〈锻炼〉。过年专指春节或新年的庆祝，日常锻炼要说“锻炼”。"}, {"text": "我们给外婆过年，祝她长寿。", "explanation": "这里应该用〈庆生〉。过年指春节，给长辈庆祝生日要用“庆生”。"}, {"text": "婚礼那天，我们在饭店过年，热闹极了。", "explanation": "这里应该用〈庆祝〉。过年专指春节或新年的庆祝，婚礼要说“庆祝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今年想在奶奶家过了年。", "corrected_sentence": "我们今年想在奶奶家过年。", "error_description": "多了“了”：“想”表示打算，后面要接未发生的动作，不能用完成体“过了年”，应说“想在奶奶家过年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个寒假我们在家过年着。", "corrected_sentence": "这个寒假我们在家过年。", "error_description": "错误：句末的“着”位置不当。“过年”是离合词，持续态要插在中间，写作“过着年”；但这里句意是普通陈述，不需要持续态，应去掉“着”，说“这个寒假我们在家过年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
