INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88603, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工作面是工人干活的那个地方。", "primary_collocate": null, "pronunciation": "gōng zuò miàn", "ipa": "kʊŋ˥ tswo˥˩ mjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "工人们都在工作面上干活。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作面太小，放不下机器。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上先去工作面看一看。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作面上很热，大家都出了汗。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作面的地上有很多水。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅带我们走进了新的工作面。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，工作面不太安全。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作面上不能玩手机，请大家注意。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作面有二十个工人。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把工具搬到了工作面。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "采煤工作面", "label": "复合"}], "register": "中性", "sense_fingerprint": "工人干活的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88603, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作面", "is_correct": true, "explanation": "正确答案。“工作面”是工人干活的地方，可以说“在工作面上干活”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是用来学习的书，不是工人干活的地方。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“在……上”表示平面上的场所，“教室”是房间，应说“在教室里”，不能说“在教室上”。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文是写的文章，不是可以“干活”的场所。"}], "explanations": {"工作面": "正确答案。“工作面”是工人干活的地方，可以说“在工作面上干活”。", "课本": "语义：课本是用来学习的书，不是工人干活的地方。", "教室": "搭配：“在……上”表示平面上的场所，“教室”是房间，应说“在教室里”，不能说“在教室上”。", "作文": "语义：作文是写的文章，不是可以“干活”的场所。"}, "sentence_index": 0, "correct_answer": "工作面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在工作面上读书。", "explanation": "这里应该用〈教室〉。“工作面”指工人干活的地方，孩子们读书不能说“工作面”。"}, {"text": "我们在工作面上开了一场音乐会。", "explanation": "这里应该用〈礼堂〉。“工作面”指工人作业的地方，不是开音乐会的场所。"}, {"text": "作家每天在工作面里写小说。", "explanation": "这里应该用〈工作室〉。“工作室”是作家、画家等人写作、创作的地方；“工作面”指工人干活的地方，不能用来指写作的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作面", "is_correct": true, "explanation": "正确答案。下雨后工作面地面湿滑，不太安全。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是可以“安全”与否的对象，句意说不通。"}, {"text": "标点", "is_correct": false, "explanation": "语义：标点是符号，不存在安全与否的问题。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“安全”用于地点、环境或事物，不能用来形容“心情”。"}], "explanations": {"工作面": "正确答案。下雨后工作面地面湿滑，不太安全。", "歌曲": "语义：歌曲不是可以“安全”与否的对象，句意说不通。", "标点": "语义：标点是符号，不存在安全与否的问题。", "心情": "搭配：“安全”用于地点、环境或事物，不能用来形容“心情”。"}, "sentence_index": 6, "correct_answer": "工作面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在工作面上做饭。", "explanation": "这里应该用〈厨房〉。“工作面”是工人干活的地方，做饭要在厨房里。"}, {"text": "我们在工作面上踢足球。", "explanation": "这里应该用〈操场〉。“工作面”指工人干活的场地，踢足球要去操场。"}, {"text": "工人们每天穿着工作面去上班。", "explanation": "这里应该用〈工作服〉。“工作服”是上班时穿的衣服，可以说“穿着工作服”；“工作面”是工人干活的地方，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天早上先到这台工作面检查设备。", "corrected_sentence": "他每天早上先到这个工作面检查设备。", "error_description": "错误：量词用错。“工作面”应用量词“个”，不能用“台”（“台”多用于机器、设备）。应说“这个工作面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师傅们工作面上检查机器。", "corrected_sentence": "老师傅们在工作面上检查机器。", "error_description": "错误：漏了介词“在”。“工作面上”表示地点，前面要加“在”，应说“在工作面上检查机器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
