INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88604, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "矿井等处工人直接进行作业的场所。", "primary_collocate": null, "pronunciation": "gōng zuò miàn", "ipa": "kʊŋ˥ tswo˥˩ mjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "矿工们下井后，先到工作面。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤矿的工作面离地面很深。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作面每天能挖很多煤。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作面里又黑又热，大家都很辛苦。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长要求大家在工作面戴好帽子。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天工作面的灯坏了。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在煤矿的工作面干了十年。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的工作面已经准备好了。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作面上有水，要小心走路。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把煤从工作面运了出去。", "target_word": "工作面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "采煤工作面", "label": "复合"}], "register": "中性", "sense_fingerprint": "矿井里工人作业的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作面", "is_correct": true, "explanation": "正确答案。矿工下井后先到工作面，那是他们作业的地方。"}, {"text": "动物", "is_correct": false, "explanation": "语义：矿工不会先到“动物”那里，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "配价：“到”需要接地点，“课本”是物品，不能作为动作的目的地。"}, {"text": "地面", "is_correct": false, "explanation": "语义：矿工下井后不会先回到地面，与句意矛盾。"}], "explanations": {"工作面": "正确答案。矿工下井后先到工作面，那是他们作业的地方。", "动物": "语义：矿工不会先到“动物”那里，句意不通。", "课本": "配价：“到”需要接地点，“课本”是物品，不能作为动作的目的地。", "地面": "语义：矿工下井后不会先回到地面，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "工作面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷每天在工作面里散步。", "explanation": "这里应该用〈公园〉。“工作面”是矿井里工人作业的场所，不能用来散步。"}, {"text": "运动员在工作面里比赛。", "explanation": "这里应该用〈体育馆〉。“工作面”指矿井里工人作业的地方，不是比赛场所。"}, {"text": "矿工们每天穿着工作面下井。", "explanation": "这里应该用〈工作服〉。“工作服”是工作时穿的衣服，“穿着工作服下井”是常见说法；“工作面”指矿井里工人作业的场所，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作面", "is_correct": true, "explanation": "正确答案。“在……的工作面干了十年”指他在矿井的作业场所工作。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是可以“干”的工作场所，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是工作的场所，不能用来“干”。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“干了十年”要求工作场所，“早餐”不能与“干了十年”搭配。"}], "explanations": {"工作面": "正确答案。“在……的工作面干了十年”指他在矿井的作业场所工作。", "课本": "语义：课本不是可以“干”的工作场所，句意不通。", "歌曲": "语义：歌曲不是工作的场所，不能用来“干”。", "早餐": "搭配：“干了十年”要求工作场所，“早餐”不能与“干了十年”搭配。"}, "sentence_index": 6, "correct_answer": "工作面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在工作面上写作业。", "explanation": "这里应该用〈书桌〉。“工作面”是矿井里工人作业的场所，写作业要在书桌上。"}, {"text": "医生在工作面里给病人看病。", "explanation": "这里应该用〈诊室〉。“工作面”是工人作业的场所，不是看病的地方。"}, {"text": "矿工下井前要把工作面挂在胸前。", "explanation": "这里应该用〈工作证〉。“工作证”是证明身份的卡片，可以挂在胸前；“工作面”指矿井里工人作业的场所，不是可以挂的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们工作面里挖煤。", "corrected_sentence": "工人们在工作面里挖煤。", "error_description": "错误：漏了介词“在”。“工作面里”表示地点，前面要加“在”，应说“在工作面里挖煤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只工作面已经挖完了。", "corrected_sentence": "这个工作面已经挖完了。", "error_description": "错误：指示量词用错。“只”多用于动物，工作面是场所，应说“这个工作面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88605, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88605, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88605, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "避开是躲到一边，不碰上它。", "primary_collocate": null, "pronunciation": "bì kāi", "ipa": "pi⁵¹ kʰaɪ⁵⁵", "syllable_count": 2, "sentences": [{"text": "我们早点出门，避开上班的高峰。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车的时候，要避开路上的大水坑。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走到路边，避开了迎面来的自行车。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们选了周二去，正好避开周末的人群。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫跳到一边，避开了那只大狗。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天中午太热，最好避开高温的时候出门。", "target_word": "避开", "complexity_tier": "T3", "furigana": "xià tiān zhōng wǔ tài rè, zuì hǎo bì kāi gāo wēn de shí hou chū mén.", "sentence_source": "generated"}, {"text": "他提前换到另一条车道，避开了前面的事故。", "target_word": "避开", "complexity_tier": "T3", "furigana": "tā tí qián huàn dào lìng yī tiáo chē dào, bì kāi le qián miàn de shì gù.", "sentence_source": "generated"}, {"text": "请走左边，避开地上的玻璃。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机及时转弯，避开了前面的石头。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐早班车，就能避开堵车。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "避开了", "label": "完成体"}, {"form": "避开过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "身体或行动上躲到一边，不碰上人、车、障碍或时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "避开", "is_correct": true, "explanation": "正确。“避开”表示躲开，与“早点出门”想要躲开高峰的意图相符。"}, {"text": "迎上", "is_correct": false, "explanation": "语义：“迎上”表示主动走上前去，与“早点出门”想要避开高峰的意图相反。"}, {"text": "遇上", "is_correct": false, "explanation": "语义：“遇上”表示恰好碰到，与“早点出门”想要避开高峰的意图相反。"}, {"text": "拉开", "is_correct": false, "explanation": "搭配：“拉开”后接的是距离或间隔，不能直接接“高峰”这样的时段。"}], "explanations": {"避开": "正确。“避开”表示躲开，与“早点出门”想要躲开高峰的意图相符。", "迎上": "语义：“迎上”表示主动走上前去，与“早点出门”想要避开高峰的意图相反。", "遇上": "语义：“遇上”表示恰好碰到，与“早点出门”想要避开高峰的意图相反。", "拉开": "搭配：“拉开”后接的是距离或间隔，不能直接接“高峰”这样的时段。"}, "sentence_index": 0, "correct_answer": "避开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们选了周二去，正好避开了打折的日子，买到了很便宜的东西。", "explanation": "这里应该用〈赶上〉。“买到了很便宜的东西”说明碰上了打折，应用“赶上”；“避开”表示躲开、不碰上，与此冲突。"}, {"text": "我们周二去看朋友，正好避开了他，聊得很开心。", "explanation": "这里应该用〈碰上〉。“避开”表示躲开、不接触，与“聊得很开心”冲突；“碰上”表示恰好遇见。"}, {"text": "我们选了周二去，正好避开了好天气。", "explanation": "这里应该用〈错过〉。“好天气”不是需要躲开的对象；“错过”表示没有赶上，可用于“错过好天气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "避开", "is_correct": true, "explanation": "正确。“避开”表示躲开，与“提前换到另一条车道”想要躲开事故的意图相符。"}, {"text": "撞上", "is_correct": false, "explanation": "语义：“撞上”表示发生碰撞，与“提前换车道”想要躲开事故的意图相反。"}, {"text": "惹上", "is_correct": false, "explanation": "搭配：“惹上”多用于惹上麻烦、官司等，不能用于事故。"}, {"text": "赶上", "is_correct": false, "explanation": "语义：“赶上”可表示碰上（如“赶上下雨”），但与“提前换到另一条车道”想要躲开事故的意图相反。"}], "explanations": {"避开": "正确。“避开”表示躲开，与“提前换到另一条车道”想要躲开事故的意图相符。", "撞上": "语义：“撞上”表示发生碰撞，与“提前换车道”想要躲开事故的意图相反。", "惹上": "搭配：“惹上”多用于惹上麻烦、官司等，不能用于事故。", "赶上": "语义：“赶上”可表示碰上（如“赶上下雨”），但与“提前换到另一条车道”想要躲开事故的意图相反。"}, "sentence_index": 6, "correct_answer": "避开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐早班车，就能避开堵车，所以我们每天都堵在路上。", "explanation": "这里应该用〈遇上〉。句中“每天都堵在路上”说明仍然碰上堵车，应用“遇上”；“避开”表示躲开，与此冲突。"}, {"text": "我们坐早班车，就能避开我的同事，一起吃早饭。", "explanation": "这里应该用〈见到〉。“避开”表示有意不接触，与“一起吃早饭”冲突；“见到”表示碰见，与语境相符。"}, {"text": "这两个司机互相避开了对方，所以每次都撞在一起。", "explanation": "这里应该用〈碰上〉。句中“每次都撞在一起”说明他们总是碰到，应用“碰上”；“避开”表示有意不接触，与此冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开车的时候，我们尽量避开得施工的路段。", "corrected_sentence": "开车的时候，我们尽量避开施工的路段。", "error_description": "“避开得”错误，应为“避开”。“得”只用于可能补语的“避得开”，不能直接插在“避开”和宾语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车快到路口，我们要尽量避开了前面的大车。", "corrected_sentence": "车快到路口，我们要尽量避开前面的大车。", "error_description": "“避开了”错误，应为“避开”。“要尽量”表示意愿或将来，与表示完成的“了”冲突，“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88606, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88606, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "面对", "is_correct": true, "explanation": "正确。“面对”表示正视，与“避开”（有意不面对）相反。"}, {"text": "讨论", "is_correct": false, "explanation": "与“避开”没有反义关系，只是同为动词。"}, {"text": "相信", "is_correct": false, "explanation": "与“避开”没有反义关系，只是同为动词。"}, {"text": "帮助", "is_correct": false, "explanation": "与“避开”没有反义关系，只是同为动词。"}], "correct_answer": "面对", "explanations": {"面对": "正确。“面对”表示正视，与“避开”（有意不面对）相反。", "讨论": "与“避开”没有反义关系，只是同为动词。", "相信": "与“避开”没有反义关系，只是同为动词。", "帮助": "与“避开”没有反义关系，只是同为动词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "躲开；不与之接触。", "primary_collocate": null, "pronunciation": "bì kāi", "ipa": "pi⁵¹ kʰaɪ⁵⁵", "syllable_count": 2, "sentences": [{"text": "他一看见老板，心里就发慌，想避开。", "target_word": "避开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们聊天时，最好避开这个话题。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她最近一直在避开我，不想见面。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友生气了，我先避开他几天。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话很直，从不避开问题。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈问成绩，他总是想避开。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者一追问，她就避开了话题，什么也没说。", "target_word": "避开", "complexity_tier": "T3", "furigana": "jì zhě yī zhuī wèn, tā jiù bì kāi le huà tí, shén me yě méi shuō.", "sentence_source": "generated"}, {"text": "他想避开那些爱吵架的人。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说到钱的事，大家都避开了。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不能总是避开这件事，要面对它。", "target_word": "避开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "避开了", "label": "完成体"}, {"form": "避开过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "有意不与某人、某话题或某件事接触、不面对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "避开", "is_correct": true, "explanation": "正确。“避开”表示有意躲开，与“一看见老板，心里发慌”的语境相符。"}, {"text": "迎上", "is_correct": false, "explanation": "语义：“迎上”表示主动走上前去，与“心里发慌”的心态不合。"}, {"text": "接近", "is_correct": false, "explanation": "语义：“接近”表示靠近，与“心里发慌，想避开”的意图相反。"}, {"text": "亲近", "is_correct": false, "explanation": "语义：“亲近”表示关系亲密，与“心里发慌”的心态不合。"}], "explanations": {"避开": "正确。“避开”表示有意躲开，与“一看见老板，心里发慌”的语境相符。", "迎上": "语义：“迎上”表示主动走上前去，与“心里发慌”的心态不合。", "接近": "语义：“接近”表示靠近，与“心里发慌，想避开”的意图相反。", "亲近": "语义：“亲近”表示关系亲密，与“心里发慌”的心态不合。"}, "sentence_index": 0, "correct_answer": "避开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一起很久了，我却总是避开他，还常常打电话问他。", "explanation": "这里应该用〈联系〉。“常常打电话问他”属于主动联系，与“避开”表示的不接触相反，应用“联系”。"}, {"text": "我想和他说话，就主动避开他。", "explanation": "这里应该用〈接近〉。“接近”表示走近，与“想和他说话”的意愿一致；“避开”表示躲开，二者相反。"}, {"text": "妈妈很生气，他却主动避开了妈妈，去向她道歉。", "explanation": "这里应该用〈接近〉。“去向她道歉”需要走近对方，与“避开”表示的不接触相反；“接近”与之一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "避开", "is_correct": true, "explanation": "正确。“避开”表示躲开、不回应，与“记者一追问，她就……了话题，什么也没说”的语境相符。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”表示交流意见，与句末“什么也没说”矛盾。"}, {"text": "谈论", "is_correct": false, "explanation": "语义：“谈论”表示说起某件事，与句末“什么也没说”矛盾。"}, {"text": "回答", "is_correct": false, "explanation": "搭配：“回答”后接的是问题，不能直接接“话题”，且与“什么也没说”矛盾。"}], "explanations": {"避开": "正确。“避开”表示躲开、不回应，与“记者一追问，她就……了话题，什么也没说”的语境相符。", "讨论": "语义：“讨论”表示交流意见，与句末“什么也没说”矛盾。", "谈论": "语义：“谈论”表示说起某件事，与句末“什么也没说”矛盾。", "回答": "搭配：“回答”后接的是问题，不能直接接“话题”，且与“什么也没说”矛盾。"}, "sentence_index": 6, "correct_answer": "避开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很想见老同学，一到聚会就避开了大家，跟每个人都聊了很久。", "explanation": "这里应该用〈找到〉。“跟每个人都聊了很久”说明他主动接触大家；“避开”表示有意不接触，与此冲突。"}, {"text": "我们应该勇敢避开挑战。", "explanation": "这里应该用〈面对〉。“面对”表示正视困难，与“勇敢”的语境一致；“避开”表示躲开，与“勇敢”不搭配。"}, {"text": "他很想参加比赛，却每次都避开比赛。", "explanation": "这里应该用〈参加〉。“很想参加”表示愿意，与“避开”表示的有意不接触相反，应说“每次都参加比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不想再谈这件事，就想避开了这个话题。", "corrected_sentence": "我不想再谈这件事，就避开了这个话题。", "error_description": "“想避开了”错误，应为“就避开了”。“想”表示打算，“了”表示动作已经完成，二者不能同时用在同一动作上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不能一直避开了这个问题。", "corrected_sentence": "我们不能一直避开这个问题。", "error_description": "“避开了”错误，应为“避开”。“不能一直”表示持续或尚未发生的情形，与表示完成的“了”冲突，“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
