INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88607, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谈话是两个人或几个人在一起说话。", "primary_collocate": null, "pronunciation": "tán huà", "ipa": "tʰan˧˥ xua˥˩", "syllable_count": 2, "sentences": [{"text": "老师找我谈话。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在办公室里谈话。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个人坐在树下谈话。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们谈话的时候，他一直笑着。", "target_word": "谈话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在和客人谈话。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别人谈话时，请不要大声喧哗。", "target_word": "谈话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们谈话谈了很久。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理想找小王谈话。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "几个朋友在门口小声谈话。", "target_word": "谈话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们谈话的声音很小。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈了话", "label": "体标"}, {"form": "谈过话", "label": "体标"}, {"form": "談話", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两人或几人在一起说话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adf9579b-4126-4d8c-b7a3-be431450724f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88607, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谈话", "is_correct": true, "explanation": "谈话：两人或几人在一起说话，正是本词的意思。"}, {"text": "碳化", "is_correct": false, "explanation": "tàn（第四声）与 tán（第二声）声调不同，碳化指化学上的碳化过程，不是交谈。"}, {"text": "弹花", "is_correct": false, "explanation": "huā（第一声）与 huà（第四声）声调不同，弹花指用弓弹松棉花，不是说话。"}, {"text": "糖化", "is_correct": false, "explanation": "táng 与 tán 韵母不同（-ang 对 -an），糖化指淀粉分解成糖，不是交谈。"}], "explanations": {"谈话": "谈话：两人或几人在一起说话，正是本词的意思。", "碳化": "tàn（第四声）与 tán（第二声）声调不同，碳化指化学上的碳化过程，不是交谈。", "弹花": "huā（第一声）与 huà（第四声）声调不同，弹花指用弓弹松棉花，不是说话。", "糖化": "táng 与 tán 韵母不同（-ang 对 -an），糖化指淀粉分解成糖，不是交谈。"}, "sentence_index": null, "correct_answer": "谈话"}, "level_3": {"options": [{"text": "谈话", "is_correct": true, "explanation": "正确：“老师找我谈话”指老师找我当面谈事情。"}, {"text": "谈恋爱", "is_correct": false, "explanation": "语义：谈恋爱指男女之间相爱，老师和学生之间不能这样说。"}, {"text": "撒娇", "is_correct": false, "explanation": "语义：撒娇是对亲近的人任性撒痴，不用于老师找学生。"}, {"text": "毕业", "is_correct": false, "explanation": "语法：毕业是不及物动词，不能说“老师找我毕业”。"}], "explanations": {"谈话": "正确：“老师找我谈话”指老师找我当面谈事情。", "谈恋爱": "语义：谈恋爱指男女之间相爱，老师和学生之间不能这样说。", "撒娇": "语义：撒娇是对亲近的人任性撒痴，不用于老师找学生。", "毕业": "语法：毕业是不及物动词，不能说“老师找我毕业”。"}, "sentence_index": 0, "correct_answer": "谈话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长一个人站在台上谈话，台下没有人回应。", "explanation": "这里应该用〈讲话〉。谈话需要两人或几人互相交谈，一人对着台下讲话不是谈话。"}, {"text": "他谈话很快，大家都听不清。", "explanation": "这里应该用〈说话〉。谈话指交谈这件事，不用来描述说话的速度。"}, {"text": "在市场上，我和摊主谈话，摊主一句话也没说。", "explanation": "谈话需要双方都开口交流；摊主一句话也不说时，不能用谈话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88607, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈话", "is_correct": true, "explanation": "正确：“他们谈话谈了很久”中，谈话指两人或多人交谈。"}, {"text": "打招呼", "is_correct": false, "explanation": "语义：打招呼只是简短的问候，与“谈了很久”的时长矛盾。"}, {"text": "点头", "is_correct": false, "explanation": "搭配：点头是身体动作，不能说“点头谈了很久”。"}, {"text": "眨眼", "is_correct": false, "explanation": "语义：眨眼是瞬间的动作，无法持续很久，与“谈了很久”矛盾。"}], "explanations": {"谈话": "正确：“他们谈话谈了很久”中，谈话指两人或多人交谈。", "打招呼": "语义：打招呼只是简短的问候，与“谈了很久”的时长矛盾。", "点头": "搭配：点头是身体动作，不能说“点头谈了很久”。", "眨眼": "语义：眨眼是瞬间的动作，无法持续很久，与“谈了很久”矛盾。"}, "sentence_index": 6, "correct_answer": "谈话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国要加强文化谈话，促进相互了解。", "explanation": "这里应该用〈交流〉。谈话指两人或几人当面交谈，“加强……”后面的文化往来要用交流。"}, {"text": "两队选手在台上谈话，拍着桌子大声对骂。", "explanation": "这里应该用〈吵架〉。谈话是平和的交谈，拍桌子大声对骂要用吵架。"}, {"text": "他一个人坐在床边谈话，房间里没有别人。", "explanation": "这里应该用〈自言自语〉。谈话需要两人或几人交谈，一人说话不是谈话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88607, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天跟老师谈话问题。", "corrected_sentence": "我明天跟老师谈话。", "error_description": "“谈话”是不及物的离合词，后面不能直接带“问题”作宾语。应删去“问题”，写作“我明天跟老师谈话。”若要说谈论的内容，可用“谈问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88607, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和老师谈话过。", "corrected_sentence": "我和老师谈过话。", "error_description": "“谈话”是离合词，体标“过”要放在“谈”后面，写作“谈过话”。“谈话过”的位置不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
