INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或多人之间交谈。", "primary_collocate": null, "pronunciation": "tán huà", "ipa": "tʰan˧˥ xua˥˩", "syllable_count": 2, "sentences": [{"text": "校长找他谈话，问他为什么迟到。", "target_word": "谈话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学在教室外谈话。", "target_word": "谈话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢和老人谈话。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天下午，老板和我谈话了。", "target_word": "谈话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一边走一边谈话。", "target_word": "谈话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在院子里高兴地谈话。", "target_word": "谈话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两位老人在公园里谈话。", "target_word": "谈话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生要和你的家人谈话。", "target_word": "谈话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在电话里谈话，听不清楚。", "target_word": "谈话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们谈话时，我在旁边看书。", "target_word": "谈话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈了话", "label": "体标"}, {"form": "谈过话", "label": "体标"}, {"form": "談話", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两人或多人之间交谈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adf9579b-4126-4d8c-b7a3-be431450724f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谈话", "is_correct": true, "explanation": "谈话：两人或多人之间交谈，正是本词的意思。"}, {"text": "碳化", "is_correct": false, "explanation": "tàn（第四声）与 tán（第二声）声调不同，碳化指化学上的碳化过程，不是交谈。"}, {"text": "弹花", "is_correct": false, "explanation": "huā（第一声）与 huà（第四声）声调不同，弹花指用弓弹松棉花，不是说话。"}, {"text": "糖化", "is_correct": false, "explanation": "táng 与 tán 韵母不同（-ang 对 -an），糖化指淀粉分解成糖，不是交谈。"}], "explanations": {"谈话": "谈话：两人或多人之间交谈，正是本词的意思。", "碳化": "tàn（第四声）与 tán（第二声）声调不同，碳化指化学上的碳化过程，不是交谈。", "弹花": "huā（第一声）与 huà（第四声）声调不同，弹花指用弓弹松棉花，不是说话。", "糖化": "táng 与 tán 韵母不同（-ang 对 -an），糖化指淀粉分解成糖，不是交谈。"}, "sentence_index": null, "correct_answer": "谈话"}, "level_3": {"options": [{"text": "谈话", "is_correct": true, "explanation": "正确：“校长找他谈话”指校长找他当面谈事情。"}, {"text": "撒娇", "is_correct": false, "explanation": "语义：撒娇是对亲近的人任性撒痴，不用于校长找学生问话。"}, {"text": "毕业", "is_correct": false, "explanation": "语法：毕业是不及物动词，不能说“校长找他毕业”。"}, {"text": "谈恋爱", "is_correct": false, "explanation": "语义：谈恋爱指男女相爱，与“问他为什么迟到”的语境不符。"}], "explanations": {"谈话": "正确：“校长找他谈话”指校长找他当面谈事情。", "撒娇": "语义：撒娇是对亲近的人任性撒痴，不用于校长找学生问话。", "毕业": "语法：毕业是不及物动词，不能说“校长找他毕业”。", "谈恋爱": "语义：谈恋爱指男女相爱，与“问他为什么迟到”的语境不符。"}, "sentence_index": 0, "correct_answer": "谈话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师一个人在教室里谈话，没有学生回应。", "explanation": "这里应该用〈自言自语〉。谈话需要两人或几人交谈，一人说话不是谈话。"}, {"text": "她谈话很慢，我们等了很久。", "explanation": "这里应该用〈说话〉。谈话指交谈这件事，不用来描述说话的速度。"}, {"text": "在菜市场，我对着摊主谈话，摊主头也不抬地忙着称菜。", "explanation": "谈话需要双方互相交流；只有一方说话、另一方不回应时，不能用谈话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈话", "is_correct": true, "explanation": "正确：“两位老人在公园里谈话”指两位老人在公园里交谈。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课是在学校里进行的活动，两位老人在公园里不能“上课”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是在学校或考场进行的活动，与公园的场景不符。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：洗澡一般在浴室或浴缸里进行，不说“在公园里洗澡”。"}], "explanations": {"谈话": "正确：“两位老人在公园里谈话”指两位老人在公园里交谈。", "上课": "语义：上课是在学校里进行的活动，两位老人在公园里不能“上课”。", "考试": "语义：考试是在学校或考场进行的活动，与公园的场景不符。", "洗澡": "搭配：洗澡一般在浴室或浴缸里进行，不说“在公园里洗澡”。"}, "sentence_index": 6, "correct_answer": "谈话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们每个月互相谈话，一写就是好几页纸。", "explanation": "这里应该用〈通信〉。谈话指口头交谈，书信往来要用通信。"}, {"text": "两位候选人在电视上谈话，拍着桌子互相大骂。", "explanation": "这里应该用〈吵架〉。谈话是平和的交谈，拍桌子互相大骂要用吵架。"}, {"text": "她一个人站在窗前谈话，没有人理她。", "explanation": "这里应该用〈自言自语〉。谈话需要两人或几人交谈，一人说话不是谈话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天找老板谈话工作。", "corrected_sentence": "我明天找老板谈话。", "error_description": "“谈话”是不及物的离合词，后面不能直接带“工作”作宾语。应删去“工作”，写作“我明天找老板谈话。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一边走一边谈话学习。", "corrected_sentence": "他们一边走一边谈话。", "error_description": "“谈话”是不及物的离合词，后面不能直接带“学习”作宾语。应删去“学习”，写作“他们一边走一边谈话。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edae3028-438b-4ea2-bfb3-92bec6308192') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
