INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88609, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "长按是用手指在屏幕上按住一会儿不放。", "primary_collocate": null, "pronunciation": "cháng àn", "ipa": "ʈʂʰɑŋ³⁵ an⁵¹", "syllable_count": 2, "sentences": [{"text": "长按手机屏幕，就能打开设置。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长按着图标，图标开始动了。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长按那条短信，可以把它删掉。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长按了好几秒游戏图标。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你长按地图上的一个点，就能找到路。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长按语音键说话，说完再松开。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我长按过这个软件的图标，没有看到新功能。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请长按屏幕，直到出现红色的圈。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷学会了长按屏幕上的照片。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手指长按在屏幕上，别动，也别松开。", "target_word": "长按", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "长按了", "label": "完成体"}, {"form": "长按着", "label": "持续体"}, {"form": "长按过", "label": "经历体"}], "register": "口语", "sense_fingerprint": "长按：用手指在触摸屏上按住不放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df93761e-3099-453a-be8c-fa0da9ef77d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88609, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长按", "is_correct": true, "explanation": "正确：「长按」指用手指按住屏幕不放，与「就能打开设置」的操作相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：「擦」表示抹去污渍，不能用来打开设置。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：「抱」搭配人或可抱的物体，「抱手机屏幕」不成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发声歌唱，句中没有对应的对象，与按屏幕的操作不合。"}], "explanations": {"长按": "正确：「长按」指用手指按住屏幕不放，与「就能打开设置」的操作相符。", "擦": "语义：「擦」表示抹去污渍，不能用来打开设置。", "抱": "搭配：「抱」搭配人或可抱的物体，「抱手机屏幕」不成立。", "唱": "语义：「唱」指发声歌唱，句中没有对应的对象，与按屏幕的操作不合。"}, "sentence_index": 0, "correct_answer": "长按"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子长按了好几声妈妈。", "explanation": "这里应该用〈喊〉。长按是按住屏幕，不能用来形容发出声音。"}, {"text": "这道题他长按了好几秒。", "explanation": "这里应该用〈思考〉。长按只用于屏幕或按键，不能用于思考题目。"}, {"text": "孩子长按了好几遍道理。", "explanation": "这里应该用〈讲〉。长按只用于屏幕或按键，不能用于道理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长按", "is_correct": true, "explanation": "正确：「长按」表示用手指按住图标不放，与「长按过这个软件的图标」的操作相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，「吃这个软件」搭配不当。"}, {"text": "闻", "is_correct": false, "explanation": "语义：「闻」指用鼻子感知气味，与操作软件的意思不合。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：「嚼」的对象是食物，「嚼这个软件」搭配不当。"}], "explanations": {"长按": "正确：「长按」表示用手指按住图标不放，与「长按过这个软件的图标」的操作相符。", "吃": "搭配：「吃」的对象是食物，「吃这个软件」搭配不当。", "闻": "语义：「闻」指用鼻子感知气味，与操作软件的意思不合。", "嚼": "搭配：「嚼」的对象是食物，「嚼这个软件」搭配不当。"}, "sentence_index": 6, "correct_answer": "长按"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "把纸长按在书里。", "explanation": "这里应该用〈夹〉。长按只用于屏幕或按键，不能用于把纸夹在书里。"}, {"text": "妈妈每天长按肩膀，缓解疲劳。", "explanation": "这里应该用〈按摩〉。长按只用于按键或屏幕，不能用来描述给肩膀做按摩。"}, {"text": "他长按起了箱子。", "explanation": "这里应该用〈搬〉。长按指在屏幕或按键上持续按压，不能用于搬起箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请长按了手机屏幕上的图标，就能移动它。", "corrected_sentence": "请长按手机屏幕上的图标，就能移动它。", "error_description": "错误：祈使句「请长按……」后多加了完成体标记「了」，表示动作已完成，与请求对方去做的语气矛盾。正确形式是「请长按手机屏幕上的图标」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请长按过图标两秒，它就会动起来。", "corrected_sentence": "请长按图标两秒，它就会动起来。", "error_description": "错误：祈使句「请长按……」后误加了经历体标记「过」。「过」表示动作曾经发生，与请求对方现在去做的语气矛盾，应去掉「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
