INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88611, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "证实是用办法让大家知道某件事是真的。", "primary_collocate": null, "pronunciation": "zhèng shí", "ipa": "tʂɤŋ˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "警察证实了这个消息。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生证实他没有生病。", "target_word": "证实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次实验证实了他的想法。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司已经证实了这件事。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片证实他去过那里。", "target_word": "证实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想证实学生说的是真话。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要证据来证实这个说法。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿出车票证实自己去过那里。", "target_word": "证实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的话证实了他没说谎。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事还没有人证实。", "target_word": "证实", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "证实了", "label": "了体"}, {"form": "证实过", "label": "过体"}], "register": "书面", "sense_fingerprint": "用办法让大家知道某件事是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d06d0e-067c-4c11-97ae-a74e588d261c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88611, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证实", "is_correct": true, "explanation": "正确：证实 zhèng shí，意思是用办法让大家知道某件事是真的。"}, {"text": "正式", "is_correct": false, "explanation": "zhèng shì（第四声）与 zhèng shí（第二声）声调不同，意思是正式、合乎规定。"}, {"text": "正史", "is_correct": false, "explanation": "zhèng shǐ（第三声）与 zhèng shí（第二声）声调不同，意思是官方编修的史书。"}, {"text": "正职", "is_correct": false, "explanation": "zhèng zhí 与 zhèng shí 只有第二个音节的声母不同（zh 与 sh），意思是主要职位，与副职相对。"}], "explanations": {"证实": "正确：证实 zhèng shí，意思是用办法让大家知道某件事是真的。", "正式": "zhèng shì（第四声）与 zhèng shí（第二声）声调不同，意思是正式、合乎规定。", "正史": "zhèng shǐ（第三声）与 zhèng shí（第二声）声调不同，意思是官方编修的史书。", "正职": "zhèng zhí 与 zhèng shí 只有第二个音节的声母不同（zh 与 sh），意思是主要职位，与副职相对。"}, "sentence_index": null, "correct_answer": "证实"}, "level_3": {"options": [{"text": "证实", "is_correct": true, "explanation": "正确：“证实”指确认消息为真，与“警察”和“这个消息”相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”指操纵车辆，消息不能被驾驶。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不能说“饲养这个消息”。"}, {"text": "培养", "is_correct": false, "explanation": "搭配：“培养”的对象是人才、习惯，不能说“培养这个消息”。"}], "explanations": {"证实": "正确：“证实”指确认消息为真，与“警察”和“这个消息”相符。", "驾驶": "语义：“驾驶”指操纵车辆，消息不能被驾驶。", "饲养": "搭配：“饲养”的对象是动物，不能说“饲养这个消息”。", "培养": "搭配：“培养”的对象是人才、习惯，不能说“培养这个消息”。"}, "sentence_index": 0, "correct_answer": "证实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这本书证实给了朋友。", "explanation": "这里应该用〈送〉。证实是确认事情为真，不能表示把东西交给别人，送书要用送。"}, {"text": "他在院子里证实了一棵树。", "explanation": "这里应该用〈种〉。证实是确认事情为真，不能表示栽种植物。"}, {"text": "同学们正在证实课文。", "explanation": "这里应该用〈背〉。证实是确认事情为真，不能表示背诵课文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88611, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "证实", "is_correct": true, "explanation": "正确：证实 zhèng shí，意思是用办法让大家知道某件事是真的。"}, {"text": "政事", "is_correct": false, "explanation": "zhèng shì（第四声）与 zhèng shí（第二声）声调不同，意思是政治方面的事务。"}, {"text": "正使", "is_correct": false, "explanation": "zhèng shǐ（第三声）与 zhèng shí（第二声）声调不同，意思是出使时的主要使臣。"}, {"text": "争食", "is_correct": false, "explanation": "zhēng shí（第一声）与 zhèng shí（第四声）第一个音节声调不同，意思是争抢食物。"}], "explanations": {"证实": "正确：证实 zhèng shí，意思是用办法让大家知道某件事是真的。", "政事": "zhèng shì（第四声）与 zhèng shí（第二声）声调不同，意思是政治方面的事务。", "正使": "zhèng shǐ（第三声）与 zhèng shí（第二声）声调不同，意思是出使时的主要使臣。", "争食": "zhēng shí（第一声）与 zhèng shí（第四声）第一个音节声调不同，意思是争抢食物。"}, "sentence_index": null, "correct_answer": "证实"}, "level_3": {"options": [{"text": "证实", "is_correct": true, "explanation": "正确：“证实”指通过证据确认说法为真，与“证据”和“这个说法”相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，“说法”不能被喝，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱这个说法”。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象是火、火柴等，不能说“点燃这个说法”。"}], "explanations": {"证实": "正确：“证实”指通过证据确认说法为真，与“证据”和“这个说法”相符。", "喝": "语义：“喝”指饮用，“说法”不能被喝，句子说不通。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱这个说法”。", "点燃": "搭配：“点燃”的对象是火、火柴等，不能说“点燃这个说法”。"}, "sentence_index": 6, "correct_answer": "证实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上证实一杯牛奶。", "explanation": "这里应该用〈喝〉。证实是确认事情为真，不能表示饮用。"}, {"text": "妈妈在厨房里证实了一锅汤。", "explanation": "这里应该用〈煮〉。证实是确认事情为真，不能表示烹煮。"}, {"text": "他很认真地证实了跑步。", "explanation": "这里应该用〈锻炼〉。证实是确认事情为真，不能表示做运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.