INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "用事实证明其确实。", "primary_collocate": null, "pronunciation": "zhèng shí", "ipa": "tʂɤŋ˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "新的数据证实了这个看法。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用实验证实了猜想。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家的研究证实了这一点。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最后的结果证实他是对的。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息已经得到证实。", "target_word": "证实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "检查结果证实她没有问题。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "后来的事证实了我的担心。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "录像证实了他当时在场。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "调查还没有证实这个传言。", "target_word": "证实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩证实他很努力。", "target_word": "证实", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "证实了", "label": "了体"}, {"form": "证实过", "label": "过体"}], "register": "书面", "sense_fingerprint": "用事实证明某事确实如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d06d0e-067c-4c11-97ae-a74e588d261c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88612, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证实", "is_correct": true, "explanation": "正确：证实 zhèng shí，意思是用事实证明某事确实如此。"}, {"text": "正史", "is_correct": false, "explanation": "zhèng shǐ（第三声）与 zhèng shí（第二声）声调不同，意思是官方编修的史书。"}, {"text": "正职", "is_correct": false, "explanation": "zhèng zhí 与 zhèng shí 只有第二个音节的声母不同（zh 与 sh），意思是主要职位，与副职相对。"}, {"text": "正事", "is_correct": false, "explanation": "zhèng shì（第四声）与 zhèng shí（第二声）声调不同，意思是正经的事情。"}], "explanations": {"证实": "正确：证实 zhèng shí，意思是用事实证明某事确实如此。", "正史": "zhèng shǐ（第三声）与 zhèng shí（第二声）声调不同，意思是官方编修的史书。", "正职": "zhèng zhí 与 zhèng shí 只有第二个音节的声母不同（zh 与 sh），意思是主要职位，与副职相对。", "正事": "zhèng shì（第四声）与 zhèng shí（第二声）声调不同，意思是正经的事情。"}, "sentence_index": null, "correct_answer": "证实"}, "level_3": {"options": [{"text": "证实", "is_correct": true, "explanation": "正确：“证实”指用事实证明看法确实如此，与“新的数据”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于“看法”，数据不能吃掉看法。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球，不能说“踢这个看法”。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”指操纵车辆，看法不能被驾驶。"}], "explanations": {"证实": "正确：“证实”指用事实证明看法确实如此，与“新的数据”相符。", "吃": "语义：“吃”不能用于“看法”，数据不能吃掉看法。", "踢": "搭配：“踢”的对象是球，不能说“踢这个看法”。", "驾驶": "语义：“驾驶”指操纵车辆，看法不能被驾驶。"}, "sentence_index": 0, "correct_answer": "证实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在厨房里证实了一碗饭。", "explanation": "这里应该用〈做〉。证实是确认事情为真，不能表示做饭。"}, {"text": "孩子们在操场上证实了足球。", "explanation": "这里应该用〈踢〉。证实是确认事情为真，不能表示做体育动作。"}, {"text": "他认真证实了一首歌。", "explanation": "这里应该用〈听〉。证实是确认事情为真，不能表示听音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_