INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88613, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "幼儿是年纪很小很小的孩子。", "primary_collocate": null, "pronunciation": "yòu ér", "ipa": "jou˥˩ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "幼儿需要大人每天照顾。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个幼儿还不会自己穿衣服。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿的笑声让全家人都很开心。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给幼儿讲了一个小故事。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多幼儿在玩沙子。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿喜欢听歌，也喜欢跳舞。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是为幼儿写的，字很大。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿吃饭的时候，爸爸一直在旁边看着。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说幼儿不能吃太硬的东西。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个幼儿一看见妈妈就哭了。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "幼儿园", "label": "复合"}], "register": "中性", "sense_fingerprint": "年纪很小很小的孩子，需要大人照顾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼儿", "is_correct": true, "explanation": "年纪很小的孩子，需要大人每天照顾，符合句意。"}, {"text": "老板", "is_correct": false, "explanation": "语义：老板是成年的经营者，不需要大人每天照顾，与句意矛盾。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是成年人，不会需要大人每天照顾，句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有需要大人每天照顾的生命，句意不通。"}], "explanations": {"幼儿": "年纪很小的孩子，需要大人每天照顾，符合句意。", "老板": "语义：老板是成年的经营者，不需要大人每天照顾，与句意矛盾。", "老师": "语义：老师是成年人，不会需要大人每天照顾，句意不通。", "椅子": "语义：椅子没有需要大人每天照顾的生命，句意不通。"}, "sentence_index": 0, "correct_answer": "幼儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的幼儿都已经十五岁了。", "explanation": "这里应该用〈青少年〉。幼儿指年纪很小的孩子，十五岁的学生应说青少年。"}, {"text": "幼儿每天要去图书馆自习。", "explanation": "这里应该用〈学生〉。幼儿年纪很小，还不会自习，去图书馆自习的应说学生。"}, {"text": "这位幼儿已经四十岁了。", "explanation": "这里应该用〈中年人〉。幼儿指年纪很小的孩子，不能用来指四十岁的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼儿", "is_correct": true, "explanation": "这本书的读者是年纪很小的孩子，字大，符合句意。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“为……写的书”的读者应能读字，不能说为猫写书。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不读书，“字很大”的读者不可能是机器。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：“为……写”要求有阅读能力的对象，蔬菜不能作读者。"}], "explanations": {"幼儿": "这本书的读者是年纪很小的孩子，字大，符合句意。", "猫": "搭配：“为……写的书”的读者应能读字，不能说为猫写书。", "机器": "语义：机器不读书，“字很大”的读者不可能是机器。", "蔬菜": "搭配：“为……写”要求有阅读能力的对象，蔬菜不能作读者。"}, "sentence_index": 6, "correct_answer": "幼儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这窝小兔都是幼儿。", "explanation": "这里应该用〈幼崽〉。幼儿只指人类的小孩，动物的小崽要说幼崽。"}, {"text": "我们公司新来了三十名幼儿。", "explanation": "这里应该用〈员工〉。幼儿指年纪很小的孩子，不能指公司里的员工。"}, {"text": "幼儿每天开车去上班。", "explanation": "这里应该用〈司机〉。幼儿年纪还小，不会开车上班，不能指这类人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只幼儿每天都要喝牛奶。", "corrected_sentence": "这个幼儿每天都要喝牛奶。", "error_description": "量词错误：“幼儿”指人，量词应用“个”或“名”，不用“只”。“只”一般用于动物等，所以应说“这个幼儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师一定要教好这只幼儿。", "corrected_sentence": "老师一定要教好这个幼儿。", "error_description": "量词错误：“幼儿”指人，量词应用“个”，不用“只”。“只”一般用于动物，所以应说“这个幼儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
