INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年纪很小、尚未上学的孩子。", "primary_collocate": null, "pronunciation": "yòu ér", "ipa": "jou˥˩ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "幼儿还没上学，白天在家玩。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店专门卖幼儿的衣服和玩具。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很关心每个幼儿。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区为幼儿建了一个安全的游乐场。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿还没到上学的年纪，要多玩。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目是给还没上学的幼儿看的。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带着幼儿去图书馆借绘本。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年这个幼儿就要上学了。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿坐公共汽车可以不买票。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天陪幼儿读绘本，一起画画。", "target_word": "幼儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "幼儿园", "label": "复合"}], "register": "中性", "sense_fingerprint": "年纪很小、还没上学的孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼儿", "is_correct": true, "explanation": "年纪很小、还没上学的孩子，符合“还没上学”的句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生已经上学，与“还没上学”矛盾。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是成年人，不可能“还没上学”。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：“玩”用于人或动物，植物不说在家玩。"}], "explanations": {"幼儿": "年纪很小、还没上学的孩子，符合“还没上学”的句意。", "学生": "语义：学生已经上学，与“还没上学”矛盾。", "老师": "语义：老师是成年人，不可能“还没上学”。", "植物": "搭配：“玩”用于人或动物，植物不说在家玩。"}, "sentence_index": 0, "correct_answer": "幼儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司专门招聘幼儿。", "explanation": "这里应该用〈大学毕业生〉。幼儿还没上学，不能被公司招聘，招聘的对象应是大学毕业生这样的成年人。"}, {"text": "幼儿要参加期末考试。", "explanation": "这里应该用〈中学生〉。幼儿还没上学，不参加期末考试。"}, {"text": "这窝小狗都是幼儿。", "explanation": "这里应该用〈幼崽〉。幼儿只指人类的小孩，动物的小崽要说幼崽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼儿", "is_correct": true, "explanation": "年纪很小、还没上学的孩子，需要妈妈带着去图书馆，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能去图书馆借绘本，句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会借书，“带着椅子去借绘本”不成立。"}, {"text": "猫", "is_correct": false, "explanation": "语义：借绘本是给会看书的小孩子，猫不会看绘本，句意不通。"}], "explanations": {"幼儿": "年纪很小、还没上学的孩子，需要妈妈带着去图书馆，符合句意。", "汽车": "语义：汽车不能去图书馆借绘本，句意不通。", "椅子": "语义：椅子不会借书，“带着椅子去借绘本”不成立。", "猫": "语义：借绘本是给会看书的小孩子，猫不会看绘本，句意不通。"}, "sentence_index": 6, "correct_answer": "幼儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天陪幼儿去公司开会。", "explanation": "这里应该用〈同事〉。幼儿指年纪很小的孩子，不能指去公司开会的人。"}, {"text": "老师让幼儿写三篇读后感。", "explanation": "这里应该用〈学生〉。幼儿还没上学，不会写读后感。"}, {"text": "幼儿每天骑摩托车上班。", "explanation": "这里应该用〈司机〉。幼儿年纪很小，不会骑车上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只幼儿今年才三岁。", "corrected_sentence": "这个幼儿今年才三岁。", "error_description": "量词错误：指人的“幼儿”应用“个”，不能用“只”，应说“这个幼儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天都细心照顾这只幼儿。", "corrected_sentence": "她每天都细心照顾这个幼儿。", "error_description": "量词错误：指人的“幼儿”应用“个”，不能用“只”，应说“这个幼儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
