INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88617, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "资讯是别人告诉你的新消息。", "primary_collocate": null, "pronunciation": "zī xùn", "ipa": "tsɨ˥ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "我每天上网看新闻和资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站有很多旅游资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想获取最新的比赛资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上的资讯太多了。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我发来一条重要资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我有关这家店的资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有不少教育资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资讯对我找工作很有用。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在群里分享了考试资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在查找资讯非常方便。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "资讯", "label": "原形"}, {"form": "資訊", "label": "繁体"}], "register": "书面", "sense_fingerprint": "别人告知的新消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88617, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资讯", "is_correct": true, "explanation": "正确答案。资讯（zī xùn）指别人告诉你的新消息。"}, {"text": "咨询", "is_correct": false, "explanation": "xún（第二声）与 xùn（第四声）声调不同；咨询表示向人请教，不是消息。"}, {"text": "资信", "is_correct": false, "explanation": "xìn 与 xùn 韵母不同（in/un）；资信指信用状况，不指消息。"}, {"text": "私讯", "is_correct": false, "explanation": "sī 与 zī 声母不同（s/z）；私讯指私下发送的信息，不是别人告知的新消息。"}], "explanations": {"资讯": "正确答案。资讯（zī xùn）指别人告诉你的新消息。", "咨询": "xún（第二声）与 xùn（第四声）声调不同；咨询表示向人请教，不是消息。", "资信": "xìn 与 xùn 韵母不同（in/un）；资信指信用状况，不指消息。", "私讯": "sī 与 zī 声母不同（s/z）；私讯指私下发送的信息，不是别人告知的新消息。"}, "sentence_index": null, "correct_answer": "资讯"}, "level_3": {"options": [{"text": "资讯", "is_correct": true, "explanation": "正确。资讯指新消息，与“新闻”并列，表示上网查看的内容。"}, {"text": "食物", "is_correct": false, "explanation": "语义：上网看的是新闻和信息，食物不是可以“看”的内容。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以上网查看的内容。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“看”不能与“香味”搭配，香味要用“闻”。"}], "explanations": {"资讯": "正确。资讯指新消息，与“新闻”并列，表示上网查看的内容。", "食物": "语义：上网看的是新闻和信息，食物不是可以“看”的内容。", "冰箱": "语义：冰箱是家电，不是可以上网查看的内容。", "香味": "搭配：“看”不能与“香味”搭配，香味要用“闻”。"}, "sentence_index": 0, "correct_answer": "资讯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个很有耐心的资讯。", "explanation": "这里应该用〈记者〉。资讯指消息，不指人；做采访、报道的人才是〈记者〉。"}, {"text": "他的资讯不好，银行不愿意借钱给他。", "explanation": "这里应该用〈资信〉。资信指信用状况，银行放贷看的是资信，资讯指消息。"}, {"text": "我在网上查到了一台资讯。", "explanation": "这里应该用〈条〉。台用于机器，资讯应用“条”或“则”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88617, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资讯", "is_correct": true, "explanation": "正确。资讯指教育方面的消息，与“报纸上有不少”搭配自然。"}, {"text": "家具", "is_correct": false, "explanation": "语义：报纸上刊登的是文字消息，家具不是报纸的内容。"}, {"text": "香料", "is_correct": false, "explanation": "语义：“教育”后面不能接“香料”，报纸上也不会刊登香料。"}, {"text": "油漆", "is_correct": false, "explanation": "语义：报纸上刊登的是消息，油漆不是可以刊登的内容，“教育油漆”也不成立。"}], "explanations": {"资讯": "正确。资讯指教育方面的消息，与“报纸上有不少”搭配自然。", "家具": "语义：报纸上刊登的是文字消息，家具不是报纸的内容。", "香料": "语义：“教育”后面不能接“香料”，报纸上也不会刊登香料。", "油漆": "语义：报纸上刊登的是消息，油漆不是可以刊登的内容，“教育油漆”也不成立。"}, "sentence_index": 6, "correct_answer": "资讯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都去财务室领资讯。", "explanation": "这里应该用〈工资〉。领的是工资，资讯是消息，不能被领取。"}, {"text": "他每周都要交一份资讯。", "explanation": "这里应该用〈报告〉。报告是要上交的书面文件，资讯是消息，不是可以上交的文件。"}, {"text": "他们正在努力筹集资讯。", "explanation": "这里应该用〈资金〉。筹集的是钱，资讯是消息，不能被筹集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天收到了一位重要资讯。", "corrected_sentence": "我昨天收到了一条重要资讯。", "error_description": "错误：“一位重要资讯”；正确：“一条重要资讯”。“位”用于人，资讯是消息，应用“条”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把考试资讯们发到了群里。", "corrected_sentence": "老师把考试资讯发到了群里。", "error_description": "错误：“资讯们”；正确：“资讯”。“们”只用于指人的名词，“资讯”不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
