INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信息；消息。", "primary_collocate": null, "pronunciation": "zī xùn", "ipa": "tsɨ˥ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司提供科技资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的资讯不一定都是真的。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在找关于大学的资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学会选择有用的资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件每天推送健康资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在网站上查到航班资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份杂志有很多电影资讯。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这方面的资讯知道得很少。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把收集到的资讯写在本子上。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把活动资讯发给大家。", "target_word": "资讯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "资讯", "label": "原形"}, {"form": "資訊", "label": "繁体"}], "register": "书面", "sense_fingerprint": "信息、消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资讯", "is_correct": true, "explanation": "正确答案。资讯（zī xùn）指信息、消息。"}, {"text": "咨询", "is_correct": false, "explanation": "xún（第二声）与 xùn（第四声）声调不同；咨询表示请教、询问，不是信息。"}, {"text": "资信", "is_correct": false, "explanation": "xìn 与 xùn 韵母不同（in/un）；资信指信用状况。"}, {"text": "私讯", "is_correct": false, "explanation": "sī 与 zī 声母不同（s/z）；私讯指私下发送的信息，不是泛指的信息。"}], "explanations": {"资讯": "正确答案。资讯（zī xùn）指信息、消息。", "咨询": "xún（第二声）与 xùn（第四声）声调不同；咨询表示请教、询问，不是信息。", "资信": "xìn 与 xùn 韵母不同（in/un）；资信指信用状况。", "私讯": "sī 与 zī 声母不同（s/z）；私讯指私下发送的信息，不是泛指的信息。"}, "sentence_index": null, "correct_answer": "资讯"}, "level_3": {"options": [{"text": "资讯", "is_correct": true, "explanation": "正确。资讯指科技方面的信息，与“提供科技”搭配自然。"}, {"text": "调料", "is_correct": false, "explanation": "语义：“科技”不能修饰调料，这句话指公司提供的是科技内容。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“提供”后不能直接接“感情”，“科技感情”也不成词。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是公司可以提供的科技内容，与“科技”不搭。"}], "explanations": {"资讯": "正确。资讯指科技方面的信息，与“提供科技”搭配自然。", "调料": "语义：“科技”不能修饰调料，这句话指公司提供的是科技内容。", "感情": "搭配：“提供”后不能直接接“感情”，“科技感情”也不成词。", "河流": "语义：河流不是公司可以提供的科技内容，与“科技”不搭。"}, "sentence_index": 0, "correct_answer": "资讯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在饭店点了三道资讯。", "explanation": "这里应该用〈菜〉。点的是菜，资讯是消息，不能被点。"}, {"text": "这座山的资讯非常茂盛。", "explanation": "这里应该用〈树木〉。茂盛形容草木，资讯是消息，不能说茂盛。"}, {"text": "我在报纸上读到一座资讯。", "explanation": "这里应该用〈条〉或〈则〉。座用于山、楼房等大型固定物，资讯不能用“座”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资讯", "is_correct": true, "explanation": "正确。资讯指电影方面的消息，与“很多”和杂志内容相符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：杂志上刊登的是消息，蔬菜与“电影”不搭，不能作为杂志的内容。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是杂志能刊登的内容，与“电影”也不搭。"}, {"text": "油漆", "is_correct": false, "explanation": "语义：杂志刊登的是消息，油漆不是杂志的内容，“电影油漆”也不成立。"}], "explanations": {"资讯": "正确。资讯指电影方面的消息，与“很多”和杂志内容相符。", "蔬菜": "语义：杂志上刊登的是消息，蔬菜与“电影”不搭，不能作为杂志的内容。", "钥匙": "语义：钥匙不是杂志能刊登的内容，与“电影”也不搭。", "油漆": "语义：杂志刊登的是消息，油漆不是杂志的内容，“电影油漆”也不成立。"}, "sentence_index": 6, "correct_answer": "资讯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正在为项目筹集资讯。", "explanation": "这里应该用〈资金〉。筹集的是钱，资讯是消息，不能被筹集。"}, {"text": "她每周都要交一份资讯。", "explanation": "这里应该用〈报告〉。报告是要上交的书面文件，资讯是消息。"}, {"text": "我在手机上看到了一枚资讯。", "explanation": "这里应该用〈条〉。枚用于奖牌、硬币等小物件，资讯是消息，应用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在网站上看到一台最新资讯。", "corrected_sentence": "我在网站上看到一条最新资讯。", "error_description": "错误：“一台最新资讯”；正确：“一条最新资讯”。“台”用于机器，资讯是消息，应用“条”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把考试资讯们贴在门口。", "corrected_sentence": "老师把考试资讯贴在门口。", "error_description": "错误：“资讯们”；正确：“资讯”。“资讯”是不可数的名词，不能加复数词尾“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
