INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88619, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "坐标是用两个数告诉你一个点在什么地方。", "primary_collocate": null, "pronunciation": "zuò biāo", "ipa": "tswo˥˩ pjɑʊ˥", "syllable_count": 2, "sentences": [{"text": "地图上这个点的坐标是多少？", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在纸上写出这个点的坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么看坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把坐标发给朋友，他很快找到了。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个点的坐标是（3，5）。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机能告诉你现在的坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在图上写错了坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给我你的坐标，我去找你。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，我们学了坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长看着坐标，调整了方向。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐标系", "label": "复合"}, {"form": "坐标轴", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "用两个数表示一个点的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坐标", "is_correct": true, "explanation": "坐标指用两个数表示点的位置，正是地图上问“是多少”的对象。"}, {"text": "分数", "is_correct": false, "explanation": "语义：“分数”是考试或比赛的得分，不能用来指地图上某个点的位置。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：“芳名”是敬辞，用于询问别人的姓名，不适用于地图上的点。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”属于平面图形，点没有面积，“点的面积”不能这样搭配。"}], "explanations": {"坐标": "坐标指用两个数表示点的位置，正是地图上问“是多少”的对象。", "分数": "语义：“分数”是考试或比赛的得分，不能用来指地图上某个点的位置。", "芳名": "语域：“芳名”是敬辞，用于询问别人的姓名，不适用于地图上的点。", "面积": "搭配：“面积”属于平面图形，点没有面积，“点的面积”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "坐标"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的坐标是三十八岁。", "explanation": "这里应该用〈年龄〉。坐标指点的位置数值，说人的岁数要用“年龄”。"}, {"text": "他记下了一块坐标。", "explanation": "这里应该用〈组〉。坐标常以“组”计数，如“一组坐标”，不说“一块坐标”。"}, {"text": "这张票的坐标是十二排三号。", "explanation": "这里应该用〈座位〉。坐标表示点的位置数值，票上的座位要说“座位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐标", "is_correct": true, "explanation": "坐标是用数值表示位置的，“写错了坐标”指在图上写错了点的位置数值。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是人或物的重量，不能写在地图上，与“在图上写错了”的语境不符。"}, {"text": "车票", "is_correct": false, "explanation": "语义：“车票”是乘车凭证，不能写在地图上，与语境不符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物的岁数，不能写在图上，与语境不符。"}], "explanations": {"坐标": "坐标是用数值表示位置的，“写错了坐标”指在图上写错了点的位置数值。", "体重": "语义：“体重”是人或物的重量，不能写在地图上，与“在图上写错了”的语境不符。", "车票": "语义：“车票”是乘车凭证，不能写在地图上，与语境不符。", "年龄": "语义：“年龄”指人或生物的岁数，不能写在图上，与语境不符。"}, "sentence_index": 6, "correct_answer": "坐标"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把坐标写在信封上，寄给了朋友。", "explanation": "这里应该用〈地址〉。坐标是数值，写在信封上寄信要用“地址”。"}, {"text": "这栋楼的坐标是十二号。", "explanation": "这里应该用〈门牌号〉。楼的编号要说“门牌号”，坐标指点的位置数值。"}, {"text": "路口的坐标写着“向左”。", "explanation": "这里应该用〈路标〉。路口写着方向的是路标，不是坐标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给我看了一条坐标。", "corrected_sentence": "他给我看了一组坐标。", "error_description": "错误形式：“一条坐标”；正确形式：“一组坐标”。坐标通常以“组”计数，“条”用于河流、路线等长条状事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他算出了这个点的坐标们。", "corrected_sentence": "他算出了这个点的坐标。", "error_description": "错误形式：“坐标们”；正确形式：“坐标”。坐标是表示数值的名词，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
