INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88620, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "确定点在平面或空间中位置的一组数值。", "primary_collocate": null, "pronunciation": "zuò biāo", "ipa": "tswo˥˩ pjɑʊ˥", "syllable_count": 2, "sentences": [{"text": "平面上每个点都有自己的坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空间里的点需要三个坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用坐标表示飞机的位置。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写出点A的坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这组坐标指向山顶的小屋。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图软件会显示你所在的坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个点的坐标不同，位置就不同。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师记下了桥的坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在方格纸上找到了坐标。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星把坐标传回了地球。", "target_word": "坐标", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐标系", "label": "复合"}, {"form": "坐标轴", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "确定点在平面或空间中位置的一组数值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坐标", "is_correct": true, "explanation": "坐标指确定点位置的一组数值，平面上每个点都有这样一组数值。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”属于人的情绪，点没有心情，不能这样说。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”用于人或生物，点不能说有年龄，“点的年龄”不能这样搭配。"}, {"text": "学号", "is_correct": false, "explanation": "语义：“学号”是学生的编号，与平面上的点无关。"}], "explanations": {"坐标": "坐标指确定点位置的一组数值，平面上每个点都有这样一组数值。", "心情": "语义：“心情”属于人的情绪，点没有心情，不能这样说。", "年龄": "搭配：“年龄”用于人或生物，点不能说有年龄，“点的年龄”不能这样搭配。", "学号": "语义：“学号”是学生的编号，与平面上的点无关。"}, "sentence_index": 0, "correct_answer": "坐标"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张票的坐标是三十八元。", "explanation": "这里应该用〈票价〉。坐标指点的位置数值，票的价钱要说“票价”。"}, {"text": "他的坐标是二十岁。", "explanation": "这里应该用〈年龄〉。坐标指点的位置数值，说人的岁数要用“年龄”。"}, {"text": "他算出了一把坐标。", "explanation": "这里应该用〈组〉。坐标常以“组”计数，“一把”用于有柄的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐标", "is_correct": true, "explanation": "坐标是确定点位置的数值，坐标不同则位置不同，句意通顺。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，点没有重量，与“位置就不同”的逻辑不符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是买卖中的钱数，与点的位置无关。"}, {"text": "宽度", "is_correct": false, "explanation": "搭配：“宽度”属于面或线，点没有宽度，“点的宽度”不能这样搭配。"}], "explanations": {"坐标": "坐标是确定点位置的数值，坐标不同则位置不同，句意通顺。", "重量": "语义：“重量”指物体的轻重，点没有重量，与“位置就不同”的逻辑不符。", "价格": "语义：“价格”是买卖中的钱数，与点的位置无关。", "宽度": "搭配：“宽度”属于面或线，点没有宽度，“点的宽度”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "坐标"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的坐标是八十分。", "explanation": "这里应该用〈分数〉。坐标指点的位置数值，考试成绩要说“分数”。"}, {"text": "老师给学生打了一个坐标。", "explanation": "这里应该用〈分数〉。“打”通常接分数，坐标指点的位置数值，不能用来评分。"}, {"text": "这本书的坐标是五。", "explanation": "这里应该用〈页码〉。书中的页数要说“页码”，坐标指点的位置数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师要求我们写出每个点的坐标们。", "corrected_sentence": "老师要求我们写出每个点的坐标。", "error_description": "错误形式：“坐标们”；正确形式：“坐标”。坐标是表示数值的名词，不能加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "探测器把坐标的传回了基地。", "corrected_sentence": "探测器把坐标传回了基地。", "error_description": "错误形式：“坐标的传回”；正确形式：“坐标传回”。“把”字句中，宾语“坐标”后面直接接动词，不能在宾语后加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88621, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进攻", "is_correct": true, "explanation": "进攻：与“防守”意思相对，指主动攻入对方一方。"}, {"text": "思考", "is_correct": false, "explanation": "思考：动词，但与“防守”没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息：动词，与“防守”的意思没有相对关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：动词，与“防守”的意思没有相对关系。"}], "correct_answer": "进攻", "explanations": {"进攻": "进攻：与“防守”意思相对，指主动攻入对方一方。", "思考": "思考：动词，但与“防守”没有反义关系。", "休息": "休息：动词，与“防守”的意思没有相对关系。", "唱歌": "唱歌：动词，与“防守”的意思没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88621, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进攻", "is_correct": true, "explanation": "进攻：与“防守”意思相对，指主动攻入对方一方。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：动词，与“防守”的意思没有相对关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：动词，与“防守”的意思没有相对关系。"}, {"text": "学习", "is_correct": false, "explanation": "学习：动词，与“防守”的意思没有相对关系。"}], "correct_answer": "进攻", "explanations": {"进攻": "进攻：与“防守”意思相对，指主动攻入对方一方。", "旅行": "旅行：动词，与“防守”的意思没有相对关系。", "睡觉": "睡觉：动词，与“防守”的意思没有相对关系。", "学习": "学习：动词，与“防守”的意思没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88621, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防守是保护自己这边，不让对方进来。", "primary_collocate": null, "pronunciation": "fáng shǒu", "ipa": "faŋ˧˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们队的后卫很会防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始后，他们一直在防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他防守得很好，对方进不了球。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，防守和进攻一样重要。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先防守，再找机会进攻。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在球场上负责防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方来了三个人，我们很难防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队只会防守，不会进攻。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把对方的前锋防守得很紧。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们防守了一整场，最后还是输了。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防守了", "label": "体标"}, {"form": "防守着", "label": "体标"}, {"form": "防守过", "label": "体标"}, {"form": "防守反击", "label": "复合"}], "register": "中性", "sense_fingerprint": "保护自己这一方，不让对方进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88621, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防守", "is_correct": true, "explanation": "防守：保护自己这一方、不让对方进来，即本题的目标词。"}, {"text": "放手", "is_correct": false, "explanation": "放手（fàng，第四声）与 fáng（第二声）声调不同，意思是松开手、不再管。"}, {"text": "防水", "is_correct": false, "explanation": "防水（shuǐ，第三声）与 shǒu（第三声）韵母不同，ui 与 ou 相混，意思是不让水渗入。"}, {"text": "防暑", "is_correct": false, "explanation": "防暑（shǔ，第三声）与 shǒu（第三声）韵母不同，u 与 ou 相混，意思是预防中暑。"}], "explanations": {"防守": "防守：保护自己这一方、不让对方进来，即本题的目标词。", "放手": "放手（fàng，第四声）与 fáng（第二声）声调不同，意思是松开手、不再管。", "防水": "防水（shuǐ，第三声）与 shǒu（第三声）韵母不同，ui 与 ou 相混，意思是不让水渗入。", "防暑": "防暑（shǔ，第三声）与 shǒu（第三声）韵母不同，u 与 ou 相混，意思是预防中暑。"}, "sentence_index": null, "correct_answer": "防守"}, "level_3": {"options": [{"text": "防守", "is_correct": true, "explanation": "防守：保护本队球门，与“后卫很会”搭配自然。"}, {"text": "防线", "is_correct": false, "explanation": "词性：“防线”是名词，“很会”后面要接动词，不能说“很会防线”。"}, {"text": "球门", "is_correct": false, "explanation": "词性：“球门”是名词，不能放在“很会”后面。"}, {"text": "足球", "is_correct": false, "explanation": "词性：“足球”是名词，“很会足球”不成话，应说“很会踢足球”。"}], "explanations": {"防守": "防守：保护本队球门，与“后卫很会”搭配自然。", "防线": "词性：“防线”是名词，“很会”后面要接动词，不能说“很会防线”。", "球门": "词性：“球门”是名词，不能放在“很会”后面。", "足球": "词性：“足球”是名词，“很会足球”不成话，应说“很会踢足球”。"}, "sentence_index": 0, "correct_answer": "防守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前锋一脚防守，球进了网。", "explanation": "这里应该用〈射门〉。防守是阻止对方进攻，前锋射门得分不能说“防守”。"}, {"text": "他把球防守给了队友。", "explanation": "这里应该用〈传〉。防守是阻止对方，不能把球防守给队友。"}, {"text": "对方失误后，我们立刻防守，很快进了一球。", "explanation": "这里应该用〈反击〉。防守是阻止对方进攻，抢到球后快速进攻得分要说“反击”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防守", "is_correct": true, "explanation": "防守：阻止对方进攻，与“我们很难”搭配自然。"}, {"text": "抬", "is_correct": false, "explanation": "配价：“抬”需要带宾语（抬东西），这里没有宾语，句意不完整。"}, {"text": "烧饭", "is_correct": false, "explanation": "语义：烧饭与“对方来了三个人”的情境不相关，句意不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：对方来袭时“跳舞”不合情境，句意不通。"}], "explanations": {"防守": "防守：阻止对方进攻，与“我们很难”搭配自然。", "抬": "配价：“抬”需要带宾语（抬东西），这里没有宾语，句意不完整。", "烧饭": "语义：烧饭与“对方来了三个人”的情境不相关，句意不通。", "跳舞": "语义：对方来袭时“跳舞”不合情境，句意不通。"}, "sentence_index": 6, "correct_answer": "防守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他防守很准，连续得了两个三分。", "explanation": "这里应该用〈投篮〉。防守是阻止对方进攻，得分要说“投篮”，不能说“防守”。"}, {"text": "他在第八十分钟防守了一球，帮球队扳平比分。", "explanation": "这里应该用〈进球〉。防守是阻止对方，帮球队扳平比分要说“进球”。"}, {"text": "他防守推进，一直冲到对方禁区。", "explanation": "这里应该用〈带球〉。防守是阻止对方进攻，带球推进冲向对方禁区要说“带球”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "后卫防守地很稳，对方很难突破。", "corrected_sentence": "后卫防守得很稳，对方很难突破。", "error_description": "“防守得很稳”中，“得”引出补语“很稳”，此处误用结构助词“地”（用于状语）；应说“防守得很稳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在禁区里防守对方的前锋着。", "corrected_sentence": "他们在禁区里防守对方的前锋。", "error_description": "句末的“着”位置不当：“着”应紧跟动词表示持续（如“防守着对方的前锋”），不能放在宾语之后的句尾；应去掉句末“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
