INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88622, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防备并守卫，抵御对方进攻。", "primary_collocate": null, "pronunciation": "fáng shǒu", "ipa": "faŋ˧˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "士兵们在城墙上防守着。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人从北边来了，我们要认真防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把城门关上，开始防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城防守得很好，敌人没能进来。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军让一半的人留下防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山口很小，几百人就能防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边防守的人太少，敌人很容易过来。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们防守了三个月，终于等到了帮手。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，他一个人在山上防守。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要有足够的人来防守边界。", "target_word": "防守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防守了", "label": "体标"}, {"form": "防守着", "label": "体标"}, {"form": "防守过", "label": "体标"}, {"form": "防守反击", "label": "复合"}], "register": "中性", "sense_fingerprint": "防备并守卫，抵御敌人进攻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88622, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防守", "is_correct": true, "explanation": "防守：防备并守卫，抵御敌人进攻，即本题的目标词。"}, {"text": "放手", "is_correct": false, "explanation": "放手（fàng，第四声）与 fáng（第二声）声调不同，意思是松开手、不再管。"}, {"text": "防水", "is_correct": false, "explanation": "防水（shuǐ，第三声）与 shǒu（第三声）韵母不同，ui 与 ou 相混，意思是不让水渗入。"}, {"text": "防暑", "is_correct": false, "explanation": "防暑（shǔ，第三声）与 shǒu（第三声）韵母不同，u 与 ou 相混，意思是预防中暑。"}], "explanations": {"防守": "防守：防备并守卫，抵御敌人进攻，即本题的目标词。", "放手": "放手（fàng，第四声）与 fáng（第二声）声调不同，意思是松开手、不再管。", "防水": "防水（shuǐ，第三声）与 shǒu（第三声）韵母不同，ui 与 ou 相混，意思是不让水渗入。", "防暑": "防暑（shǔ，第三声）与 shǒu（第三声）韵母不同，u 与 ou 相混，意思是预防中暑。"}, "sentence_index": null, "correct_answer": "防守"}, "level_3": {"options": [{"text": "防守", "is_correct": true, "explanation": "防守：守住城墙、抵御敌人，与“城墙上”搭配自然。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：士兵在城墙上守卫，“游泳”与情境不符，句意不通。"}, {"text": "讲课", "is_correct": false, "explanation": "语义：“讲课”与城墙上的守卫无关，句意不通。"}, {"text": "城门", "is_correct": false, "explanation": "词性：“城门”是名词，不能带“着”作谓语，句子不通。"}], "explanations": {"防守": "防守：守住城墙、抵御敌人，与“城墙上”搭配自然。", "游泳": "语义：士兵在城墙上守卫，“游泳”与情境不符，句意不通。", "讲课": "语义：“讲课”与城墙上的守卫无关，句意不通。", "城门": "词性：“城门”是名词，不能带“着”作谓语，句子不通。"}, "sentence_index": 0, "correct_answer": "防守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们防守敌人的城池，三天后便攻入了城中。", "explanation": "这里应该用〈攻打〉。防守是守卫己方，攻打敌方城池不能说“防守”。"}, {"text": "我军防守敌人的主力，同时突破了它的防线。", "explanation": "这里应该用〈进攻〉。防守是守卫己方，突破敌方防线属于进攻，不能说“防守”。"}, {"text": "他们防守敌军的营地，一夜之间就拿下了它。", "explanation": "这里应该用〈攻占〉。防守指守卫己方的地方，一夜拿下敌方营地要说“攻占”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防守", "is_correct": true, "explanation": "防守：守卫要地，与“河边”“的人”搭配自然。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：河边唱歌的人少，与“敌人很容易过来”没有因果关系，句意不通。"}, {"text": "烧饭", "is_correct": false, "explanation": "语义：河边烧饭的人少与敌人过来无关，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：河边睡觉的人少与敌人容易过来没有关系，句意不通。"}], "explanations": {"防守": "防守：守卫要地，与“河边”“的人”搭配自然。", "唱歌": "语义：河边唱歌的人少，与“敌人很容易过来”没有因果关系，句意不通。", "烧饭": "语义：河边烧饭的人少与敌人过来无关，句意不通。", "睡觉": "语义：河边睡觉的人少与敌人容易过来没有关系，句意不通。"}, "sentence_index": 6, "correct_answer": "防守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们防守对方的营寨，三天后便发动了围城。", "explanation": "这里应该用〈围攻〉。防守是守卫己方，包围对方营寨要说“围攻”，不能说“防守”。"}, {"text": "他带兵防守河对岸的敌人，然后渡河夺取了粮仓。", "explanation": "这里应该用〈突袭〉。防守是守卫己方阵地，渡河夺取敌方粮仓要说“突袭”。"}, {"text": "我们防守对方的城墙，最后一鼓作气夺下了城池。", "explanation": "这里应该用〈猛攻〉。防守是守卫己方，一鼓作气夺下敌城要说“猛攻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们防守地很严，敌人进不来。", "corrected_sentence": "士兵们防守得很严，敌人进不来。", "error_description": "“防守得很严”中，“得”引出补语“很严”，此处误用结构助词“地”（用于状语）；应说“防守得很严”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "将军带着人马在山口着防守。", "corrected_sentence": "将军带着人马在山口防守。", "error_description": "“着”应紧跟动词之后表示持续，不能放在动词“防守”前面；此处应去掉“着”，说“在山口防守”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
