INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在道路的表面上。", "primary_collocate": null, "pronunciation": "lù shang", "ipa": "lu⁵¹ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "路上有一只小狗，车都停下来了。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下雨，路上有很多水。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上没有人，也没有车。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的雪很厚，走起来很慢。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在路上，下车看了看。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有一块大石头，挡住了车。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里路上很黑，我们打开了灯。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上到处是落叶，很漂亮。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的车越来越多。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在路上玩球，很危险。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "道路的表面之上（处所）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae3ffb7-db8b-4484-bd04-e2dff1dba072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌上", "is_correct": false, "explanation": "语义：车不会停在桌子上，“车都停下来了”与“桌上”的场所矛盾。"}, {"text": "路上", "is_correct": true, "explanation": "正确：“路上”指道路的表面，与“车都停下来了”相符。"}, {"text": "房间里", "is_correct": false, "explanation": "搭配：“车停下来”需要道路这样的场所，“房间里”不能说车停在里面。"}, {"text": "水里", "is_correct": false, "explanation": "语义：小狗在水里，车停下来，这样的场景与句子语境不符。"}], "explanations": {"桌上": "语义：车不会停在桌子上，“车都停下来了”与“桌上”的场所矛盾。", "路上": "正确：“路上”指道路的表面，与“车都停下来了”相符。", "房间里": "搭配：“车停下来”需要道路这样的场所，“房间里”不能说车停在里面。", "水里": "语义：小狗在水里，车停下来，这样的场景与句子语境不符。"}, "sentence_index": 0, "correct_answer": "路上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在路上的床上睡了三天。", "explanation": "“路上”指道路的表面，不能与“床上”搭配表示室内的位置，这里应去掉“路上”，直接说“在床上睡了三天”。"}, {"text": "我们在路上的办公室里开会。", "explanation": "“路上”指道路的表面，不能用来表示办公室里的位置，这里应直接说“在办公室里开会”。"}, {"text": "这块石头在路上的房间里。", "explanation": "“路上”指道路的表面，不能与“房间里”搭配表示室内的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阳光下", "is_correct": false, "explanation": "语义：“夜里”与“阳光下”矛盾，夜里不会有阳光。"}, {"text": "路上", "is_correct": true, "explanation": "正确：“路上”指道路的表面，夜里道路很黑，与“很黑”相符。"}, {"text": "路灯下", "is_correct": false, "explanation": "语义：路灯下是明亮的，与“很黑”矛盾。"}, {"text": "火光里", "is_correct": false, "explanation": "搭配：“火光”是明亮的，“火光里很黑”搭配不当。"}], "explanations": {"阳光下": "语义：“夜里”与“阳光下”矛盾，夜里不会有阳光。", "路上": "正确：“路上”指道路的表面，夜里道路很黑，与“很黑”相符。", "路灯下": "语义：路灯下是明亮的，与“很黑”矛盾。", "火光里": "搭配：“火光”是明亮的，“火光里很黑”搭配不当。"}, "sentence_index": 6, "correct_answer": "路上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路上的抽屉里找到了钥匙。", "explanation": "“路上”指道路的表面，不能用来指抽屉的位置。"}, {"text": "我的书放在路上的书架上。", "explanation": "“路上”指道路的表面，不能与“书架上”搭配表示室内的位置。"}, {"text": "这把椅子在路上的厨房里放着。", "explanation": "“路上”指道路的表面，不能与“厨房里”搭配表示室内的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一辆车停在路上里，堵住了路口。", "corrected_sentence": "一辆车停在路上，堵住了路口。", "error_description": "错误：“路上”后面又加了“里”，形成重复的方位词。应去掉“里”，改为“停在路上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个孩子在路上里踢球。", "corrected_sentence": "几个孩子在路上踢球。", "error_description": "错误：“路上”后面又加了“里”，形成重复的方位词。应去掉“里”，改为“在路上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
