INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在去某地或返回的途中。", "primary_collocate": null, "pronunciation": "lù shang", "ipa": "lu⁵¹ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "我在路上买了一杯咖啡。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上小心，到家给我打电话。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路上遇到了老同学。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去机场的路上，我一直在看书。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在路上吃了午饭。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在回家的路上接到了电话。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，所以我来晚了。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在路上给我发了一条消息。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在路上聊了很多。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在路上走了两个小时。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "行进途中（过程）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae3ffb7-db8b-4484-bd04-e2dff1dba072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书里", "is_correct": false, "explanation": "语义：书里不能买咖啡，“买”的场所不能是书。"}, {"text": "路上", "is_correct": true, "explanation": "正确：“路上”表示行进途中，“我在路上买了一杯咖啡”自然通顺。"}, {"text": "黑板上", "is_correct": false, "explanation": "搭配：“买”需要商店、街边等场所，黑板上不能买东西。"}, {"text": "天上", "is_correct": false, "explanation": "语义：天上不能买咖啡，句子前后矛盾。"}], "explanations": {"书里": "语义：书里不能买咖啡，“买”的场所不能是书。", "路上": "正确：“路上”表示行进途中，“我在路上买了一杯咖啡”自然通顺。", "黑板上": "搭配：“买”需要商店、街边等场所，黑板上不能买东西。", "天上": "语义：天上不能买咖啡，句子前后矛盾。"}, "sentence_index": 0, "correct_answer": "路上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在路上的厨房里做了晚饭。", "explanation": "“路上”表示行进途中，不能与“厨房里”搭配表示室内的位置，这里应直接说“在厨房里做了晚饭”。"}, {"text": "我的钥匙放在路上的卧室里。", "explanation": "“路上”表示行进途中，不能用来指卧室里的位置，这里应去掉“路上”，直接说“放在卧室里”。"}, {"text": "工人们在路上的车间里工作。", "explanation": "“路上”不能用来指车间里的位置，这里应直接说“在车间里工作”，不用“路上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室里", "is_correct": false, "explanation": "语义：“堵车”发生在教室里不合常理，前后矛盾。"}, {"text": "路上", "is_correct": true, "explanation": "正确：“路上”表示行进途中，“路上堵车”自然通顺，解释了“来晚了”。"}, {"text": "书里", "is_correct": false, "explanation": "搭配：“堵车”的场所应是道路，“书里”不能堵车。"}, {"text": "厨房里", "is_correct": false, "explanation": "语义：厨房里不会堵车，这句的因果关系不成立。"}], "explanations": {"教室里": "语义：“堵车”发生在教室里不合常理，前后矛盾。", "路上": "正确：“路上”表示行进途中，“路上堵车”自然通顺，解释了“来晚了”。", "书里": "搭配：“堵车”的场所应是道路，“书里”不能堵车。", "厨房里": "语义：厨房里不会堵车，这句的因果关系不成立。"}, "sentence_index": 6, "correct_answer": "路上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在路上的教室里学习了两个小时。", "explanation": "“路上”表示行进途中，不能用来指教室的位置，这里的组合不符合本义项。"}, {"text": "他在路上的餐厅里吃了午饭。", "explanation": "“路上”表示行进途中，不能与“餐厅里”搭配表示室内的位置。"}, {"text": "她在路上的家里睡了一觉。", "explanation": "“路上”表示行进途中，不能用来指家里的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去火车站的路上里，我们遇到了一场大雨。", "corrected_sentence": "去火车站的路上，我们遇到了一场大雨。", "error_description": "错误：“路上”后面又加了“里”，形成重复的方位词。应去掉“里”，改为“去火车站的路上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在去学校的路上里，他听了一首新歌。", "corrected_sentence": "在去学校的路上，他听了一首新歌。", "error_description": "错误：“路上”后面又加了“里”，形成重复的方位词。应去掉“里”，改为“路上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88627, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散", "is_correct": true, "explanation": "正确。散指离开聚集的地方，与「集」的人群聚集义相反。"}, {"text": "继续", "is_correct": false, "explanation": "「继续」与「集」的任何义项都没有反义关系。"}, {"text": "漂洗", "is_correct": false, "explanation": "「漂洗」指用水冲洗，与「集」的任何义项都无反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "「研究」指探讨问题，与「人走到一起」无反义关系。"}], "correct_answer": "散", "explanations": {"散": "正确。散指离开聚集的地方，与「集」的人群聚集义相反。", "继续": "「继续」与「集」的任何义项都没有反义关系。", "漂洗": "「漂洗」指用水冲洗，与「集」的任何义项都无反义关系。", "研究": "「研究」指探讨问题，与「人走到一起」无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88627, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散", "is_correct": true, "explanation": "正确。散指离开聚集的地方，与「集」的人群聚集义相反。"}, {"text": "修理", "is_correct": false, "explanation": "「修理」指修复损坏的东西，与「集」的任何义项都无反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "「保存」指留存东西，与「集」的任何义项都无反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "「观察」指仔细看，与「人走到一起」无反义关系。"}], "correct_answer": "散", "explanations": {"散": "正确。散指离开聚集的地方，与「集」的人群聚集义相反。", "修理": "「修理」指修复损坏的东西，与「集」的任何义项都无反义关系。", "保存": "「保存」指留存东西，与「集」的任何义项都无反义关系。", "观察": "「观察」指仔细看，与「人走到一起」无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88627, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "集是很多人或东西走到一起,放在一起。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "下课后，同学们都集在操场上。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天一黑，大家就集在村口。", "target_word": "集", "complexity_tier": "T3", "furigana": "tiān yì hēi, dàjiā jiù jí zài cūnkǒu.", "sentence_source": "generated"}, {"text": "人们从各地都集在这个小城里。", "target_word": "集", "complexity_tier": "T3", "furigana": "rénmen cóng gèdì dōu jí zài zhège xiǎochéng lǐ.", "sentence_source": "generated"}, {"text": "请大家明天早上八点集在门口。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很快集在老师身边。", "target_word": "集", "complexity_tier": "T3", "furigana": "háizimen hěn kuài jí zài lǎoshī shēnbiān.", "sentence_source": "generated"}, {"text": "车站前集着很多等车的人。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一下雨，路上的积水就集在低处。", "target_word": "集", "complexity_tier": "T3", "furigana": "yí xiàyǔ, lùshàng de jīshuǐ jiù jí zài dīchù.", "sentence_source": "generated"}, {"text": "一听见音乐，大家都集在广场上了。", "target_word": "集", "complexity_tier": "T3", "furigana": "yì tīngjiàn yīnyuè, dàjiā dōu jí zài guǎngchǎng shàng le.", "sentence_source": "generated"}, {"text": "参加比赛的人已经集在一起了。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站前集了几百个人。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集了", "label": "体标"}, {"form": "集着", "label": "体标"}], "register": "中性", "sense_fingerprint": "很多人走到同一个地方聚在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88627, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集", "is_correct": true, "explanation": "正确答案：集 jí（第二声），表示很多人走到一起。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压、拥挤。"}, {"text": "齐", "is_correct": false, "explanation": "qí 与 jí 声母不同（q 与 j），声调相同，意思是整齐。"}], "explanations": {"集": "正确答案：集 jí（第二声），表示很多人走到一起。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "寄": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压、拥挤。", "齐": "qí 与 jí 声母不同（q 与 j），声调相同，意思是整齐。"}, "sentence_index": null, "correct_answer": "集"}, "level_3": {"options": [{"text": "集", "is_correct": true, "explanation": "正确。集在操场上表示同学们走到一起、聚在一处。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：「挂」指悬挂物品，不能说「同学们都挂在操场上」。"}, {"text": "摔", "is_correct": false, "explanation": "语义：「摔」表示跌倒，与「同学们都……」的聚集义不合。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：「扔」的对象多为物品，不能说「同学们都扔在操场上」。"}], "explanations": {"集": "正确。集在操场上表示同学们走到一起、聚在一处。", "挂": "搭配：「挂」指悬挂物品，不能说「同学们都挂在操场上」。", "摔": "语义：「摔」表示跌倒，与「同学们都……」的聚集义不合。", "扔": "搭配：「扔」的对象多为物品，不能说「同学们都扔在操场上」。"}, "sentence_index": 0, "correct_answer": "集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一列火车八点集在车站。", "explanation": "这里应该用〈到达〉。集表示很多人或东西聚到一起，一列火车单独抵达，不能说「集在车站」。"}, {"text": "妈妈集了一件毛衣给弟弟。", "explanation": "这里应该用〈织〉。集表示聚到一起，织毛衣要用「织」，不能说「集毛衣」。"}, {"text": "把一本书集在桌上。", "explanation": "这里应该用〈放〉。集要求多个人或东西聚在一起，只放一本书时用「放」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88627, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "集", "is_correct": true, "explanation": "正确答案：集 jí（第二声），表示很多人走到一起。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是敲打。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}, {"text": "其", "is_correct": false, "explanation": "qí 与 jí 声母不同（q 与 j），声调相同，意思是其他。"}], "explanations": {"集": "正确答案：集 jí（第二声），表示很多人走到一起。", "击": "jī（第一声）与 jí（第二声）声调不同，意思是敲打。", "季": "jì（第四声）与 jí（第二声）声调不同，意思是季节。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。", "其": "qí 与 jí 声母不同（q 与 j），声调相同，意思是其他。"}, "sentence_index": null, "correct_answer": "集"}, "level_3": {"options": [{"text": "集", "is_correct": true, "explanation": "正确。集在低处表示积水向低处聚合到一起。"}, {"text": "升", "is_correct": false, "explanation": "语义：积水会向低处流聚，不会「升」到高处，与「低处」的语境矛盾。"}, {"text": "飞", "is_correct": false, "explanation": "语义：水不会「飞」，与积水自然流动的语境不合。"}, {"text": "举", "is_correct": false, "explanation": "搭配：「举」的主体需能用手或物体抬起，积水不能「举」在低处。"}], "explanations": {"集": "正确。集在低处表示积水向低处聚合到一起。", "升": "语义：积水会向低处流聚，不会「升」到高处，与「低处」的语境矛盾。", "飞": "语义：水不会「飞」，与积水自然流动的语境不合。", "举": "搭配：「举」的主体需能用手或物体抬起，积水不能「举」在低处。"}, "sentence_index": 6, "correct_answer": "集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一个人集在门口等妈妈。", "explanation": "这里应该用〈站〉。集要求很多人聚到一起，一个人不能说「集」。"}, {"text": "爸爸集了那台旧洗衣机。", "explanation": "这里应该用〈修〉。集表示聚到一起，修理坏了的机器要用「修」，不能说「集机器」。"}, {"text": "他集了一个包裹回家。", "explanation": "这里应该用〈拿〉。集要求很多人或东西聚到一起，单个包裹不能说「集」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们都集了在教室门口。", "corrected_sentence": "同学们都集在教室门口。", "error_description": "「了」位置错误：「集」后不能直接加「了」再接「在教室门口」。应说「同学们都集在教室门口」，不在「集」后加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
