INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88628, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚在一起;聚合。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "大家的钱集在一起，就能买房子。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几张旧照片集在一本书里。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小水珠集在一起，就变成了小河。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把大家的想法集在一起，办法就多了。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些材料都集在一个文件夹里。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把力量集在一起，一定能成功。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所有的信都集在一个盒子里。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星星点点的光集在一起，照亮了山路。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把朋友们送的小礼物集在一起放好。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "零钱集在一起，也是一笔钱。", "target_word": "集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集了", "label": "体标"}, {"form": "集过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把分散的钱、东西、想法聚合到一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 点点 (Zipf 3.71), 照亮 (Zipf 3.66), 山路 (Zipf 3.75)']::text[], '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88628, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集", "is_correct": true, "explanation": "正确答案：集 jí（第二声），表示聚在一起。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压、拥挤。"}, {"text": "齐", "is_correct": false, "explanation": "qí 与 jí 声母不同（q 与 j），声调相同，意思是整齐。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记住。"}], "explanations": {"集": "正确答案：集 jí（第二声），表示聚在一起。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压、拥挤。", "齐": "qí 与 jí 声母不同（q 与 j），声调相同，意思是整齐。", "记": "jì（第四声）与 jí（第二声）声调不同，意思是记住。"}, "sentence_index": null, "correct_answer": "集"}, "level_3": {"options": [{"text": "集", "is_correct": true, "explanation": "正确。集在一起与「大家的钱」相合，表示钱聚合到一处，能凑够买房子的钱。"}, {"text": "分", "is_correct": false, "explanation": "语义：「分」是分开，与「在一起」正相反，句意自相矛盾。"}, {"text": "散", "is_correct": false, "explanation": "语义：「散」是分散，与「在一起」相抵触，不能说钱散在一起还能买房。"}, {"text": "花", "is_correct": false, "explanation": "搭配：「花」的对象是钱的用途，不能说「钱花在一起」。"}], "explanations": {"集": "正确。集在一起与「大家的钱」相合，表示钱聚合到一处，能凑够买房子的钱。", "分": "语义：「分」是分开，与「在一起」正相反，句意自相矛盾。", "散": "语义：「散」是分散，与「在一起」相抵触，不能说钱散在一起还能买房。", "花": "搭配：「花」的对象是钱的用途，不能说「钱花在一起」。"}, "sentence_index": 0, "correct_answer": "集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察集了现场的一根头发，送去化验了。", "explanation": "这里应该用〈取〉。集要求很多东西聚到一起，单独一根头发要用「取」，不能说「集」。"}, {"text": "他把一个苹果集在碗里。", "explanation": "这里应该用〈放〉。集要求很多东西聚到一起，只有一个苹果时用「放」。"}, {"text": "妈妈集了一桌好菜招待客人。", "explanation": "这里应该用〈准备〉。集表示聚到一起，不表示备菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88628, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "集", "is_correct": true, "explanation": "正确答案：集 jí（第二声），表示聚在一起。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是敲打。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}], "explanations": {"集": "正确答案：集 jí（第二声），表示聚在一起。", "击": "jī（第一声）与 jí（第二声）声调不同，意思是敲打。", "季": "jì（第四声）与 jí（第二声）声调不同，意思是季节。", "寄": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}, "sentence_index": null, "correct_answer": "集"}, "level_3": {"options": [{"text": "集", "is_correct": true, "explanation": "正确。集在一个盒子里表示把所有的信聚到一处。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：「挂」一般指把物品悬挂起来，不能说「挂在盒子里」。"}, {"text": "拆", "is_correct": false, "explanation": "语义：「拆」是拆开，与「都……在一个盒子里」的聚合义相反。"}, {"text": "送", "is_correct": false, "explanation": "配价：「送」需要「送给＋对象」的结构，不能说「送在一个盒子里」。"}], "explanations": {"集": "正确。集在一个盒子里表示把所有的信聚到一处。", "挂": "搭配：「挂」一般指把物品悬挂起来，不能说「挂在盒子里」。", "拆": "语义：「拆」是拆开，与「都……在一个盒子里」的聚合义相反。", "送": "配价：「送」需要「送给＋对象」的结构，不能说「送在一个盒子里」。"}, "sentence_index": 6, "correct_answer": "集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工作中集了很多经验。", "explanation": "这里应该用〈积累〉。集指聚到一起，经验要逐渐积累，不说「集经验」。"}, {"text": "他集了一扇破门。", "explanation": "这里应该用〈修〉。集表示聚到一起，修补门窗要用「修」。"}, {"text": "奶奶集了一锅粥给大家喝。", "explanation": "这里应该用〈煮〉。集表示聚到一起，不表示烹煮食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们把零花钱集下来，买了一个新足球。", "corrected_sentence": "同学们把零花钱集起来，买了一个新足球。", "error_description": "补语错误：「集」后应接「起来」，说成「集下来」不成词。正确说法是「把……集起来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧邮票集起在抽屉里了。", "corrected_sentence": "他把旧邮票集在抽屉里了。", "error_description": "错误形式：「集起在」；正确形式：「集在」。补语「起」不能直接与「在」连用（应说「集起来」或「集在」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
