INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "穿过；通过（透明或有空隙的物体）。", "primary_collocate": null, "pronunciation": "tòu guò", "ipa": "tʰou˥˩ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "太阳透过云层照下来。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我透过眼镜看黑板。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光透过窗纸照了出来。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子透过栏杆往外看。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水透过屋顶的洞滴下来。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她透过镜头看着我笑。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风透过墙上的小洞吹进来。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们透过玻璃墙看到里面的人。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他透过帐篷的缝看星星。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光透过树叶，在地上留下很多小点。", "target_word": "透过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "透过", "label": "原形"}, {"form": "透过了", "label": "体标"}], "register": "中性", "sense_fingerprint": "穿过透明或有空隙的物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚践踏，太阳不能踩云层。"}, {"text": "透过", "is_correct": true, "explanation": "“透过”表示光线穿过云层，与“太阳……照下来”的语境相合。"}, {"text": "扛", "is_correct": false, "explanation": "语义：“扛”是用肩承担重物，与光线穿过云层不符。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带宾语“云层”。"}], "explanations": {"踩": "语义：“踩”是用脚践踏，太阳不能踩云层。", "透过": "“透过”表示光线穿过云层，与“太阳……照下来”的语境相合。", "扛": "语义：“扛”是用肩承担重物，与光线穿过云层不符。", "跑": "配价：“跑”是不及物动词，不能带宾语“云层”。"}, "sentence_index": 0, "correct_answer": "透过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小船透过河面驶向对岸。", "explanation": "这里应该用〈驶过〉。透过指光线、视线穿过透明或有缝隙的物体，船在水面行进要用〈驶过〉。"}, {"text": "我透过大雨跑回了家。", "explanation": "这里应该用〈冒着〉。透过指光线、视线穿过透明或有空隙的物体，在大雨中行走要用〈冒着〉。"}, {"text": "他透过河水游到了对岸。", "explanation": "这里应该用〈游过〉。透过指光线、视线穿过透明或有空隙的物体，人在水中游动要用〈游过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能以“小洞”作宾语。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”要求有口的动作者，风不能咬墙。"}, {"text": "透过", "is_correct": true, "explanation": "“透过”表示风穿过墙上的小洞，与“吹进来”的语境相合。"}, {"text": "跪", "is_correct": false, "explanation": "配价：“跪”是不及物动词，不能带宾语“墙上的小洞”。"}], "explanations": {"唱": "搭配：“唱”不能以“小洞”作宾语。", "咬": "语义：“咬”要求有口的动作者，风不能咬墙。", "透过": "“透过”表示风穿过墙上的小洞，与“吹进来”的语境相合。", "跪": "配价：“跪”是不及物动词，不能带宾语“墙上的小洞”。"}, "sentence_index": 6, "correct_answer": "透过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洪水透过了屋子。", "explanation": "这里应该用〈涌进〉。透过指光线或视线穿过透明或有空隙的物体，液体大量流入房屋要用〈涌进〉。"}, {"text": "孩子透过栏杆跳了过去。", "explanation": "这里应该用〈跳过〉。透过只用于光线、视线穿过透明或有空隙的物体，人跳过栏杆要用〈跳过〉。"}, {"text": "工人透过了新房子。", "explanation": "这里应该用〈搬进〉。透过表示光线或视线穿过东西，人搬入房屋要用〈搬进〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳光透过了树叶了，洒在窗台上。", "corrected_sentence": "阳光透过了树叶，洒在窗台上。", "error_description": "“了”只需用一次，紧跟“透过”即可；“树叶”后面又加“了”属于重复，应去掉多余的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "清晨的阳光透过着窗户照进来。", "corrected_sentence": "清晨的阳光透过窗户照进来。", "error_description": "错误：“透过着”；正确：“透过”。“透过”在这里表示光线穿过窗户，后面直接带宾语，再接“照进来”，不用“着”，应去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88631, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上传", "is_correct": true, "explanation": "正确：“上传”与“下载”是反义词，下载是把网上的东西拿到自己的设备，上传是把自己设备上的东西送到网上。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是日常动作，与“下载”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是走路休息，与“下载”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”是绘画活动，与“下载”没有反义关系。"}], "correct_answer": "上传", "explanations": {"上传": "正确：“上传”与“下载”是反义词，下载是把网上的东西拿到自己的设备，上传是把自己设备上的东西送到网上。", "睡觉": "“睡觉”是日常动作，与“下载”没有反义关系。", "散步": "“散步”是走路休息，与“下载”没有反义关系。", "画画": "“画画”是绘画活动，与“下载”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
