INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指过去或将来的某个时间。", "primary_collocate": null, "pronunciation": "nà shí", "ipa": "na˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "明年春天我毕业，那时我想去旅行。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月我就回国了，那时再见面吧。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等你长大，那时你会明白的。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时的学校没有电脑。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五年以后，那时我可能住在上海。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时他刚到北京，一个朋友也没有。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们三年后上大学，那时家里会很安静。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到了那时就知道了。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们第一次见面是在冬天，那时下着雪。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时的我不爱读书。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那時", "label": "繁体"}, {"form": "那时候", "label": "复合"}], "register": "中性", "sense_fingerprint": "那时：指前文提到的过去或将来的某个时间点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4833d5f1-cf75-4236-a0b9-bf3c5753a5f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那时", "is_correct": true, "explanation": "正确：“那时”指明年以后的某个时候，与“明年春天我毕业”的将来语境相合。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指已经过去的一年，与“明年春天我毕业”的将来语境冲突。"}, {"text": "上个星期", "is_correct": false, "explanation": "搭配：“上个星期”指已经过去的一周，不能与“明年春天我毕业”并列作时间状语。"}, {"text": "小时候", "is_correct": false, "explanation": "语义：“小时候”指童年，与“明年春天我毕业”所说的未来计划冲突。"}], "explanations": {"那时": "正确：“那时”指明年以后的某个时候，与“明年春天我毕业”的将来语境相合。", "去年": "语义：“去年”指已经过去的一年，与“明年春天我毕业”的将来语境冲突。", "上个星期": "搭配：“上个星期”指已经过去的一周，不能与“明年春天我毕业”并列作时间状语。", "小时候": "语义：“小时候”指童年，与“明年春天我毕业”所说的未来计划冲突。"}, "sentence_index": 0, "correct_answer": "那时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去那时吃饭。", "explanation": "这里应该用〈那里〉。“去”后面要接地点，而“那时”只表示时间。"}, {"text": "我住在那时。", "explanation": "这里应该用〈那里〉。“住在”后要接地点，而“那时”只表示时间，不能指地方。"}, {"text": "我坐在那时等你。", "explanation": "这里应该用〈那里〉。“坐在”后面要接地点，而“那时”只表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那时", "is_correct": true, "explanation": "正确：“那时”指孩子们上大学以后的某个时候，与“三年后上大学”的将来语境相合。"}, {"text": "以前", "is_correct": false, "explanation": "语义：“以前”指过去，与“三年后上大学”的将来语境冲突。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指已经过去的一天，与“三年后”的将来安排冲突。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指过去很久的时候，与“孩子们三年后上大学”的将来语境冲突。"}], "explanations": {"那时": "正确：“那时”指孩子们上大学以后的某个时候，与“三年后上大学”的将来语境相合。", "以前": "语义：“以前”指过去，与“三年后上大学”的将来语境冲突。", "昨天": "语义：“昨天”指已经过去的一天，与“三年后”的将来安排冲突。", "从前": "语义：“从前”指过去很久的时候，与“孩子们三年后上大学”的将来语境冲突。"}, "sentence_index": 6, "correct_answer": "那时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把那时放进了书包。", "explanation": "语义：“那时”是时间词，不能作“放”的对象，这里应该换成〈笔〉之类的具体物品。"}, {"text": "你要是不同意，那时我就不去了。", "explanation": "这里应该用〈那么〉。“那时”只表示时间，不能表示“这样的话”的推论。"}, {"text": "那时打了我一拳，我很生气。", "explanation": "语义：“那时”是时间词，不能作动作的施事。这里应该换成指人的词，如〈他〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那时我住在学校那时。", "corrected_sentence": "那时我住在学校。", "error_description": "错误形式：「那时我住在学校那时。」正确形式：「那时我住在学校。」“那时”只需在句首出现一次，句末重复的“那时”是多余的，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那时我还很没有工作。", "corrected_sentence": "那时我还没有工作。", "error_description": "错误形式：「那时我还很没有工作。」正确形式：「那时我还没有工作。」“很”是程度副词，不能修饰否定词“没有”，这里多出的“很”使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88635, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难看", "is_correct": true, "explanation": "“难看”指样子不好看，与“中看”意思相反。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”说价格低，与东西样子好不好看无关，不是反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力，与外观好看与否没有反义关系。"}, {"text": "新鲜", "is_correct": false, "explanation": "“新鲜”说食物或东西刚生产不久，与“中看”不构成反义关系。"}], "correct_answer": "难看", "explanations": {"难看": "“难看”指样子不好看，与“中看”意思相反。", "便宜": "“便宜”说价格低，与东西样子好不好看无关，不是反义词。", "聪明": "“聪明”形容智力，与外观好看与否没有反义关系。", "新鲜": "“新鲜”说食物或东西刚生产不久，与“中看”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88635, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难看", "is_correct": true, "explanation": "“难看”指样子不好看，与“中看”意思相反。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”指物品坚固耐用，与外观好看与否不构成反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有灰尘或污物，与“中看”不是反义关系。"}, {"text": "痛快", "is_correct": false, "explanation": "“痛快”指心里舒畅或爽快，与“中看”没有反义关系。"}], "correct_answer": "难看", "explanations": {"难看": "“难看”指样子不好看，与“中看”意思相反。", "结实": "“结实”指物品坚固耐用，与外观好看与否不构成反义关系。", "干净": "“干净”指没有灰尘或污物，与“中看”不是反义关系。", "痛快": "“痛快”指心里舒畅或爽快，与“中看”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88635, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "中看是说东西样子好看。", "primary_collocate": null, "pronunciation": "zhōng kàn", "ipa": "ʈʂʊŋ˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "这个杯子很中看，可是不好用。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子中看不中用，坐着很累。", "target_word": "中看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服很中看，价钱也不高。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那些花瓶摆在桌上很中看。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个蛋糕做得真中看，我都舍不得吃。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买的手机很中看，但是电池不行。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋很中看，穿上却很不舒服。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这盆花不太中看，不过很香。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的沙发中看又舒服，我很满意。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些玩具个个都中看，孩子特别喜欢。", "target_word": "中看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "中看不中用", "label": "复合"}], "register": "口语", "sense_fingerprint": "东西的样子好看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 花瓶 (Zipf 3.54), 摆在 (Zipf 3.87), 桌上 (Zipf 3.95)']::text[], '07e1ab4a-5687-4830-8ee0-0311191f4520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中看", "is_correct": true, "explanation": "“中看”指东西的样子好看，与后句“可是不好用”形成转折，符合语境。"}, {"text": "好用", "is_correct": false, "explanation": "语义：“好用”说的是实用，与后句“可是不好用”直接矛盾。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不能用来形容杯子的样子。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”形容味道，不能用来形容杯子的外观。"}], "explanations": {"中看": "“中看”指东西的样子好看，与后句“可是不好用”形成转折，符合语境。", "好用": "语义：“好用”说的是实用，与后句“可是不好用”直接矛盾。", "辣": "搭配：“辣”形容味道，不能用来形容杯子的样子。", "好吃": "搭配：“好吃”形容味道，不能用来形容杯子的外观。"}, "sentence_index": 0, "correct_answer": "中看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的旋律很中看。", "explanation": "这里应该用〈好听〉。“中看”只形容东西的外观，旋律要用耳朵听，应说“好听”。"}, {"text": "他的办事能力很中看。", "explanation": "这里应该用〈能干〉。“中看”只说外观样子好看，不能用来形容能力。"}, {"text": "他跑步的速度很中看。", "explanation": "这里应该用〈快〉。“中看”只形容外观样子，速度要用“快”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中看", "is_correct": true, "explanation": "“中看”指外观好看，与后句“穿上却很不舒服”形成转折。"}, {"text": "舒服", "is_correct": false, "explanation": "语义：“舒服”与后句“穿上却很不舒服”直接矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或地方，不能用来形容鞋子。"}, {"text": "好听", "is_correct": false, "explanation": "搭配：“好听”形容声音，不能用来形容鞋子的样子。"}], "explanations": {"中看": "“中看”指外观好看，与后句“穿上却很不舒服”形成转折。", "舒服": "语义：“舒服”与后句“穿上却很不舒服”直接矛盾。", "热闹": "搭配：“热闹”形容场面或地方，不能用来形容鞋子。", "好听": "搭配：“好听”形容声音，不能用来形容鞋子的样子。"}, "sentence_index": 6, "correct_answer": "中看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的味道很中看。", "explanation": "这里应该用〈鲜〉。“中看”只形容外观，味道要用“鲜”或“好”来形容。"}, {"text": "他的脾气很中看。", "explanation": "这里应该用〈温和〉。“中看”只形容外观，性格脾气不能用“中看”来说。"}, {"text": "这道数学题的解法很中看。", "explanation": "这里应该用〈巧妙〉。“中看”只形容外观，解法的精妙要用“巧妙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈买了一个中看包。", "corrected_sentence": "我妈妈买了一个中看的包。", "error_description": "“中看”作定语修饰名词时后面要加“的”，应为“中看的包”，不能说“中看包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子没中看，可是很舒服。", "corrected_sentence": "这把椅子不中看，可是很舒服。", "error_description": "“中看”是形容词，表示否定要用“不”，不能用“没”，应为“不中看”，不能说“没中看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
