INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88639, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "值得是说做这件事,花的力气不白花。", "primary_collocate": null, "pronunciation": "zhí dé", "ipa": "ʈʂɻ̩˧˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "为了家人，再辛苦也值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多年的努力，很值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然走了很远，但看到风景，我觉得值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花了三个月学做菜，真的值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了一年，终于成功，一切都值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为这份工作多花点时间，我觉得值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起早去看日出，累一点也值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为他做了这么多，值得吗？", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然花了不少钱，但很值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这一次的辛苦很值得。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不值得", "label": "否定"}, {"form": "很值得", "label": "程度"}], "register": "中性", "sense_fingerprint": "付出的辛苦、时间或金钱有回报，不白费", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "值得", "is_correct": true, "explanation": "语境：“为了家人”说明付出有回报，“值得”表示辛苦不白费，与“再辛苦也”呼应。"}, {"text": "后悔", "is_correct": false, "explanation": "语义：“后悔”是事后不满，与“为了家人”的心甘情愿相反。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”表示不满，和“为了家人”的心意相悖，不符合句意。"}, {"text": "计较", "is_correct": false, "explanation": "搭配：“计较”多指对得失斤斤计较，不能和“为了家人”这种付出搭配。"}], "explanations": {"值得": "语境：“为了家人”说明付出有回报，“值得”表示辛苦不白费，与“再辛苦也”呼应。", "后悔": "语义：“后悔”是事后不满，与“为了家人”的心甘情愿相反。", "抱怨": "语义：“抱怨”表示不满，和“为了家人”的心意相悖，不符合句意。", "计较": "搭配：“计较”多指对得失斤斤计较，不能和“为了家人”这种付出搭配。"}, "sentence_index": 0, "correct_answer": "值得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你值得去看看医生。", "explanation": "这里应该用〈应该〉。“值得”说付出有回报、有价值，不表示义务；劝人去看医生要用〈应该〉。"}, {"text": "我值得帮你。", "explanation": "这里应该用〈愿意〉。“值得”说事情有价值，不表示乐意；表示愿意帮忙要用〈愿意〉。"}, {"text": "他值得跑得很快。", "explanation": "这里应该用〈能〉。“值得”表示有价值，不表示能力；说某人能做到某事要用〈能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "值得", "is_correct": true, "explanation": "语境：“累一点也”之后说“值得”，说明看日出的辛苦有回报。"}, {"text": "错过", "is_correct": false, "explanation": "语义：“错过”是没赶上，与“起早去看日出”的目的相反。"}, {"text": "反悔", "is_correct": false, "explanation": "语义：“反悔”是推翻原来的决定，与前面主动去看日出的意愿不合。"}, {"text": "躲开", "is_correct": false, "explanation": "搭配：“躲开”是避开某人或某事，不能和“累一点”这种感受搭配。"}], "explanations": {"值得": "语境：“累一点也”之后说“值得”，说明看日出的辛苦有回报。", "错过": "语义：“错过”是没赶上，与“起早去看日出”的目的相反。", "反悔": "语义：“反悔”是推翻原来的决定，与前面主动去看日出的意愿不合。", "躲开": "搭配：“躲开”是避开某人或某事，不能和“累一点”这种感受搭配。"}, "sentence_index": 6, "correct_answer": "值得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他值得说英语。", "explanation": "这里应该用〈会〉。“值得”表示有价值，不表示能力；说某人会说某种语言要用〈会〉。"}, {"text": "学生值得遵守纪律。", "explanation": "这里应该用〈必须〉。“值得”表示有意义，不表示义务；要求学生遵守纪律时要用〈必须〉。"}, {"text": "下雨了，我值得带伞。", "explanation": "这里应该用〈得〉。“值得”说事情有价值，不表示必要；说必须带伞要用〈得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的付出真的很值得得。", "corrected_sentence": "这次的付出真的很值得。", "error_description": "错误形式：「很值得得」；正确形式：「很值得」。「值得」本身已含「得」，后面不能再多加一个「得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你为他做了这么多，值得不值得吗？", "corrected_sentence": "你为他做了这么多，值得不值得？", "error_description": "错误形式：「值得不值得吗」；正确形式：「值得不值得」。「值得不值得」已经是正反问句，后面不能再加「吗」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
