INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "价值相当;有意义,有必要做。", "primary_collocate": null, "pronunciation": "zhí dé", "ipa": "ʈʂɻ̩˧˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这本书很好，值得一看。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法值得试一试。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜值得推荐。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法值得我们学习。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老城值得去玩一天。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题值得大家认真想想。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影值得看两遍。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小事不值得生气。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不贵，值得买。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的故事值得写成一本书。", "target_word": "值得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不值得", "label": "否定"}, {"form": "很值得", "label": "程度"}], "register": "中性", "sense_fingerprint": "后接动词，表示有意义、有必要去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "值得", "is_correct": true, "explanation": "语境：“这本书很好”是推荐，“值得一看”表示有必要看。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，与“这本书很好”的推荐相反。"}, {"text": "懒得", "is_correct": false, "explanation": "语义：“懒得一看”表示不愿意看，与“这本书很好”的推荐语气相矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再去做，与“很好”的推荐语气相反。"}], "explanations": {"值得": "语境：“这本书很好”是推荐，“值得一看”表示有必要看。", "拒绝": "语义：“拒绝”是不接受，与“这本书很好”的推荐相反。", "懒得": "语义：“懒得一看”表示不愿意看，与“这本书很好”的推荐语气相矛盾。", "放弃": "语义：“放弃”是不再去做，与“很好”的推荐语气相反。"}, "sentence_index": 0, "correct_answer": "值得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我值得去超市。", "explanation": "这里应该用〈要〉。“值得”表示有价值，不表示打算；说准备去某地要用〈要〉。"}, {"text": "她值得这个道理。", "explanation": "这里应该用〈懂得〉。“值得”说事情有价值，不表示理解；说明白某个道理要用〈懂得〉。"}, {"text": "她值得帮我。", "explanation": "这里应该用〈愿意〉。“值得”说事情有价值，不表示乐意；表示愿意帮忙要用〈愿意〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "值得", "is_correct": true, "explanation": "语境：“看两遍”说明这部电影有重看的价值，“值得”表示有价值。"}, {"text": "厌烦", "is_correct": false, "explanation": "配价：“厌烦”的主语应是人，“这部电影”不能作“厌烦”的主语。"}, {"text": "抗拒", "is_correct": false, "explanation": "配价：“抗拒”要求有人主动抵抗，不能以电影为主语。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是记不住，与“看两遍”的建议相反。"}], "explanations": {"值得": "语境：“看两遍”说明这部电影有重看的价值，“值得”表示有价值。", "厌烦": "配价：“厌烦”的主语应是人，“这部电影”不能作“厌烦”的主语。", "抗拒": "配价：“抗拒”要求有人主动抵抗，不能以电影为主语。", "忘记": "语义：“忘记”是记不住，与“看两遍”的建议相反。"}, "sentence_index": 6, "correct_answer": "值得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我值得弹钢琴。", "explanation": "这里应该用〈会〉。“值得”说事情有价值，不表示能力；说自己会弹某种乐器要用〈会〉。"}, {"text": "我值得交作业。", "explanation": "这里应该用〈必须〉。“值得”说事情有价值，不表示义务；说自己必须做某事要用〈必须〉。"}, {"text": "我值得进去。", "explanation": "这里应该用〈可以〉。“值得”说事情有价值，不表示许可；说自己能够进入要用〈可以〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划很值得很讨论。", "corrected_sentence": "这个计划很值得讨论。", "error_description": "错误形式：「很值得很讨论」；正确形式：「很值得讨论」。「很」修饰的是「值得」，不能再修饰动作动词「讨论」，多出的一个「很」不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件小事不值得得你生气。", "corrected_sentence": "这件小事不值得你生气。", "error_description": "错误形式：「不值得得你生气」；正确形式：「不值得你生气」。「值得」本身已含「得」，中间不能再多加一个「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
